window.__D("text/tikkunei-zohar/c005",{"p":[[9500011223,"<p>(תהלים לג יד) מִ מֲּכוֹן שִׁ בְתּוֹ הִ שְׁגִּיחַ, (שם קמד טו) אַשְׁרֵי הָעָם שֶׁכָּכָ\"ה לּוֹ בְּגִימַטְרִיָּא מֹשֶׁ\"ה, אַשְׁרֵי הָעָם שֶׁיהו\"ה אלהי\"ו, דַּעֲלֵיהּ אִתְּמַר (קהלת א ד) דּוֹר הוֹלֵךְ וְדוֹר בָּא, וְלֵית דּוֹר פָּחוּת מִשִּׁשִּׁים רִבּוֹא, וַעֲלֵיהּ אִתְּמַר (תהלים קה ח) דָּבָר צִוָּה לְאֶלֶף דּוֹר, וְאִתְפַּשְׁטוּתֵיהּ הוּא בְכָל דָּרָא וְדָרָא, בְכָל צַדִּיק וְחָכָם דְּמִתְעַסֵּק בְּאוֹרַיְיתָא, עַד שִׁתִּין רִבּוֹא, לְאַשְׁלָמָא לְכֻלְּהוּ מִפְּגִימוּ דִלְהוֹן, וְרָזָא דְמִלָּה (ישעיה נג ה) וְהוּא מְחוֹלָל מִפְּשָׁעִנוּ, דְאִיהוּ שָׁקִיל לְכֻלְּהוּ, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין אִשָּׁה אַחַת יָלְדָה שִׁשִּׁים רִבּוֹא, וּמַנּוּ מֹשֶׁה דְשָׁקִיל כְּשִׁשִּׁים רִבּוֹא, וּבְגִין דָּא אִתְּמַר עֲלֵיהּ דּוֹר הוֹלֵךְ (ודור בא) לְהַהוּא עָלְמָא, וְדוֹר בָּא אִיהוּ יֵיתֵי כְּמִלְּקַדְמִין.</p>\n<p>וְעוֹד (בראשית ד כה) כִּי שָׁת לִי אלהי\"ם זֶרַע אַחֵר, שֵׁת אִתְפַּשְׁטוּתֵיהּ הֲוָה עַד יַעֲקֹב, דְּפָרַח בֵּיהּ י' מִן שִׁית וְאִשְׁתָּאַר שֵׁת, וְאִשְׁתָּאַר יַעֲקֹב עָקֵב, דְּיַעֲקֹב דִּיּוֹקְנֵיהּ דְּאָדָם קַדְמָאָה הֲוָה, כְּמָה דְאוּקְמוּהָ שׁוּפְרֵיהּ דְּיַעֲקֹב כְּעִין שׁוּפְרֵיהּ דְּאָדָם הָרִאשׁוֹן, וּבְגִין הַאי י' אִתְּמַר (תהלים קיח כא) אֶבֶן מָאֲסוּ הַבּוֹנִים, דְּאִינוּן אַבְרָהָם וְיִצְחָק, דְּאִתְּמַר בָּהּ לְגַבֵּי אָדָם (בראשית ג טו) הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, דַּהֲווֹ יָדְעִין דַּהֲוָה עֲתִידָה לְאַלְקָאָה מֵחִוְיָא, וּבְגִין דָּא אִתְּמַר בָּהּ אֶבֶן מָאֲסוּ הַבּוֹנִים.</p>\n<p>אָמְרוּ לֵיהּ חַבְרַיָּא, וְהָא אָמַר רַבִּי פִּנְחָס דְּאָת י' אִיהִי בְּיִצְחָק, אָמַר וַדַּאי י' עִלָּאָה אִיהִי מִן חָכְמָה, וְהַאי אִיהִי י' זְעִירָא, וּבְגִין דָּא אִתְּמַר בָּהּ עָקֵב, הֲדָא הוּא דִכְתִיב וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, וְדָא כַּף יֶרֶךְ יַעֲקֹב, דְּאִתְּמַר בָּהּ (בראשית לב כו) וַיִּגַּע בְּכַף יְרֵכוֹ, וְאִתְּמַר בֵּיהּ וְהוּא צֹלֵעַ עַל יְרֵכוֹ, וְדָא י' מִן אדנ\"י, וְאִיהוּ י' מִן הוהי, דְּבָהּ (שמות ג ו) וַיַּסְתֵּר מֹשֶׁה פָּנָיו כִּי יָרֵא מֵהַבִּיט לַאֲתַר דְּחָב בִּדְקַדְמֵיתָא, קֳדָם דְּיֵיתֵי בְגִלְגּוּלָא, כֵּיוָן דְּאָתָא יַעֲקֹב תַּמָּן, מִיָּד (בראשית לג יז) וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת, בַּת י', מִיָּד אִשְׁתַּלִּים י' בְּעָקֵב וְאִתְעֲבִיד יַעֲקֹב, וְדָא אִיהוּ דְאָמַר קְרָא (שם טו) וַיָּבֹא יַעֲקֹב שָׁלֵם, וּלְבָתַר אָתָא מֹשֶׁה וְהָפַךְ הוהי מִדִּינָא לְרַחֲמֵי וְאִתְחַזַּר יהו\"ה, וְדָא אִיהוּ רָזָא אֶבֶן מָאֲסוּ הַבּוֹנִים, בְּהַהוּא זִמְנָא אָמְרוּ כֻּלְּהוּ מֵאֵת יהו\"ה הָיְתָה זֹּאת כו',</p>\n<p>(אמר המגיה זה הלשון מצאתי בספר אחר)</p>\n<p>בְּרֵאשִׁית לֵית רֵאשִׁית אֶלָּא נְשָׁמָה, אָמַר לֵיהּ מֵהָכָא אִשְׁתְּמוֹדָע דִּבְהַאי אוֹת דִּבְרִית מִילָה חָאב אָדָם וְכָל דָּרִין דְּאָתוּ אַבַּתְרֵיהּ וְדָא אִיהוּ דְאָמַר קְרָא פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים בְּגִין דְּמַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם, אָמַר לֵיהּ אִשְׁתְּכַח דְּשֵׁת אִיהוּ גִלְגּוּלָא דְאָדָם וְהֶבֶל דְּאִתְּמַר בֵּיהּ בְּשַׁגַּם הוּא בָשָׂר בְּשַׁגַּם זֶה הֶבֶל וְרָזָא דְמִלָּה אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה, וָאֵדָעֲךָ בְּשֵׁם, אָז, הַהוּא דְאִתְּמַר בֵּיהּ אָז יָשִׁיר משֶׁה, בְּשֵׁם יהו\"ה וָאֵדָעֲךָ בְּשֵׁם, בִּתְרֵין שְׁמָהָן מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ וְאִתְּמַר בֵּיהּ הוּחַל דְּמִתַּמָּן הוּשְׁתַּת עָלְמָא.</p>\n<p>אַדְהָכִי הָא רַבִּי שִׁמְעוֹן וְרַבִּי יִצְחָק וְרַבִּי יוּדָאִי וְרַבִּי יְהוּדָה וּשְׁאָר חַבְרַיָּא, פָּגְעוּ בְּרַבִּי אֶלְעָזָר וְחַבְרוֹי דַהֲווֹ עִמֵּיהּ, אָמַר לוֹן בְּמַאי עַסְקִיתּוּ אָמְרוּ לֵיהּ בְּרָזָא דְגִלְגּוּלָא דְאָדָם וְהֶבֶל, אָמַר וַדַּאי בְּרָזָא עִלָּאָה דַהֲוִינָא מִשְׁתַּדְּלִין, הֲוִיתוּן אַתּוּן מִשְׁתַּדְּלִין.</p>\n<p>פָּתַח כְּמִלְּקַדְמִין וְאָמַר יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ וכו', דָּא אָדָם וְהֶבֶל, בְּמַחֲשָׁבָה וּבְמַעֲשֶׂה חָאבוּ, כְּמָה דְאוּקִימְנָא לְעֵילָא, וּמַאי נִיהוּ מַחֲשָׁבָה וּמַעֲשֶׂה, אַבָּא וְאִימָא חָכְמָה וּבִינָה עֲלַיְהוּ אִתְּמַר כֻּלָּם בְּחָכְמָה עָשִׂיתָ הֲרֵי עֲשִׂיָּה בְּגִין דְּתַמָּן כֹּחַ מָה, דָּא חָכְמָה דְאִתְפַּלֵּג לִתְרֵין סִטְרִין, מָ\"ה אִיהוּ אָדָם מַחֲשָׁבָה חָשַׁב מָ\"ה, מָ\"ה אָדָם, תִּשְׁכַּח דְּאִיהוּ אָדָם מַחֲשָׁבָה, בִּינָה, תַּמָּן י\"ה אַבָּא וְאִמָּא וּבֵן בְּגַוַּיְיהוּ עַמּוּד דְּסָמִיךְ לוֹן, הַהוּא דְאִתְּמַר בֵּיהּ בְּשַׁגַּם הוּא בָשָׂר, בְּשַׁגַּם זֶה הֶבֶל, דְּאִיהוּ משֶׁה, מִתַּמָּן הֲוָה, וְהָכִי אוֹקְמוּהוּ קַדְמָאִין בְּשַׁגַּם זֶה משֶׁה, הֶבֶל אִתְקְרִי עַל שֵׁם ב' מִן בְּרֵאשִׁית, ל' לְעֵינֵי כָּל יִשְׂרָאֵל, ה' חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה דְעָתִיד לְאִתְיַיהֲבָא עַל יְדֵיהּ, וְדָא אִיהוּ הֶבֶ\"ל, דְּאִתְּמַר בֵּיהּ כִּי עַל כָּל מוֹצָא פִי יהו\"ה יִחְיֶה הָאָדָם.</p>\n<p>וְאִית הֶבֶל דְּסִטְרָא אָחֳרָא דְאִתְּמַר בֵּיהּ הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתּוּעִים וְדָא הוּא הֶבֶל דְּנַבְלוּת הַפֶּה וּפִתְגָּמִין בְּטֵלִין דְּלֵית בְּהוּ תּוֹעֶלֶת כְּלָל, וּבְגִין דָּא יֶשׁ הֶבֶל כו' שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים וְיֵשׁ הֶבֶל אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים, מַאי הָרְשָׁעִים דָּא סמא\"ל וְנָחָשׁ ש דְּמשֶׁה אִיהִי תְּלַת עַנְפִין דִּשְׁרָשָׁא דְאִילָנָא וְדָא ש מִן שֵׁת, מ\"ה מִן משֶׁה דָא אָדָם, דְּאִיהוּ בְּדִיּוֹקְנָא דְאָדָם דִּלְעֵילָא, וְדָא אִיהוּ מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ וְהַאי מ\"ה, (ה) תּוֹרַת יהו\"ה תְּמִימָה, ה' חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה דְאִתְיְיהִיבוּ לֵיהּ בְּאַרְבְּעִין יוֹמִין וְאַרְבְּעִין לֵילְוָון דְּלֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה.</p>\n<p>וּבְגִין דְּעָקַר ש דְּאִיהִי שְׁרָשָׁא דְאִילָנָא מֵאַתְרָה וְאִתְעֲבִידַת תְּלַת עַנְפִין דְּאִינוּן תְּלַת זַיְינִין כְּגַוְונָא דָא ש, דְּזְרַע דְּאִיהוּ יוֹרֶה כְּחֵץ, אִתְעֲבִיד ז', דִּתְלַת טִפִּין אִתְפַּשְׁטוּ וְאִתְעֲבִידוּ שַׁרְבִיטִין, וּבְגִין דְּאַעֲקַר לוֹן מֵאַתְרַיְיהוּ וּמַה דַּהֲוָה שָׁרְשָׁא חֲדָא עִקְרָא חֲדָא, אִתְפַּלְגוּ לִתְלַת, הָכִי אִיהוּ אִזְדַּרִיק בִּתְלַת גִּלְגּוּלִין, חַד בְּנֹחַ, וּתְרֵין בְּשֵׁם וְיְפֶת, וּבְגִין דְּכַד אָתָא נֹחַ לָא בָעָא רַחֲמֵי עַל אִילֵּין גּוּבְרִין דְּטוֹפָנָא אִתְבַּיַּישׁ לְבָתַר וְאָמַר וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ, וְשֵׁם לַאו לְמַגָּנָא הֲוָה קֹבֵעַ מִדְרָשׁוֹת, וְיֶפֶת אִתְּמַר בֵּיהּ יַפְתְּ אלהי\"ם לְיְפֶת וְיִשְׁכּוֹן בְּאָהֳלֵי שֵׁם, בְּאִלֵּין תְּלַת הֲוָה בָּעֵי לְאִשְׁתַּרְשָׁא בְּשָׁרְשׁוֹי חָמָא דְלָא אַצְלַח, אַעֲקַר לֵיהּ מִתַּמָּן וְנָטַע לֵיהּ לְבָתַר יְחִידָאָה.</p>\n<p>אֲבָל אָדָם אִתְנַטַע בִּתְלַת אֲבָהָן וְאִצְטַרִיף וְאִתְלַבַּן בְּהוֹן וְאִשְׁתַּרַשׁ בְּשָׁרְשׁוֹי וְאַצְלַח, מִיַּד אָתָא משֶׁה דְאִיהוּ בְּרֵיהּ דְּאָדָם וְיָהֵיב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא עַל יְדוֹי לְאַשְׁקָאָה אִילָנָא לְאִתְגַּדְלָא בְּשָׁרְשׁוֹי וְעַנְפּוֹי בְּהַהוּא זִמְנָא אִתְתַּקַּן אִילָנָא דְעָקַר, חוֹבָא דְחָאב בְּאִילָנָא הָכָא תַּקִּין כֹּלָּא, לְבָתַר דְּאִתְכַּנִּישׁ משֶׁה מֵעָלְמָא אִתְּמַר בֵּיהּ וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְאִתְּמַר בֵּיהּ הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן סוֹבֵב סוֹבֵב הוֹלֵךְ הָרוּחַ תְּלַת זִמְנִין סוֹבֵב לָקֳבֵל תְּלַת גִּלְגּוּלִין דְּרוּחֵיהּ אַסְחִיר תַּמָּן, מִיַּד דְּאַשְׁכַּח תַּמָּן לְשַׁרְיָא, מַה כְּתִיב וְעַל סְבִיבוֹתָיו שָׁב הָרוּחַ.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר אִשְׁתְּמוֹדָע הָכָא רָזָא עִלָּאָה, מֵרוּחָא דְקוּדְשָׁא דִלְעֵילָא דְאִיהוּ בֶּן י\"ה, דְּאַסְחַר לִימִינָא וּשְׂמָאלָא וְעַמּוּדָא דְאֶמְצָעִיתָא וּלְבָתַר לִתְלַת תַּתָּאִין דְּאִינוּן צַדִּיק וּתְרֵי סַמְכֵי קְשׁוֹט, וְהָכִי אָדָם עִלָּאָה אוּף הָכִי בְּשִׁית סִטְרִין, וְדָא רָזָא דִבְּרֵאשִׁית, בָּרָא שִׁית לְעֵילָא, בָּרָא שִׁית לְתַתָּא, י' דְּפָרַח.</p>\n<p>מִן שֵׁת אִיהוּ י' דְּיַעֲקֹב, דְּפָרַח י' מִינֵיהּ וְאִשְׁתָּאַר עָקֵב, וְדָא אִיהוּ רָזָא דְהוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, וּבְגִין דָּא כַּד פָּרַח י' מִן שֵׁת מַה כְּתִיב בֵּיהּ כִּי שָׁת לִי אלהי\"ם זְרַע אַחֵר, אַחֵר גָּרִים דְּאִתְאֲבַד י' דְּאִיהִי זְרַע מִן שֵׁת, וְרָזָא דְשֵׁת כֹּל שַׁתָּה תַחַת רַגְלָיו, כֹּל וַדַּאי דְאִיהוּ זְרַע אוֹת בְּרִית קֹדֶשׁ, בְּהַהוּא זִמְנָא אָתָא משֶׁה בִּתְרֵין לוּחִין דְּאִינוּן ב' מִן בְּרֵאשִׁית וְכַסִּי עַל שֵׁת וְאִתְעֲבִיד בּשֵׁת, וּבְאָן אֲתַר כַּסִּי ב' עַל שֵׁת בְּזִמְנָא דְאָמַר וַיַּסְתֵּר משֶׁה פָּנָיו וְאָת י' אִיהִי תְמוּנַת יהו\"ה, בִּשְׂכַר וַיַּסְתֵּר משֶׁה פָּנָיו כִּי יָרֵא מֵהַבִּיט, וּתְמוּנַת יהו\"ה יַבִּיט, וְאִשְׁתַּלִּים שֵׁת.</p>\n<p>וְהַיְינוּ בְּרֵאשִׁית בָּרָא אִשְׁתַּלִּים בְּשִׁית, שֵׁת סִיּוּמָא דְאַלְפָא בֵּיתָא, אַב רֵישָׁא דְאַלְפָא בֵּיתָא, וְדָא הוּא רָזָא דְאַ\"תְּ בַּ\"שׁ, הָכָא אִתְתַּקַּן אָב עִם בֵּן תַּרְוַיְיהוּ דָא עַל גַּב דָּא, בְּכָל אֲתַר דְּאַזְלוּ לָא אִתְפָּרְשׁוּ דָא מִן דָּא, בְּרֵאשִׁית תַּמָּן אַ\"תּ בַּ\"שׁ, אַ\"ב שֵׁ\"ת, אִשְׁתָּאַר ר' י' מִן בְּרֵאשִׁית, עֲלֵיהּ אִתְּמַר וַיַּרְא רֵאשִׁית לוֹ, דְּאִיהוּ רֵאשִׁית חָכְמָה יִרְאַת יהו\"ה, כְּגַוְונָא דָא בֵּן בְּגוֹ אַבָּא, וַיַּרְא רֵאשִׁית לוֹ, מִתַּמָּן יָרִית לוֹ נִשְׁמָתָא וְאִתְקְרִי רֵאשִׁית לוֹ כִּשְׁמֵיהּ, וְאִתְקְרִי אָדָם כִּשְׁמֵיהּ בִּתְלַת אֲבָהָן דְּאִינוּן ש, אָתָא אָדָם בְּמשֶׁה, וּבְמשֶׁה כָּלִיל כֹּלָּא, וּבְגִין דָּא ש מִן משֶׁה שָׁקִיל ש' לִתְלַת אֲבָהָן, מ\"ה דִילֵיהּ כְּגַוְונָא דְאָדָם קַדְמָאָה, מַרְכְּבָתָא שְׁלֵימָתָא הֲוַת בְּמשֶׁה בִּלְחוּדוֹי, כְּמָה דַהֲוָה בִּתְלַת אֲבָהָן, וְאָדָם עִלָּאָה הֲוָה בְּמשֶׁה, תְּלַת עַנְפִין דְש אַרְיִה שׁוֹר נֶשֶׁר, מַ\"ה וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, וְאִתְּמַר בֵּיהּ משֶׁה משֶׁה תְּרֵין זִמְנִין לְקַיְימָא בֵּיהּ מַה שֶּׁהָיָה הוּא שֶׁיִּהְיְה וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה דָא אָדָם הָרִאשׁוֹן, אִשְׁתַּטְחוּ כֻּלְּהוּ קַמֵּיהּ וְאָמְרוּ זַכָּאָה חוּלְקָנָא דְאַעֲרַעְנָא בָּךְ לְמִנְדַּע רָזִין עִלָּאִין טְמִירִין דְּעַתִּיק יוֹמִין. אָמַר רַבִּי אֶלְעָזָר אִשְׁתַּמוֹדָע מֵהָכָא דְמשֶׁה מֵאַתְווֹי מַשְׁמַע דְּאִיהוּ הֶבֶל וְאִיהוּ שֵׁת וְאִיהוּ משֶׁה, וְאִתְפַּשְׁטוּתֵיהּ דְּמשֶׁה בְּכָל דָּרָא וְדָרָא וּבְכָל צַדִּיק וְצַדִּיק, וְאִיהוּ אָזִיל בִּתְלַת תְּלַת, וּבְכָל תְּלַת דְאִיהוּ רָכִיב אִתְּמַר בְּהוֹן לֹא יָמוּשׁוּ מִפִּיךָ וּמִפִּי זַרְעֲךָ וּמִפִּי זְרַע זַרְעֲךָ, מֵהָכָא אִשְׁתְּמוֹדָע דְּאִיהוּ לָא אִשְׁתַּכַּח אֶלָּא בַּאֲתַר דְּאִית בֵּיהּ אוֹרַיְיתָא, וּבְגִין דָּא זִכְרוּ תּוֹרַת משֶׁה עַבְדִּי.</p>\n<p>אָמַר לֵיהּ רַבִּי יְהוּדָה אִתְפַּשְׁטוּתָא דִילֵיהּ בִּבְנֵי נָשָׁא אִית לֵיהּ שִׁעוּרָא, אָמַר לֵיהּ אִין, עַד שִׁתִּין רִבּוֹא, וְרָזָא דְמִלָּה דּוֹר הוֹלֵךְ וְדוֹר בָּא, וְאוֹקְמוּהָ קַדְמָאִין דְּלֵית דּוֹר פָּחוֹת מִשִּׁשִּׁים רִבּוֹא, וּבְגִין דָּא אִתְּמַר בֵּיהּ אִשָּׁה אַחַת יָלְדָה בְּמִצְרַיִם שִׁשִּׁים רִבּוֹא בְּכֶרֶס אֶחָד, וּמַנּוּ דָא משֶׁה דְאִיהוּ שָׁקוּל כְּשִׁשִּׁים רִבּוֹא מִיִּשְׂרָאֵל, אָמַר לֵיהּ רַבִּי שִׁמְעוֹן בְּרִיךְ בְּרִי לְעַתִּיק יוֹמִין:</p>\n<p>וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַיהו\"ה (בראשית ד ג), מֵאָן אֲתַר אַיְיתֵי לֵיהּ, מִקֵּץ יָמִים, מִשִּׁיּוּרִין דִּילֵיהּ, כְּגוֹן בַּר נַשׁ דְּאִיהוּ בְּסוֹף יוֹמוֹי חָזַר בִּתְיוּבְתָּא, כַּד לָא אִית לֵיהּ חֵילָא לְמֶעֱבַד טַב וּבִישׁ, וּבְעוּלְמוֹי בְּתוּקְפֵיהּ לָא תָב, כְּמָה דְאוּקְמוּהוּ (ויקרא יט לב) מִפְּנֵי שֵׂיבָה תָּקוּם, וּבְגִין דָּא וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, אֲבָל הֶבֶל מִבְּכוֹרוֹת צֹאנוֹ אַיְיתֵי לֵיהּ קָרְבָּנָא מִשַּׁפִּירוּ דִילֵיהּ, וּבְגִין דָּא וַיִּשַׁע יהו\"ה אֶל הֶבֶל. וְעוֹד אֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, בְּגִין דְּקָרְבָּנָא דִילֵיהּ הֲוָה מֵהַהוּא אֲתַר דְּאִקְרֵי עִִרְוָה. וּמַאי הֲוָה פִשְׁתִּים, דְּאִתְּמַר בֵּיהּ (שמות כח מב) וַעֲשֵׂה לָהֶם מִכְנְסֵי בָד לְכַסּוֹת בְּשַׂר עִִרְוָה.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, דְּאִתְכַּסִּי בֵּיהּ בְּשַׂר עִִרְוָה טַב אִיהוּ, אָמַר לֵיהּ בְּרִי לַאו כָּל</p>"],[9500011224,"<p>עֲרָיוֹת שָׁוִין, הַאי לָא קְרִיב קָרְבָּנָא דָא אֶלָּא לְקָרְבָא עִִרְוָה דִילֵיהּ לַה', דְּאִתְּמַר בֵּיהּ (ויקרא יח ו) אִישׁ אִישׁ אֶל כָּל שְׁאֵר בְּשָׂרוֹ לֹא תִקְרְבוּ לְגַלּוֹת עִִרְוָה אֲנִי יהו\"ה, וּמַאי עִִרְוָה דִילֵיהּ זוּהֲמָא בִּישָׁא עָרְלָה, נוּקְבָא דְעָרְלָה, הַהִיא דְאִתְּמַר בָּהּ אָדָם הָרִאשׁוֹן מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה, וּמַאי נִיהִי אִימָּא דְעִרְבוּבְיָא בִּישָׁא, אִיבָּא דְאִלָנָא דְטוֹב וָרָע, דְּאִתְּמַר בָּהּ (בראשית ג ו) וַתִּקַּח מִפִּרְיוֹ וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ, וּמַאי נִיהִי לִילִית, מִתַּמָּן קָא אַתְיָין עִרֶב רַב דְּאִנּוּן מְעוּרָבִין בְּיִשְׂרָאֵל, דְּאִתְּמַר בְּהוֹן (ישעיה א ד) הוֹי גּוֹי חוֹטֵא, דְאִינוּן זֶרַע מְרֵעִים בָּנִים מַשְׁחִיתִים וכו', וְאָמְרוּ אֵלֶּה אלהי\"ך יִשְׂרָאֵל לְעִִגְלָא, וּבְגִין דָּא (בראשית ד ה) וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה.</p>\n<p>וְהָא קוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר בֵּיהּ (תהלים קמה ט) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו, וְאִתְּמַר בֵּיהּ (יחזקאל יח לב) כִּי לֹא אֶחְפּוֹץ בְּמוֹת הַמֵּת, וְקַבִּיל לוֹן, כָּל שֶׁכֵּן לְקָרְבָּנָא דְקַיִן, אֶלָּא דַהֲוָה רְעוּתֵיהּ לְבִישׁ כְּמָה דְאִתְּמַר, אֲבָל הֶבֶל הֲוָה רְעוּתֵיהּ בְּקָרְבָּנָא דִילֵיהּ, לְקָרְבָא שְׁכִינְתָּא לְהַהוּא דְאִתְּמַר בֵּיהּ (דניאל ז ט) וְעַתִּיק יוֹמִין יְתִיב לְבוּשֵׁיהּ כִּתְלָג חִוָּור וּשְׂעַר רֵישֵׁיהּ כַּעֲמַר נְקֵי, בְּמַאי, בְּהַהוּא דְקָרִיב מִבְּכוֹרוֹת צֹאנוֹ וּמֵחֶלְבֵהֶן, וּבְגִין דָּא וַיִּשַׁע יהו\"ה אֶל הֶבֶל וְהָא אִתְּמַר.</p>\n<p>וּמִיָּד דְּלָא אִתְקַבַּל קָרְבָּנָא דְקַיִן, וַיִּחַר לְקַיִן מְאֹד, וַיֹּאמֶר יהו\"ה לְקַיִן לָמָּה חָרָה לָךְ דְּלָא מִתְקַבַּל קָרְבָּנָךְ, אִם תֵּטִיב עוֹבָדָךְ בְּגִלְגּוּלָא, שְׂאֵת לָךְ בְּעָלְמָא, וְתִתְקַבַּל בִּתְיוּבְתָּא, וְאִם לַאו לַפֶּתַח חַטָּאת רוֹבֵץ, אָמַר רַבִּי אֶלְעָזָר הָכָא לָא צָרִיךְ לְאִתְכַּסְיָא רָזָא, מַאי שְׂאֵ\"ת, וְלָא אָתֵינָא לִדְרָשָׁא בְּהַאי קְרָא, אֶלָּא דְהָא שְׂאֵת מַשָּׂא אִיהוּ וּבְהִפּוּךְ אַתְוָון, שְׂאֵ\"ת אִיהוּ אֵשֶׁ\"ת, הָכָא רָמִיז דְּעָבַר עַל (ויקרא יח כ) וְאֶל אֵשֶׁת עֲמִיתְךָ לֹא תִתֵּן שְׁכָבְתְּךָ כו', דְּאָתָא עַל תְּאוֹמָתוֹ שֶׁל הֶבֶל, וְדָא אִיהוּ (בראשית ד ח) וַיָּקָם קַיִן אֶל הֶבֶל, קָם עַל תְּאוֹמָתוֹ, וּלְבָתַר קָטִיל לְבַעִִלָהּ, כְּגַוְונָא דְמִצְרִי, וְרָזָא דְמִלָּה (שמות ב יב) וַיִּפֶן כֹּה וָכֹה, וְאָמְרוּ קַדְמָאִין מַאי וַיִּפֶן כֹּה וָכֹה, אֶלָּא רָאָה מֶה עָשָׂה בְּבַיִת</p>"],[9500011225,"<p>וּמֶה עָשָׂה בַשָּׂדֶה, וְלֵית שָׂדֶה אֶלָּא אִשָּׁה, כְּמָה דְאַתְּ אָמַר (דברים כב כז) כִּי בַשָּׂדֶה מְצָאָהּ, הֲדָא הוּא דִכְתִיב (בראשית ד ח) וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה, וַיִּפֶן כֹּה וָכֹה, אִסְתַּכַּל אִם הֲוָה בֵּיהּ מִסִּטְרָא דְטוֹב, דִּלְזִמְנִין אִתְפָּרַשׁ טוֹב מִן רָע וּמִתַּמָּן אִינוּן גֵּרִים, וּבְגִין דָּא אִסְתַּכַּל מִכָּל סִטְרָא עַד שִׁתִּין רִבּוֹא, וְלָא חָזָא תַמָּן גִּיּוֹרָא דְנָפִיק מִנֵּיהּ, וַיַּךְ אֶת הַמִּצְרִי.</p>\n<p>וּלְבָתַר מַה כְּתִיב וְאִם לֹא תֵיטִיב, אַל תִּקְרֵי וְאִם אֶלָּא וְאֵם, דְּאִיהוּ (שם מט ג) יֶתֶר שְׂאֵת וְיֶתֶר עָז, לַפֶּתַח חַטָּאת רֹבֵץ, מַאי רוֹבֵץ, אֶלָּא (שמות כג ה) כִּי תִרְאֶה חֲמוֹר שֹׂנַאֲךָ רוֹבֵץ כו', דְּאִיהוּ לָא יָכִיל לְמִסְבַּל עַל כְּתֵפוֹי חֻמְרָא דְאוֹרַיְיתָא, לָא יָכִיל לְמִסְבַּל עֲלֵיהּ עוֹל מַלְכוּת בְּגָלוּתָא, וְחָדַלְתָּ מֵעֲזוֹב לוֹ, הָכָא אַחֲזֵי לְקַיִן דַּעֲתִידִין לְמֶהֱוִי יִשְׂרָאֵל בְּדוֹחֲקָא בְגָלוּתָא, עָנִי וְרוֹכֵב עַל חֲמוֹר, דִּיְהוֹן כַּחֲמוֹר מַשָּׂאוֹי עַל כְּתֵפוֹי, מֵעוֹל הַמַּס בְּגָלוּתָא וּמִכּוֹבֶד הַמְּלָאכָה, וְדָא אִיהוּ רוֹבֵץ תַּחַת מַשָּׂאוֹי בְגָלוּתָא, וּבְנוֹי דְּקַיִן דַּהֲווֹ עֲתִירִין וְתַקִּיפִין כַּמְּלָכִים בְּתוּקְפָא סַגִּיא, וּבְגִין דָּא אָמַר הֲלֹא אִם תֵּטִיב שְׂאֵת, הֲלֹא אִם תֵּטִיב לְמֶהֱוֵי שְׂאֵת לַעֲנִיֵּי יִשְׂרָאֵל דְּאִינוּן כְּבֵדִים בְּמַשָּׂא כָבֵד (יכבדו ממני), אֲנָא אַסְבִּיל לִבְרִיךְ בְּעָלְמָא, וּמַאֲרִיךְ עֲלַיְיהוּ, וְאִם לַאו, לַפֶּתַח חַטָּאת רֹבֵץ, לְתַרְעָא דְגֵיהִנָּם אִתְפַּתְּחַת, לְנַטְלָא נוּקְמָא מִנָּךְ וּמִבְּרָךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּרִיךְ בְּרִי לְעַתִּיק יוֹמִין, דְּהָא רוּחַ קַדִּשָׁא אִתְעַר לְגַבָּךְ, לְגַלָּאָה הָכָא חִדּוּשִׁים דְּלָא אִשְׁתְּמוֹדְעוּ עַד הַשְׁתָּא, אָמַר וַדַּאי דָּא אִיהוּ (בראשית ד י) קוֹל דְּמֵי אָחִיךָ צוֹעֲקִים אֵלַי, אִינוּן דָּמִים דְּיִשְׂרָאֵל, דַּעֲתִידִין לְמִגְזַל לוֹן בְּנוֹי דְּקַיִן עִרֶב רַב רַשִּׁיעַיָּיא חַיָּיבַיָּא בְגָלוּתָא, וְדָא אִיהוּ (שם ו יג) כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם, וְדָא הוּא קָטוֹלָא דְקַיִן לְהֶבֶל דְּעָנִי חָשׁוּב כַּמֵּת.</p>\n<p>וַיְהִי</p>"],[9500011226,"<p>מִקֵּץ יָמִים וְגוֹמֵר, פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר מַאי מִקֵּץ יָמִים, אֶלָּא מֵהַהוּא אֲתַר דְּעָתִיד לְמֵימָר בֵּיהּ (שם ו יג) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, (איוב כח ג) קֵץ שָׂם לַחֹשֶׁךְ, וְתִרְגֵּם יוֹנָתָן בֶּן עוּזִיאֵל קֵץ כָּל בָּשָׂר, חֲבִילוּ דְכָל בִּשְׂרָא, מַלְאֲכֵי חַבָּלָה, חָמָא דַעֲתִידִין לְמֵיפַּק מִנֵּיהּ מְחַבְּלִים כְּרָמִים, דְּאִינוּן יִשְׂרָאֵל דְּאִתְּמַר בְּהוֹן (ישעיה ה ז) כִּי כֶרֶם יהו\"ה צְבָאוֹ\"ת בֵּית יִשְׂרָאֵל, בְּגִין כַּךְ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, וְחָמָא דַעֲתִידִין לְמֵיפַק מֵהֶבֶל כַּמָּה צַדִּיקַיָּא, בְּגִין דָּא וַיִּשַׁע יהו\"ה אֶל הֶבֶל וְאֶל מִנְחָתוֹ.</p>\n<p>וְהָא בְּשַׁעִִתָּא דְאִתְיְלִיד קַיִן אִתְּמַר בֵּיהּ קָנִיתִי אִישׁ אֶת יהו\"ה, וְלָא הֲוָה הָכִי, מִשּׁוּם דְּלָא אִתְבַּסְמַת, וְחִוְיָא תַּקִּיפָא אַטִּיל בָּהּ זוּהֲמָא דְּדִינָא קַשְׁיָא, וּבְגִין דָּא לָא הֲוָה אִתְבַּסְמַת, וְכַד קַיִן מִסִּטְרָא דְנוּקְבָא נָפַק תַּקִּיפָא קַשְׁיָא בְּדִינוֹי, כֵּיוָן דְּנָפַק דָּא אִתְחַלְשַׁת אִיהִי וְאִתְבַּסְמַת, בָּתַר דָּא וְאַפִּיקַת אָחֳרָא בְּסִימָא יַתִּיר, וְסָלִיק קַדְמָאָה דַהֲוָה תַּקִּיף קַשְׁיָא עַל אָחֳרָא, דְּהָא כָּל דִּינִין אִתְעָרוּ עִמֵּיהּ.</p>\n<p>תָּא חֲזִי, מַה כְּתִיב (בראשית ד ח) וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה, בַּשָּׂדֶה דְאִשְׁתְּמוֹדָע לְעִילָא, בַּשָּׂדֶה דְאִקְרֵי שָׂדֶה שֶׁל תַּפּוּחִים, וְנָצַח הַאי דִּינָא לַאֲחוֹי מִשּׁוּם דַּהֲוָה קַשְׁיָא מִנֵּיהּ, וְאַכְפִּיֵיהּ וְאַטְמְרֵיהּ תְּחוֹתוֹי, עַד דְּאִתְעַר בְּהַאי קוּדְשָׁא בְּרִיךְ הוּא, וְאַעִִבְּרֵיהּ מִקַּמֵּיהּ וְשַׁקְעִיהּ בְּנוּקְבָא דִתְהוֹמָא רַבָּא, וּכְלִיל לְאָחוֹי בְּשִׁקּוּעָא דְיַמָּא רַבָּא דִמְבַסֵּם דִּמְעִין עִלָּאִין.</p>\n<p>וּמִנְּהוֹן נָחֲתִין נִשְׁמָתִין לְעָלְמָא, אֵינַשׁ כְּפוּם אָרְחֵיהּ, וְאַף עַל גַּב דִּטְמִירִין אִינוּן, מִתְפַּשְׁטָן דָּא בְדָא וְאַעֲבִדוּ חַד גּוּפָא, וּמֵהַאי גּוּפָא נָחֲתִין נִשְׁמָתְהוֹן דְּרַשִּׁיעַיָּא תַקִּיפֵי רוּחָא, מִתַּרְוִיהוֹן סָלְקָא דַעִִתָּךְ כַּחֲדָא, לָא אֶלָּא חַד לְסִטְרוֹי וְחַד לְסִטְרוֹי, זַכָּאִין אִינוּן צַדִּיקַיָּא, דִמְשַׁלְּפֵי נִשְׁמָתְהוֹן מֵהַאי גּוּפָא קַדִּישָׁא דְאִקְרֵי אָדָם דִּכְלִיל כֹּלָּא, אֲתַר דְּכִתְרִין וְעִטְרִין קַדִּישִׁין</p>"],[9500011227,"<p>מִתְחַבְּרִין תַּמָּן בִּצְרוֹרָא דְאַתְכְּלָא.</p>\n<p>(נ\"א) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מַאי מִקֵּץ יָמִים אֶלָּא מֵהַהוּא דְעָתִיד לְאִתְּמַר בֵּיהּ קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וּבְגִין דָּא וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, וְעוֹד מִקֵּץ יָמִים וְלָא אָמַר מֵרֹאשׁ יָמִים, אֶלָּא מִשִּׁיּוּרִין דִּילֵיהּ וְלָא מִשַּׁפִּירוּ, כְּבַר נַשׁ דְּאָתֵי מִסְכֵּנָא לְתַרְעֵיהּ וּבְזִמְנָא דְאִיהוּ תָּאִיב לְמֵיכַל, בְּגִין דְּלָא לְמֵיהַב לֵיהּ מִשַּׁפִּירוּ דְמַאֲכָל, לָא בָעֵי לְמֵיהַב לֵיהּ מִדֵּי בָּתַר דְּאָכִיל שַׁפִּירוּ דְכֹלָּא, כָּנִיף הַהוּא דְאִיהוּ בְּסוֹפָא וְיָהֵיב לְמִסְכֵּנָא דָא דְאִתְיָאֵשׁ מִנֵּיהּ, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְכַלְבָּא תַּרְמוּן לֵיהּ, וּבְגִין דָּא וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, אֲבָל הֶבֶל לָא אַקְרִיב אֶלָּא מִשַּׁפִּירוּ דְכֹלָּא הֲדָא הוּא דִכְתִיב וְהֶבֶל הֵבִיא גַם הוּא מִבְּכוֹרוֹת צֹאנוֹ וּמֵחֶלְבֵיהֶן לָא קָרִיב לְגַבֵּיהּ שִׁיּוּרִין.</p>\n<p>וּבְגִין דָּא, וַיִּשַׁע יהו\"ה אֶל הֶבֶל וְאֶל מִנְחָתוֹ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה, וַיֹּאמֶר יהו\"ה לְקַיִן לָמָּה חָרָה לָךְ וְלָמָּה נָפְלוּ פָנֶיךָ, הֲלֹא אִם תֵּטִיב שְׂאֵת, אָמַר לֵיהּ אִם אַנְתְּ תֵּטִיב עוֹבָדָךְ, שְׂאֵת יִסְתַּלֵּק קָרְבָּנָךְ, וְאִם לֹא תֵטִיב עוֹבָדָךְ לַפֶּתַח חַטָאת רֹבֵץ דְּיִתְפַּרַע מִינָךְ, אִתְּמַר הָכָא רוֹבֵץ וּבַאֲתַר אָחֳרָא כְּתִיב כִּי תִרְאֶה חֲמוֹר שֹׂנְאֲךָ רוֹבֵץ תַּחַת מַשָּׂאוֹ כו' לֹא תִרְאֶה אֶת חֲמוֹר אָחִיךָ דָא קַיִן דְּאִיהוּ רָבִיץ מִכּוֹבֵד עֲוֹנוֹי, וְאִי לָא בָּעֵי לְאַהֲדָרָא בִּתְיוּבְתָּא, וְחָדַלְתָּ מֵעֲזוֹב לוֹ דְלָא עָבִיד עוֹבָדוֹי דְאָחוּךְ, וְאִי הֲדַר בִּתְיוּבְתָּא עָזוֹב תַּעֲזוֹב עִמּוֹ, מֶה עָבַד הֶבֶל, קָם עֲלֵיהּ וְאַפְּלֵיהּ לְאַרְעָא וּלְבָתַר קָם קַיִן וְקַטְלֵיהּ דְּכֵן כְּתִיב וַיָּקָם קַיִן אֶל הֶבֶל אָחִיו וַיַּהַרְגֵהוּ, וּבְגִין דָּא אָמַר בֶּן סִירָא טָב לְבִישׁ לָא תַעֲבִיד וּבִישָׁא לָא מָטֵי לָךְ.</p>\n<p>וַיֹּאמֶר יהו\"ה לְקַיִן אֵי הֶבֶל אָחִיךָ כו' (בראשית ד ט), אָמַר רַבִּי שִׁמְעוֹן וְכִי לָא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא אָן הֲוָה הֶבֶל דְּשָׁאִיל לֵיהּ, וְהָא לָא אִתְכַּסִּי מִנֵּיהּ מִלָּה, כְּמָה דְאַתְּ אָמַר (ירמיה כג כד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים כו', אֶלָּא וַוי לוֹן לִבְנֵי נָשָׁא טִפְּשַׁיָּא אֲטִימִין לִבָּא סְתִימֵי עִינָא, דַעֲלַיְיהוּ אִתְּמַר (תהלים קטו ה) עִינַיִם לָהֶם וְלֹא יִרְאוּ בִּנְהוֹרָא דְאוֹרַיְיתָא, אִלֵּין אִינוּן בְּעִירָן דְּלָא מִסְתַּכְּלִין וְלָא יָדְעִין אֶלָּא בְתִבְנָא דְאוֹרַיְיתָא, דְאִיהִי קְלִיפָה מִלְּבָר וּמוֹץ דִּילָהּ, דְּאִתְּמַר בְּהוֹן מוֹץ וְתֶבֶן פְּטוּרִין מִן הַמַּעֲשֵׂר, דְּחַכִּימִין דְּאוֹרַיְיתָא מָארֵי דְרָזִין זָרְקִין תִּבְנָא וּמוֹץ דִּלְבָר, וְאָכְלִין חִטָּה דְאוֹרַיְיתָא דְאִיהִי מִלְּגָאו, כ\"ב אַתְוָון דְּאוֹרַיְיתָא דְסָלְקִין לְחוּשְׁבַּן חִטָּ\"ה.</p>\n<p>תָּא חֲזִי אִלֵּין בְּעִירָן חָשְׁבִין דְּשָׁאִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אֵ\"י הֶבֶל אָחִיךָ כְּמָאן דְּלָא יָדַע אָן הוּא, אֶלָּא א\"י אִיהוּ דְאִסְתַּלַּק מִן אדנ\"י, דְּאִיהוּ א' אהי\"ה אִימָּא עִלָּאָה אָנֹכִי, י' יהו\"ה דְּסָלִיק עִמָּהּ לְמֵדַן לְקַיִן, בְּגִין דָּא כַּד אִסְתַּלַּק א\"י מִן אדנ\"י אִשְׁתָּאַר ד\"ן, וּבְגִין דָּא אֵ\"י הֶבֶל אָחִיךָ, (בראשית ד ג) וַיֹּאמֶר לֹא יָדַעִִתִּי הֲשׁוֹמֵר אָחִי אָנֹכִי, לָא יָדַעִִנָא דִשְׁכִינְתָּא דְאִיהִי אָנֹכִי, עִמֵּיהּ תַּמָּן, אֵ\"י דְאִסְתַּלַּק אִימָּא וּבְרָא לְגַבֵּי חָכְמָה לְמֵיטַל נוּקְמָא מִינֵיהּ, וְאַמַּאי לְגַבֵּי חָכְמָה, בְּגִין דְּאִיהוּ אָדָם עִלָּאָה דְאִתְבְּרִי אָדָם תַּתָּאָה בְּדִיּוֹקְנֵיהּ.</p>\n<p>וַיֹּאמֶר קוֹל דְּמֵי אָחִיךָ צוֹעֲקִים אֵלַי, מַאי דְּמֵי, דָם מִבְּעִי לֵיהּ, אֶלָּא מַאי דְּמֵי דָ\"ן כְּחֻשְׁבַּן דְּמֵ\"י, וְדָא אִיהוּ (שם טו יד) דָּן אָנֹכִי וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכוּשׁ גָּדוֹל. וְעוֹד מַאי קוֹל דְּמֵי, קוֹל דָּם מִבְּעִי לֵיהּ, אֶלָּא תִּרְגֵּם אֹנְקְלוֹס, קָל זַרְעִין דַּעֲתִידִין לְמֵיפַּק מִן אָחוּךְ, אִינוּן שִׁתִּין רִבּוֹא דַעֲתִידִין לְמֵיפַּק מֵהֶבֶל, בְּהַהוּא דְאִתְּמַר בֵּיהּ בְּשַׁגַּם זֶה הֶבֶל, כֻּלְּהוּ צָוְוחִין מִן אַרְעָא, הָכָא רְמִיז עִנּוּי הַדִּין וְעִוּוּת</p>"],[9500011228,"<p>הַדִּין וְחָמָס וְשׁוֹד וְשֶׁבֶר דַּעֲתִידִין בְּנוֹי דְּקַיִן לְמֶעֱבַד לִבְנוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְדָא אִיהוּ קוֹל דְּמֵי אָחִיךָ, אָחִיךָ אִתְקְרֵי מִסִּטְרָא דְאִנּוּן דְּאִתְּמַר בְּהוֹן (שמות לב כז) הִרְגוּ אִישׁ אֶת אָחִיו.</p>\n<p>(נ\"א) וַיֹּאמֶר יהו\"ה אֶל קַיִן אֵי הֶבֶל אָחִיךָ, אָמַר רַבִּי שִׁמְעוֹן וְכִי לָא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא אֵי הֶבֶל דַּהֲוָה שָׁאִיל אֵי הֶבֶל אָחִיךָ, וְכִי אִיהוּ לָא הֲוָה יָדַע דְּקוּדְשָׁא בְּרִיךְ הוּא לֵית מִלָּה דְיִתְכַּסִּי מִנֵּיהּ אֲפִילוּ מַחֲשָׁבָה דְלִבָּא כָּל שֶׁכֵּן מִלָּהּ דְּעָלְמָא, דְּאָמַר לֹא יָדַעְתִּי הֲשׁוֹמֵר אָחִי אָנֹכִי, אֶלָּא וַוי לוֹן לְטִפְּשִׁין אַטִימִין דְּלִבָּא וְעַיְינִין לוֹן וְלָא מִסְתַּכְּלִין אֶלָּא בְּתֶבֶן לְמֵיכַל מִנֵּיהּ כִּבְעִירָן, דְּחַכִּימִין דְּיָדְעִין בְּחִטָה דְאוֹרַיְיתָא דְאִיהִי שְׁנַיִם וְעֶשְׂרִים אַתְוָון כְּחֻשְּׁבַּן חִטָ\"ה, אִלֵּין זָרְקִין תִּבְנָא מִדְּאוֹרַיְיתָא וְאָכְלִין חִטָה דְאוֹרַיְיתָא מִלְּגוֹ, תּוּ אַחֲזֵי לְכוֹן רָזִין טְמִירִין בְּהַאי קְרָא בְּזִמְנָא דְקָטַל קַיִן לְהֶבֶל, סָלִיק א\"י מִן אדנ\"י וְאִשְׁתָּאַר דָ\"ן, א' אִיהוּ אָנֹכִי אִימָא עִלָּאָה, י' יהוה דְיוּדִין אַבָּא, דִּסְלִיקוּ לְמִתְבַּע דִּינָא עַל בְּנֵיְיהוּ דְאִיהוּ הֶבֶל וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא אֵי הֶבֶל אָחִיךָ.</p>\n<p>בְּהַהוּא זִמְנָא אָמַר אִיהוּ לֹא יָדַעְתִּי הֲשׁוֹמֵר אָחִי אָנֹכִי, חָמָא קוּדְשָׁא בְּרִיךְ הוּא דְלָא אַדְכִּיר י', אֶלָּא א' דְּאִיהוּ אָנֹכִי, אָמַר לֵיהּ קוֹל דְּמֵי אָחִיךָ צוֹעֲקִים אֵלַי, דַּם אָחִיךָ מִבָּעֵי לֵיהּ, מַאי דְּמֵי, אֶלָּא דָא דַם י', וְעוֹד דְּמֵי אִיהוּ דָ\"ן כְּחוּשְׁבַּן דְּאִשְׁתָּאַר מִן אדנ\"י, וְכֹלָּא קְשׁוֹט, דִּתְלַת שְׁמָהָן כְּלִילָן בְּהַהוּא שְׁמָא, אַבָּא וְאִימָא וּבְרַתָּא, דְּאִנּוּן יהו\"ה אהי\"ה אדנ\"י, בְּגִין דְּהֶבֶל הֲוָה דִיּוֹקְנָא דְאָדָם דִּלְעֵילָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא וְאִיהוּ קוֹל דְּאִתְּמַר בֵּיהּ קוֹל דְּמֵי אָחִיךָ, וְאִית רָזָא אָחֳרָא, קוֹל דְּמֵי, קוֹל דָּם מִבָּעֵי לֵיהּ, אֶלָּא תִּרְגֵּם אֻנְקְלוֹס קָל דַּם זַרְעִין דַּעֲתִידִין לְמֵיפַּק מִן אֲחוּךְ, וְאִנּוּן שִׁתִּין רִבּוֹא.</p>\n<p>בְּהַהוּא זִמְנָא דְחָמָא דְחוֹבָא דָא בַּאֲתַר עִלָּאָה הֲוָה תַּלְיָא, הִרְהֵר בִּתְיוּבְתָּא וְאָמַר גָּדוֹל עֲוֹנִי מִנְּשׂוֹא, הֵן גֵּרַשְׁתָּ אוֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנֶיךָ אֶסָּתֵר וְהָיִיתִי נָע וָנָד בָּאָרֶץ כו', הָכָא אִתְרַמִּיז גִּלְגּוּלָא דְרַשִּׁיעַיָּא דְאִתְּמַר בְּהוֹן וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ כו', וְדָא אִיהוּ הֵן גֵּרַשְׁתָּ אוֹתִי הַיּוֹם דָּא גִלְגּוּלָא קַדְמָאָה, וְהָיִיתִי נָע דָּא גִלְגּוּלָא תִּנְיָינָא, וָנָד דָּא גִלְגּוּלָא תְּלִיתָאָה, דָּא אִיהוּ רָזָא עַל שְׁלשָׁה פִּשְׁעֵי יִשְׂרָאֵל, אִם תָּב בִּתְיוּבְתָּא בִּתְלַת גִּלְגּוּלִין שַׁפִּיר, וְאִם לָא, כְּתִיב בֵּיהּ וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, לָא אַהֲדַר לֵיהּ בְּגוּפָא אָחֳרָא, אֶלָּא יָד לְיָד לֹא יִנָקֶה רָע וְהָכִי אָזִיל נָע וָנָד עַד שִׁתִּין רִבּוֹא, וּלְכָל חַד כְּפוּם חֵילֵיהּ, דְּהַהוּא דְקָטִיל הָכִי נָטִיל קוּדְשָׁא בְּרִיךְ הוּא נוּקְמָא מִנֵּיהּ. ע\"כ בספר אחר (בדף מ\"א ת\"ח תרין אתוון עד ותהלתי לפסילים שייך כאן).</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אִם כֵּן אִשְׁתְּמוֹדָע דְּכָל עָאקוּ דָא יְהֵא בְגָלוּתָא בַתְרָאָה, אַמַּאי אִתְּמַר (בראשית ד ב) קָנִיתִי אִישׁ אֶת יהו\"ה, אִי תֵימָא בְגִין קֵנִי דְנָפִיק מִנֵּיהּ זַרְעָא מַעַלְיָא, בָּתַר דְּיִתְכַּנִּישׁ אִיהוּ יִתְעָרוּן בְּנוֹי דְּקַיִן לְחָרְבָא עָלְמָא, וּמִנַּיְיהוּ קוֹל דְּמֵי אָחִיךָ צוֹעֲקִים, הֲדָא הוּא דִכְתִיב (תהלים יג ו) מִשּׁוֹד עֲנִיִּים מֵאֶנְקַת אֶבְיוֹנִים כו'.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, בְּרִי, קַיִן מִסִּטְרָא דְאִילָנָא דְטוֹב וָרָע הֲוָה, וְאִתְפַּשְׁטוּתָא דְטוֹב הֲוָה בְגִלְגוּלָא עַד קֵנִי חוֹתֵן מֹשֶׁה, מִתַּמָּן וְאֵילֵךְ אִתְפַּשְׁטוּתָא דְרָע, וּבְגִין דְּאַחֲזֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מַה דַּעֲתִידִין לְמֶעֱבַד בְּנוֹי לְיִשְׂרָאֵל בְּכָל דָּרָא וְדָרָא, דְּכֹלָּא אַחֲזֵי לֵיהּ, אָמַר גָּדוֹל עֲוֹנִי מִנְּשׂוֹא, וּמְנָא לָן דְּאַחֲזֵי לֵיהּ גִּלְגּוּלָא דִילֵיהּ בְּכָל דָּרָא וְדָרָא, הֲדָא הוּא דִכְתִיב (בראשית ד יד) הֵן גֵּרַשְׁתָּ אוֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנֶיךָ אֶסָּתֵר וְהָיִיתִי נָע וָנָד בָּאָרֶץ, נָע וָנָד וַדַּאי, הָכָא רָמִיז גִּלְגּוּלָא דִילֵיהּ וּבְנוֹי, הֲדָא הוּא דִכְתִיב (קהלת ח י) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ, וְהָא אוּקִימְנָא לוֹן (דברים ז י) וּמְשַׁלֵּם לְשׂנְאָיו וכו', הֵן גֵּרַשְׁתָּ אוֹתִי דָא גִלְגּוּלָא קַדְמָאָה, הַיּוֹם כְּהַהוּא דְאִתְּמַר בֵּיהּ (תהלים צה ז) הַיּוֹם אִם בְּקוֹלוֹ תִשְׁמָעוּ, וְהָיִיתִי נָע וָנָד תְּרֵין גִּלְגּוּלִין אָחֳרָנִין, אֶסָּתֵר הָכָא רָמִיז (דברים לב כ) וַיֹּאמֶר אַסְתִּירָה פָנַי מֵהֶם כו', (איוב לג כט) וְהֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, וַעֲלַיְיהוּ אִתְּמַר (עמוס ב ו) עַל שְׁלֹשָׁה פִּשְׁעִי יִשְׂרָאֵל, וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, דְלָא אַהֲדַר לוֹן בְּגוּפָא רְבִיעָאָה, וְלַאו בְּפוּרְקָנָא רְבִיעָאָה, אֶלָּא אִתְּמַר בְּיִשְׂרָאֵל (דברים לב יב) יהו\"ה בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר, בְּגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ.</p>\n<p>וְעוֹד</p>"],[9500011229,"<p>אֵי הֶבֶל אָחִיךָ, תָּא חֲזִי תְּרֵין אַתְוָון אִלֵּין שְׁמַעִִנָא דְלַאֲתַר עִלָּאָה הֲווֹ סָלְקִין, א\"י, א' אָמוֹן מוּפְלָא וּמְכוּסֶה, י' מַחֲשָׁבָה, דִבְהַאי אֲתַר חָאבוּ אָדָם וְהֶבֶל, וְאִתְּמַר דְּאִינוּן א' כֶּתֶר עִִלְיוֹן, י' מַחֲשָׁבָה, לְעִילָא לְעִילָא אִסְתַּלַּק הַאי חוֹבָה, אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, וְהָא כַּמָּה מַחֲשָׁבוֹת אִינוּן, שְׁכִינְתָּא אִתְקְרֵי מַחֲשָׁבָה, וְאִיהִי י' מִן אדנ\"י, וְחָכְמָה מַחֲשָׁבָה, וְכֶתֶר דְּאִיהִי א' מִן אדנ\"י מַחֲשָׁבָה, וְכַמָּה מַחֲשָׁבִין אִינוּן דָּא לְעִילָא מִן דָּא, וְדָא עַל גַּב דָּא, הֲדָא הוּא דִכְתִיב (קהלת ה ז) כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבֹהִים עֲלֵיהֶם, וּלְעִילָא מִכֻּלְּהוּ מַחֲשָׁבָה סְתִימָא דְכָל סְתִימִין, עִלָּאָה עַל כָּל עִלָּאִין, דְּלֵית מַחֲשָׁבָה אָחֳרָא לְעִילָא מִנֵּיהּ, וְכַמָּה מַחֲשָׁבִין אִינוּן לְבוּשִׁין דָּא לְדָא, וְאִיהוּ אִשְׁתְּמוֹדָע דְּלָא חָאב אֶלָּא בְּמַחֲשָׁבָה דְאִיהִי לְבוּשָׁא, הֲדָא הוּא דִכְתִיב (בראשית ג י) וָאִירָא כִּי עִירוֹם אָנֹכִי וָאֵחָבֵא, אִתְּמַר בְּאָדָם וָאֵחָבֵא וְאִתְּמַר בְּמֹשֶׁה (שמות ג ו) וַיַּסְתֵּר מֹשֶׁה פָּנָיו.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּרִי, בְּוַדַּאי בְּכֹלָּא חָאב אָדָם, בְּמַחֲשָׁבָה דְאִיהִי לְבוּשָׁא, וּבְמַחֲשָׁבָה דְאִיהִי מִלְּגָאו, וּבְגִין דָּא אָמַר לְמֹשֶׁה בְּזִמְנָא דְאָמַר (שמות לג יח) הַרְאֵנִי נָא אֶת כְּבֹדֶךָ, אָמַר, כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, דְּאִם זָכָה שֶׁיִּרְאַנִי, וָחַי לְעוֹלָם, וּבְגִין דָּא אָמַר לֵיהּ לֹא (שמות לג כ) תוּכַל לִרְאוֹת אֶת פָּנָי, וְלַאו אִינוּן פָּנִים הָכָא אֶלָּא פָנִים דְּלָא נִרְאִין, בַּאֲתַר דְּאִשְׁתְּמוֹדָע עִלַּת הָעִלּוֹת, וּבַאֲתַר דְּאִתְגַּלְיָיא, וְחוֹבָא דְאָדָם גָּרִים דְּלָא יְכִיל מֹשֶׁה לְאִסְתַּכְּלָא בֵיהּ, כָּל שֶׁכֵּן אָחֳרָא, דְּעִלַּת הָעִלּוֹת אִסְתַּלַּק מִמַּחֲשָׁבָה דְחָאב בָּהּ אָדָם, וּבְגִין דָּא עַיִן לֹא תְשׁוּרֵהוּ, וּמַחֲשָׁבָה לֹא תְכִילֵהוּ, לָא יָכִיל לְאַשָּׂגָא לֵיהּ, דְּאִיהוּ חַי הַחַיִּים, וּבַאֲתַר דְּאִיהוּ שַׁרְיָא לֵית מִיתָה תַמָּן, וּמַחֲשָׁבָה דְאִסְתַּלַּק מִנֵּיהּ, בְּוַדַּאי אִיהוּ חָכְמָה לְבוּשָׁא לְחָכְמָה סְתִימָאָה, בְּוַדַּאי בָּהּ חָאב אָדָם, וּבְגִין דָּא אִתְּמַר בֵּיהּ (בראשית ג י) וָאִירָא כִּי עִירוֹם אָנֹכִי וָאֵחָבֵא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וְהָא מֵהָכָא מַשְׁמַע דְּלָא חָאב בְּמַחֲשָׁבָה עִלָּאָה אֶלָּא בְהַהִיא דְאִיהִי לְבוּשָׁא מִינָהּ, וְאִשְׁתָּאַר אִיהוּ</p>"],[9500011230,"<p>בְהַהִיא דְאִיהִי מִלְּגָאו, בְּמוֹחָא בְּלָא קַרְקַפְתָּא, וּבְגִין דָּא וָאִירָא, דְּאִזְדַּעִִזַע מֵהַהִיא דִלְגוֹ מִן מַחֲשָׁבָה סְתִימָא דְאִיהוּ עִלַּת הָעִלּוֹת, אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, בְּרִי, בְּמַחֲשָׁבָה דְאִיהוּ מוֹחָא אוּף הָכִי חָב דְּזַרְעָא מִתַּמָּן נָפִיק, דְּאִיהוּ נְבִיעוּ דְאִילָנָא דְחַיֵּי דְאִיהוּ אוֹר קַדְמוֹן וְאוֹר צַח וְאוֹר מְצוּחְצָח, תְּלַת טִפִּין דְּאִתְרְמִיזוּ בְּי' עִלָּאָה, קוֹצָא דִלְעִילָא וְקוֹצָא דִלְתַתָּא וְגֵיו בְּאֶמְצָעִיתָא, וְעָרַב תַּמָּן חֹשֶׁךְ דְּאַפְסִיק בֵּין עִלַּת הָעִלּוֹת לְמוֹחָא סְתִימָא, וּבְגִין דָּא (שמות לג כ) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי עַד דְּהַהוּא חֹשֶׁךְ אִתְעַבַּר מִתַּמָּן, וְדָא אִיהוּ רָזָא (ישעיה נט כ) כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם וּבֵין אלהיכ\"ם, וּבְגִין הַהוּא חֹשֶׁךְ, לֵית מַחֲשָׁבָה יָכִילָא לְאַשָּׂגָא תַמָּן, כָּל שֶׁכֵּן עַיִן, עַד דְּאִתְעַבַּר מִתַּמָּן הַהוּא חֹשֶׁךְ, וּכְגַוְונָא דִילֵיהּ לְתַתָּא אִית עֲנָנָא חֲשׁוֹכָא דְאִתְּמַר בָּהּ (איכה ג מד) סַכֹּתָה בֶעָנָן לָךְ כו'.</p>\n<p>אִזְדַּעִִזַע רַבִּי אֶלְעָזָר וְכֻלְּהוּ חַבְרַיָּא וְאִזְדַּעִִזְעוּ סָבִין מָארֵי דִמְתִיבְתָּא, אָמַר רַבִּי אֶלְעָזָר עַד כְּעַן לָא יְדַעִִנָא דְחוֹבָא דְאָדָם הָכִי הֲוָה עִלָּאָה, דְּמָטָא לַאֲתַר עִלָּאָה דְכָל עִלָּאִין, אָמַר, אַבָּא, הַב לִי רְשׁוּ לְמִשְׁאַל אַף עַל גַּב דְּלָא אִתְיַיהִיב רְשׁוּ לְכָל בַּר נַשׁ לְמִשְׁאַל כָּל שֶׁכֵּן לְמִנְדַּע, אָמַר לֵיהּ אֵימָא בְּרִי דְהָא רַעֲוָא אִשְׁתַּכַּח וּרְשׁוּתָא אִתְיַיהִיב לְגַלָּאָה כָּל מַה דְּיָכִילְנָא לְמִנְדַּע, אָמַר לֵיהּ, אַבָּא, אִשְׁתְּמוֹדָע בְּגִין הַהוּא חֹשֶׁךְ דְּאַפְסִיק בֵּין עִלַּת הָעִלּוֹת לְמַחֲשָׁבָה סְתִימָא, דְּעִלַּת עַל כָּל הָעִלּוֹת לָא אִשְׁתַּתַּף בְּשׁוּם מַחֲשָׁבָה סְתִימָא כָּל שֶׁכֵּן גַּלְיָא, וְלַאו בְּשׁוּם אוֹר גָּנִיז וְטָמִיר וְקַדְמוֹן וְצַח וּמְצוּחְצָח, אָמַר וַדַּאי הָכִי הוּא דְאִם אִלֵּין נְהוֹרִין וּמַחֲשָׁבִין הֲווֹ מִנֵּיהּ לָא הֲוָה יָכִיל חֹשֶׁךְ לְאַפְרָשָׁא, אֲבָל עִלַּת עַל כָּל הָעִלּוֹת אִיהוּ עַל כָּל נְהוֹרִין גְּנִיזִין וּסְתִימִין כְּנִשְׁמָתָא בְגוּפָא, וְאוֹר קַדְמוֹן אַף עַל גַּב דְּאִיהוּ סָתִים וְגָנִיז וְאִיהוּ קַדְמוֹן לְכָל סְפִירָן וּלְכָל אַתְוָון וּנְקוּדֵי וְטַעֲמֵי, הָכִי אִיהוּ לְגַבֵּי עִלַּת עַל כָּל הָעִלּוֹת, כְּגוּפָא לְגַבֵּי נִשְׁמָתָא, דִּבְעִלַּת הָעִלּוֹת לֵית בֵּיהּ גַּוָּון וְלָא צוּרָה וְלָא דִיּוֹקְנָא וְלָא שׁוּתָּפוּ, וּבַאֲתַר דְּעַיִן לָא שַׁלִּיט מָאן יָכִיל לְמֶעֱבַד דִּמְיוֹן.</p>\n<p>בָּתַר דְּהִרְהֵר תְּשׁוּבָה אָדָם לְתַתָּא, הָדְרָא לְבוּשָׁא לְגַבֵּי מוֹחָא דְאִיהוּ אַבָּא קַרְקַפְתָּא דִתְּפִלֵּי, וְאִתְחַבַּר מוֹחָא דְאִיהִי חָכְמָה בְּאִימָּא, מִיָּד (בראשית ג כא) וַיַּעַשׂ יהו\"ה אלהי\"ם לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם, וְאִינוּן תְּפִלִּין דְּאִינוּן מֵעוֹר, בְּהַהוּא זִמְנָא קָמַת תְּשׁוּבָה דְאִיהִי אִימָּא קַרְקַפְתָּא דִתְּפִלֵּי עִם אָדָם לְאַגָּנָא עֲלֵיהּ וּלְכַסְיָא עֲלֵיהּ דַּהֲוָה עָרוֹם, כְּגַוְונָא דְאִיהוּ כַּסִּי עַל מוֹחָא עִלָּאָה, וּבְרִי, כָּל מָאן דְּאַנַּח תְּפִלִּין כְּאִלּוּ כַּסִּי עַל מוֹחָא עִלָּאָה, וּבְגִין דָּא שְׁכִינְתָּא עִלָּאָה לָא זָזָה מִנֵּיהּ, וְרָזָא דְמִלָּה (תהלים קל ז) אִם עֲוֹנוֹת תִּשְׁמָר יָ\"הּ אדנ\"י מִי יַעֲמוֹד, מִ\"י יַעֲמוֹד וַדַּאי דְּאִיהִי אִימָּא עִלָּאָה תְּשׁוּבָה הָא קָמַת בְּאָדָם עִלָּאָה, וּשְׁכִינְתָּא דְאִיהִי תְּפִלָּה שֶׁל יָד בְּאָדָם תַּתָּאָה, שְׁכִינְתָּא עִלָּאָה נָחֲתַת עִם אָדָם, וּשְׁכִינְתָּא תַּתָּאָה עִם הֶבֶל, וְעִם כָּל (דא) מָארֵי דְּדַכְיוּ דְקָא אַתְיָין מִנַּיְיהוּ, וּבְגִין דָּא (רות א יט) וַתֵּלַכְנָה שְׁתֵּיהֶן.</p>\n<p>מִיָּד דְּחָאבוּ יִשְׂרָאֵל בְּעוֹבָדָא דְעִִגְלָא מַה כְּתִיב (ישעיה ג ב) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם דְּאִתְּמַר בָּהּ (משלי ב ג) כִּי אִם לַבִּינָה תִקְרָא, אִשְׁתַּלְחַת (נ\"א ואסתלקת) מִנַּיְיהוּ וַתָּרָם מֵעַל הָאָרֶץ, דְּלָא נָחְתַת עֲלַיְיהוּ אֶלָּא</p>"],[9500011231,"<p>בְּשַׁבָּתוֹת וְיֹמִין טָבִין, וְאִשְׁתְּאָרַת שְׁכִינְתָּא תַּתָּאָה יְחִידָאָה לְתַתָּא, וּשְׁכִינְתָּא עִלָּאָה יְחִידָאָה לְעִילָא, וְהָא אוּקְמוּהָ אֵיכָה יָשְׁבָה בָדָד, דִּבְקַדְמֵיתָא לָא הֲוַת שְׁכִינְתָּא עִלָּאָה זָזָה מִנַּיְיהוּ כְּגַוְונָא דִשְׁכִינְתָּא תַּתָּאָה, זַכָּאִין אִינוּן מָארֵי דִתְיוּבְתָּא דְנַחְתֵי לָהּ עֲלַיְיהוּ בְּכָל יוֹמָא וְשַׁעִִתָּא וְרִגְעָא וְלָא זָזַת מִנַּיְיהוּ בְּכָל אֲתַר, דַּעֲלַיְיהוּ אִתְּמַר (שם ו כב) בְּהִתְהַלֶּכְךָ תַּנְחֶה אוֹתָךְ כו' וְלָא אִית לָהּ עֲלַיְיהוּ יוֹמָא יְדִיעַ כְּגַוְונָא דְאָחֳרָנִין דְּלָא נָחֲתַת עֲלַיְיהוּ אֶלָּא בְּשַׁבָּתוֹת וְיוֹמִין טָבִין, אֲבָל מָארֵי תְּיוּבְתָּא לָא זָזַת מִנַּיְיהוּ לְעָלַם.</p>\n<p>וּבְגִין דָּא בְרִי, אֵ\"י הֶבֶל אָחִיךָ, אִי יָכְלִינָן לְמֵימַר א' י' מִן אהי\"ה אִימָּא עִלָּאָה, וְאִשְׁתָּאֲרוּ ה' ה', וְאִתְּמַר עֲלַיְיהוּ וַתֵּלַכְנָה שְׁתֵּיהֶן, הָכָא חָאב הֶבֶל אָדָם, חָב בְּי\"ו מִן יהו\"ה וְאִסְתַּלַּק י\"ו וְאִתְעֲבִיד ו' י', אָמַר רַבִּי אֶלְעָזָר וְהָא י' ו', אִינוּן, י' לְעִילָא ו' לְתַתָּא, מַאי ו' י', אָמַר בְּרִי הָכִי אִיהוּ וַדַּאי, דְּחוֹבָה דָא אִיהוּ לְעִילָא בְּאָת א דְאִסְתַּלְקַת בְּמַחֲשָׁבָה דְאִיהִי י' עִלָּאָה דְתַמָּן עִלַּת הָעִלּוֹת, וְאִשְׁתָּאַר ו' י' כְּגַוְונָא דָא א, וְעַל י' עִלָּאָה אִתְּמַר (תהלים צא יד) כִּי יָדַע שְׁמִי, שֵׁם י', יִקְרָאֵנִי וְאֶעֱנֵהוּ, זַכָּאָה אִיהוּ מָאן דְּנָחִית לֵיהּ בְּמַחֲשַׁבְתֵּיהּ לְאַתְרֵיהּ, דְּהַאי מַחֲשָׁבָה עֲלָהּ אִתְּמַר (ויקרא ז לז) זֹאת הַתּוֹרָה לָעוֹלָה לַמִּנְחָה וְלַחַטָּאת וְלָאָשָׁם וְלַמִּלּוּאִים וּלְזֶבַח הַשְּׁלָמִים.</p>\n<p>וְאַמַּאי אִתְּמַר בְּאָת י' כִּי יָדַע שְׁמִי, אֶלָּא, כְּמָה דְלֵית בְּאָת י' שׁוּתָּפוּ דְאָת אָחֳרָא, הָכִי לֵית בֵּיהּ שׁוּתָּפוּ דְאִיהוּ אֶחָד וְאֵין שֵׁנִי לוֹ, אֶחָד בְּלָא חֻשְׁבָּן, הוּא בְרָא כֹּלָּא וְלֵית בּוֹרֵא עֲלֵיהּ, וְכִי אִית דְּיָכִיל לְמִבְרֵי אֲפִילוּ יִתּוּשׁ זְעִיר אֶלָּא הוּא, אֶלָּא, מַיִם אִית לוֹן חֵילָא לְמִבְרֵי אִילָנִין וְעִשְׂבִּין, וְאִינוּן אִתְבְּרִיאוּ, אֲבָל בּוֹרֵא עָלְמִין בָּרָא וְלֵית עֲלֵיהּ מָאן דְּבָרָא לֵיהּ וּלְחַכִּימָא בִרְמִיזָא דְבַאֲתַר דָּא לֵית לְגַלָּאָה יַתִּיר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר מֵהָכָא מַשְׁמַע דְּאִית בּוֹרֵא בְשׁוּתָּפוּ דְאַתְוָון, כְּגוֹן ב' מִן בְּרֵאשִׁית דְּאִיהִי אִימָּא, ר' מִן רֵאשִׁית דְּאִיהִי חָכְמָה, ו' מִן בּוֹרֵא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, א' מִן בְּרֵאשִׁית דְּאִיהוּ כֶּתֶר, שִׁי\"ת, שִׁית סְפִירָן, הָא כֻלְּהוּ עִִשֶׂר, אִם חָסֵר חַד לָא אִשְׁתַּלִּים בְּרִיאָה, אֲבָל עִלַּת עַל כָּל הָעִלּוֹת אִיהוּ בָּרָא כֹלָּא בְּלָא שׁוּתָּפוּ כְּלָל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר וְכִי הָא שְׁמַעִִנָא, דְּבַעֲשַׂר סְפִירָן לָא אִתְּמַר תַּמָּן אֶלָּא אֲצִילוּת וְלָא בְּרִיאָה, אָמַר רַבִּי שִׁמְעוֹן וּמָאן אָמַר דְּאִית בְּהוֹן בְּרִיאָה אֶלָּא כֻלְּהוּ עִִשֶׂר בְּשׁוּתָּפוּ דָא עִם דָּא עָבְדִין בְּרִיאָה בְּעָלְמָא, וַאֲנָא אֵימָא דְאִם הֲוָה חָסֵר חַד מִן מִנְיָנָא לָא אִשְׁתַּלִּים הַהִיא בְּרִיאָה, אֲבָל עִלַּת עַל כָּל הָעִלּוֹת אִיהוּ בּוֹרֵא בְּלָא שׁוּתָּפוּ אָחֳרָא דְאִיהוּ חַד בְּלָא שׁוּתָּפָא כְלָל לָא לְעִילָא וְלָא לְתַתָּא וְלָא בְּאֶמְצָעִיתָא וְלָא מִכָּל סִטְרָא כְלָל, אָמַר וַדַּאי כְּעַן אִתְגַּלְיָא מַה דְּלָא אִתְמַסַּר לְגַלָּאָה אֲפִילוּ מִלִּבָּא לְפוּמָא, וְרָזָא דָא צָרִיךְ לְאִתְכַּסְיָא מִכָּל בַּר נַשׁ, דְּלַאו כָּל מוֹחָא יָכִיל לְמִסְבַּל הַאי, אֶלָּא אִלֵּין דְּיָדְעִין בְּרָזִין, אִלֵּין דְּחָכְמָתָא דִלְהוֹן סָלִיק עַל כָּל נְבִיאַיָּא וְחַכִּימַיָּא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא, הָא אִתְגַּלְיָא א' בְּרָזָא עִלָּאָה כַּד אִסְתַּלַּק עִלַּת הָעִלּוֹת בְּאָת י' וְאִשְׁתָּאַר וי אֶלָּא מַאי אוי, אָמַר לֵיהּ (א' עלאה) (נ\"א אית א') לְעִילָא מִן א', דְּאִית א' מֵאַתְוָון רַבְרְבָן, וְאִית א' מֵאַתְוָון זוּטְרָן, וְאִית א' מֵאַתְוָון בֵּינוּנִיִּים, (נ\"א זה שייך לדף פ\"ג ע\"א ועוד נעשה אדם) אִינוּן אָדָם דִּבְרִיאָה אָדָם דִּיצִירָה אָדָם דַּעֲשִׂיָּה, וַעֲלַיְיהוּ אִתְּמַר (קהלת ה ז) כִּי גָבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר, וְאִית תְּלַת עִלָּאִין עֲלַיְיהוּ בְאֹרַח אֲצִילוּת, וַעֲלֵיהֶם אִתְּמַר וּגְבֹהִים עֲלֵיהֶם.</p>\n<p>וְאִינוּן דִּבְרִיאָה אִינוּן לְבוּשִׁין לְאִינוּן דַּאֲצִילוּת, וְהַאי אִיהוּ אוֹר לְבוּשׁ עִִלְיוֹן, וְאִינוּן עִִשֶׂר מִתְלַבְּשִׁין בְּעִִשֶׂר, וְאִלֵּין דַּאֲצִילוּת אָמְרוּ לְאִינוּן דִּבְרִיאָה דְמִתְלַבְּשִׁין בְּהוֹן, (בראשית א כו) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵינוּ, כָּל סְפִירָה יָהִיב בֵּיהּ חוּלָקֵיהּ מִלְּגָאו וּמִלְּבָר, וְאִם חָסֵר חַד מֵעֲשַׂר סְפִירָן דְּלָא הֲוָה יָהִיב בֵּיהּ חוּלָקֵיהּ לָא הֲוָה אִשְׁתַּלִּים בִּנְיָינָא דְאָדָם, וּבְזִמְנָא דְחָב אָדָם כָּל סְפִירָה וּסְפִירָה נָטִיל חוּלָקֵיהּ מִנֵּיהּ וְאִשְׁתָּאַר אַיִן, וְרָזָא דְמִלָּה (קהלת ג יט) וּמוֹתַר הָאָדָם מִן הַבְּהֵמָה אָיִן, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין (תהלים מט יג) וְאָדָם בִּיקָר בַּל יָלִין נִמְשַׁל כַּבְּהֵמוֹת נִדְמוּ, אָדָם דַּהֲוָה לָן בִּיקָר דִּלְעִילָא וְלָא נָטִיר לֵיהּ, נִמְשַׁל כַּבְּהֵמוֹת דְּמוּת דִּילֵיהּ, דְּאִינוּן חַיּוֹת הַקֹּדֶשׁ, אֲבָל עִלַּת הָעִלּוֹת כַּד בָּרָא לֵיהּ כְּמָה דְאַתְּ אָמַר (נ\"א הדא הוא דכתיב) (בראשית א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, אִיהוּ נָטִיל כֹּלָּא מִינֵיהּ, וִיהִיב בֵּיהּ בְּלָא שׁוּתָּפוּ דְאָחֳרָא, דְּאַבָּא וְאִימָּא עָבְדוּ לֵיהּ בְּצִיּוּרַיְיהוּ</p>"],[9500011232,"<p>בִּתְרֵין צִיּוּרִין, הֲדָא הוּא דִכְתִיב (בראשית ב ד) וַיִּיצֶר יהו\"ה אלהי\"ם וַיִּיצֶר בִּתְרֵין צִיּוּרִין, צִיּוּרָא דְאַבָּא דְאִיהוּ יהו\"ה, וְצִיּוּרָא דֶאלהי\"ם דְּאִיהִי אִימָּא, וְדָא אִיהוּ וַיִּיצֶר יהו\"ה אלהי\"ם, וּלְבָתַר עָבַד לֵיהּ מָאנָא הֲדָא הוּא דִכְתִיב (שם) עָפָר מִן הָאֲדָמָה, מִן הָאֲדָמָה לָא כְתִיב, אֶלָּא עָפָר מִן הָאֲדָמָה, וְדָא שְׁכִינְתָּא תַּתָּאָה דְאִתְּמַר בָּהּ (איוב לד טו) וְאָדָם עַל עָפָר יָשׁוּב דְּאִיהִי גִלְגּוּלָא דִילֵיהּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא, בָּתַר דְּרַעֲוָא אִשְׁתַּכַּח צָרִיךְ לְמִפְתַּח מִלִּין בְּאִתְגַּלְיָא, מַאי אָדָם דְּבָרָא עִלַּת הָעִלּוֹת בְּדִיּוֹקְנֵיהּ, דְּהָא כְתִיב דְּלֵית בֵּיהּ דְּמוּת, אָמַר לֵיהּ, בְּרִי, הָכָא לָא אָמַר בְּצַלְמֵנוּ, דְּאִית בֵּיהּ דִּיּוֹקְנָא, אֶלָּא בְּצַלְמוֹ רוֹצֶה לוֹמַר כְּגַוְונָא דְאִיהוּ רוֹאֶה וְאֵינוֹ נִרְאֶה, דִּיהֵא אִיהוּ הָכִי, וּכְגַוְונָא דְלֵית בֵּיהּ דִּיּוֹקְנָא, דִּיהֵא אִיהוּ הָכִי, וּכְגַוְונָא דְלֵית קַדְמוֹן עֲלֵיהּ דִּיהֵא אִיהוּ הָכִי, וּכְגַוְונָא דְאִיהוּ עִלַּת הָעִלּוֹת חַד בְּלָא שׁוּתָּפוּ וּבְלָא חֻשְׁבָּן, דִּיהֵא אִיהוּ הָכִי, כֹּלָּא כְּגַוְונָא דִילֵיהּ.</p>\n<p>וְאִית אָדָם דִּבְרִיאָה וִיצִירָה וַעֲשִׂיָּה בְּגַוָּונָא אָחֳרָא בִּלְבוּשִׁין וְגוּפָא (דלבר) (נ\"א בלבד), דְּבַאֲצִילוּת הָא אִתְּמַר דְּלֵית בֵּיהּ בְּרִיאָה וִיצִירָה וַעֲשִׂיָּה כְּלָל, אִית בְּרִיאָה דְבָרָא הוּא לְתַתָּא בְדִיּוֹקְנֵיהּ, אֲבָל לַאו דְּאִתְבְּרֵי אִיהוּ.</p>\n<p>וְתָא חֲזִי אַף עַל גַּב דְּאִתְּמַר בִּסְפִירָן בְּרִיאָה, בִּלְבוּשָׁא מִלְּבָר אִיהוּ, וְלַאו אִיהוּ מִלְּגָאו, וּבְגִין דָּא כְּתִיב (בראשית א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ הָכָא רָזָא אָחֳרָא בְּגוּפָא, אִית סְפִירָן דִּבְרִיאָה וְאִית סְפִירָן דַּאֲצִילוּת, וּבְגִין דָּא וַיִּבְרָא אלהי\"ם אֶת הָאָדָם, דָּא עַמּוּדָא דְאֶמְצָעִיתָא דְאִתְּמַר בֵּיהּ (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, בְּצַלְמוֹ שְׁכִינְתָּא תַּתָּאָה, בְּצֶלֶם אלהי\"ם שְׁכִינְתָּא עִלָּאָה, וַיִּיצֶר יהו\"ה אלהי\"ם אֶת הָאָדָם דָּא צַדִּיק חַי עָלְמִין, יְצָרוֹ בִיצִירָה עִלָּאָה וּבִיצִירָה תַּתָּאָה, דְּאִינוּן י' י' מִן א, ו' מִן וַיִּיצֶר אִיהוּ ו' דְּאֶמְצָעִיתָא, דְּאִיהוּ בִתְרֵין יוּדִין בְּאָת א, וּתְרֵין יוּדִי\"ן עֲלַיְיהוּ אִתְּמַר (משלי יד א) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ וְאִינוּן חָכְמָה קְדוּמָה וְחָכְמָה תַּתָּאָה.</p>\n<p>וְאָדָם מִסִּטְרָא דְאוֹת בְּרִית י' אִתְיְלִיד מָהוּל, הֲדָא הוּא דִכְתִיב (שמות ב ב) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא, (ישעיה ג י) אִמְרוּ צַדִּיק כִּי טוֹב, דְּתַמָּן לַאו קְלִיפָה דְעָרְלָה כְּלָל, וְהָא דְאִתְּמַר אָדָם הָרִאשׁוֹן מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה, דָא אָדָם דַּעֲשִׂיָּה, וּמַאי נִיהוּ דָא קְלִיפָה דְאִתְלַבְּשָׁא בֵּיהּ (נ\"א דאתלבשת בה) לְשַׁלְטָאָה עַל כֹּלָּא, הֲדָא הוּא דִכְתִיב (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, וּבְגִין דָּא אִתְּמַר בָּהּ (בראשית א כו) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ לְאִתְלַבְּשָׁא בְּכָל דִּיּוֹקְנִין וּקְלִיפִין.</p>\n<p>וְעוֹד אִתְּמַר בָּהּ בִּשְׁכִינְתָּא תַּתָּאָה, נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, דִתְהֵא כְלִילָא מִכָּל סְפִירָן, דְּכָל עִִשֶׂר סְפִירָן יְהִיבוּ בָּהּ כָּל חַד חוּלָקֵיהּ, וּמַאי חוּלָקֵיהּ, אֶלָּא כָּל סְפִירָה יְהִיב בָּהּ עִשּׂוּר דִּילֵיהּ, דְּכָל סְפִירָה סָלִיק לַעֲשָׂרָה, וְיַהֲבוּ לֵיהּ כָּל חַד וְחַד עִשּׂוּר דִּילֵיהּ אִשְׁתָּאֲרוּ אִינוּן תֵּשַׁע תֵּשַׁע, וְכָל חַד וְחַד אִשְׁתַּלִּים בָּהּ לַעֲשָׂרָה, וּבְגִין דָּא מְעַשְּׂרִין חַד מֵעֲשָׂרָה, וּבְגִין דְּאִיהִי כְּלִילָא מִכֻּלְּהוּ אִתְּמַר בָּהּ (ירמיה ב ב) אַהֲבַת כְּלוּלוֹתָיִךְ, כְּלִילָא מִכֹּלָּא, וּלְבָתַר דְּאִתְכְּלִילַת מֵעִלָּאִין אִתְּמַר בָּהּ (בראשית א כו) וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ, אִתְכְּלִילַת בְּתַתָּאִין, וַאֲפִילוּ בְּכָל קְלִיפִין דְּסִטְרָא אָחֳרָא אִתְלַבְּשַׁת, לְקַיְימָא בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, וּבְכָל מַה דְּאִתְלַבְּשַׁת אִתְכְּלִילַת (נ\"א אתקריאת) בִּשְׁמֵיהּ, הָא הָכָא אָדָם דַּעֲשִׂיָּה וִיצִירָה.</p>\n<p>אָדָם דִּבְרִיאָה אוּקְמוּהוּ עַל תִּפְאֶרֶת, מַאי בְּצַלְמוֹ, בְּצֶלֶם, תְּרֵין דִּיּוֹקְנִין דִּילֵיהּ לְעִילָא, אֶלָּא (ס\"א אלין) אִינוּן וָא\"ו תְּרֵין וָוִי\"ן, אִינוּן תְּרֵין דִּיּוֹקְנִין דְּא דְּאִיהוּ אָדָם דְּאֶמְצָעִיתָא, דִּשְׁכִינְתָּא עִלָּאָה אִיהִי דְמוּת אָדָם עִלָּאָה דְאִיהוּ חָכְמָה עִלָּאָה, וּשְׁכִינְתָּא תַּתָּאָה דְמוּת אָדָם דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>וְעוֹד, עַמּוּדָא דְאֶמְצָעִיתָא בְדִיּוֹקְנָא דְכֶתֶר וְדָא אָדָם דִּבְרִיאָה, וְאָדָם דִּיצִירָה צַדִּיק בְּדִיּוֹקְנָא דְחָכְמָה, וּבְגִין דָּא (מלכים א ה כו) וַיהוָֹה נָתַן חָכְמָה לִשְׁלֹמֹה דְאִיהוּ צַדִּיק בְּרִית שָׁלוֹם שָׁלֵם ה', וּשְׁכִינְתָּא תַּתָּאָה אָדָם דַּעֲשִׂיָּה דְמוּת דִּשְׁכִינְתָּא עִלָּאָה וְכֹלָּא קְשׁוֹט, (ושכינתא ודאי אתכלילת בכלא), וּבְגִין דָּא זִמְנִין אִתְקְרִיאַת נֶשֶׁר, זִמְנִין חַיָּה.</p>"],[9500011233,"<p>זִמְנִין יוֹנָה, זִמְנִין צִפּוֹר, בְּכָל מַה דְּשַׁלִּיטָא אִתְקְרִיאַת בִּשְׁמֵיהּ, וּבְעִשְׂבִּין אִתְקְרִיאַת שׁוֹשַׁנָּה, עִץ פְּרִי עוֹשֶׂה פְּרִי, וְכַד שָׁלְטָא עַל אַרְעָא אִתְקְרִיאַת אֶרֶץ, וְכַד שָׁלְטָא עַל יַמָּא אִתְקְרִיאַת יָם עַל שְׁמֵיהּ, וְכַד שָׁלְטָא עַל טוּרִין אִתְקְרִיאַת סֶלַע, לֵית בִּרְיָה בְּעָלְמָא דְשַׁלְטָא עֲלֵיהּ דְּלָא אִתְקְרִיאַת בִּשְׁמֵיהּ, אֲבָל עִם כָּל דָּא דְשַׁלְטָא עַל כֹּלָּא, עֲבִידַת אַפְרָשׁוּתָא בֵּין דַּרְגִּין דְּאִינוּן מוֹחָא וְאִיבָּא, לִקְלִיפִין דְּסִטְרָא אָחֳרָא דְאִינוּן כִּקְלִיפִין דֶּאֱגוֹזָא דִמְכַסְּיָין עַל מוֹחָא, וְרָזָא דְמִלָּה (בראשית א ד) וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ, וַוי לֵיהּ לְמַאן דִּמְעָרֵב קְלִיפִין דְּסִטְרָא אָחֳרָא עִם דַּרְגִּין דְּסִטְרָא דְּדַכְיוּ.</p>\n<p>(כאן חסר) (אמר המגיה עוד מצאתי בס\"א זה הלשון)</p>\n<p>וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וכו' (שם ד א), וְכִי לָא אִשְׁתְּמוֹדָע בָּהּ עַד הַהִיא זִמְנָא, אֶלָּא מִיּוֹמָא דְאִתְחֲרַב בֵּי מַקְדְּשָׁא קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְיַחַד בִּשְׁכִינְתֵּיהּ בְּיוֹמִין דְּחוֹל, וְלָא הֲווֹ יִשְׂרָאֵל אִשְׁתְּמוֹדְעָן תּוּקְפֵיהּ בְּיוֹמִין דְּחוֹל, בְּגִין דְּמֶמְשָׁלָה דְעִִבֶד וְשִׁפְחָה בְּהוֹן, בָּתַר דְּיִתְעַבְּרוּן מֵעָלְמָא מִיָּד וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ וּבְהַהִיא זִמְנָא (ישעיה יא ט) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יהו\"ה, וּבְהַהִיא זִמְנָא אִתְקַיַּים קְרָא (ירמיה לא לג) כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם, (זכריה יד ט) וּבַיּוֹם הַהוּא יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>דָּבָר אַחֵר וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן, יָדַע וַדַּאי כְּגוֹן (אסתר ד א) וּמָרְדְּכַי יָדַע, אִית יְדִיעָה לְטַב וְאִית יְדִיעָה לְבִישׁ, בְּזִמְנָא דְאוֹלִידַת לְקַיִן יָדַע אֶת כָּל אֲשֶׁר נַעֲשָׂה הַהוּא זוּהֲמָא, וְעַד הַהוּא אֲתַר דְּמָטֵי וְאִתְפַּשַּׁט הַהוּא זוּהֲמָא בְּכָל דָּרִין, וּתְלַת גִּלְגּוּלֵי, עֲלַיְיהוּ אִתְּמַר (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, בָּתַר דְּיִתְגַּבַּר בְּיִצְרֵיהּ דְּלָא עָבִיד חֶטְאָה, וְהַאי יְדִיעָה דְקַיִן אִיהוּ דְאִתְגְּלֵי לֵיהּ עַד הַהוּא אֲתַר דְּאִתְפַּשַּׁט, דַּעֲלֵיהּ אִתְּמַר (ישעיה יד כט) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע, בְּגִין דְּאִיהוּ מִשֹּׁרֶשׁ נָחָשׁ דְּאַטִּיל זוּהֲמָא בְחַוָּה, מַלְאַךְ הַמָּוְת דְּגָרִים מִיתָה לְאָדָם וּלְכָל דָּרִין דִּילֵיהּ, הָכִי, הַאי דַּרְכֵּיהּ לְקַטְלָא, וּבְגִין דָּא קָטִיל לַהֶבֶל.</p>\n<p>וְהַאי זוּהֲמָא דְאִתְנְטִיל מִנֵּיהּ אִיהִי לִילִי\"ת אִימָּא דְעִרֶב רַב, עֲלָהּ אִתְּמַר (משלי ה ה) רַגְלֶיהָ יוֹרְדוֹת מָוְת וכו', דְּאִיהִי סַם מָוְת דְּאֵל אַחֵר דְּאִיהוּ סמא\"ל, וְאִיהִי אִיבָּא דִילֵיהּ, גַּם לְרַבּוֹת אֵל אַחֵר, נָחָשׁ בְּגִינָהּ אִתְּמַר (בראשית ג ו) וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל, הָכָא רָזָא דְחַוָּה וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ וַיֹּאכַל גַּם לְרַבּוֹת, וּלְבָתַר חָזָא לֵיהּ דְּאִתְחָרַט כְּמָה דְאַתְּ אָמַר (שם ד יג) גָּדוֹל עֲוֹנִי מִנְּשׂוֹא, וּבְגִין דָּא (שם ב) קָנִיתִי אִישׁ אֶת יהו\"ה, הָכָא רָמִיז קֵנִי חוֹתֵן מֹשֶׁה, דְּעָתִיד לְאַהֲדָרָא בִּתְשׁוּבָה וּלְקַבָּלָא אָת בְּרִית, הֲדָא הוּא דִכְתִיב (שם טו) וַיָּשֶׂם יהו\"ה לְקַיִן אוֹת, אוֹת בְּרִית מִילָה לְאַגָּנָא עֲלֵיהּ.</p>\n<p>וּבְגִין דָּא וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, מַאי וַתּוֹסֶף אֶלָּא רָזָא דְמִלָּה וְלֹא יָסַף עוֹד לְדַעִִתָּהּ (שם לח כו), בְּגִין הַהוּא זוּהֲמָא דְנָפִיק מִנֵּיהּ, וְחָמָא אִתְפַּשְׁטוּתֵיהּ בְּכָל דָּרָא, כֵּיוָן דְּחָמָא לַהֶבֶל דְּאִתְפַּשְׁטוּתֵיהּ בְּכָל דָּרָא לְטָב, אָמַר וַתּוֹסֶף לָלֶדֶת, אוֹסִיפַת אִיהִי כַּמָּה קָרְבָּנִין וְכַמָּה תַּחֲנוּנִין וְכַמָּה בִּכְיָין בְּגִינֵיהּ, כֵּיוָן דְּאִיהוּ הֲוָה עָתִיד לְדַכָּאָה זוּהֲמָא דִילֵיהּ מֵעָלְמָא, וְהָא קֹהֶלֶת אָמַר (קהלת ח יד) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים אַשֶׁר מַגִיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, הָכָא אִתְגְּלֵי צַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ, אִית הֶבֶל, וְאִית הֶבֶל וַעֲלַיְיהוּ אִתְּמַר (שם י ב) לֵב חָכָם לִימִינוֹ וְלֵב כְּסִיל לִשְׂמֹאלוֹ, בְּשַׁגַּם זֶה הֶבֶל, וְהָא אוּקְמוּהוּ בְּשַׁגַּם זֶה מֹשֶׁה, מֹשֶׁה זֶה שֵׁת, וְאִיהוּ שֵׁם, וְאִיהוּ הֶבֶל, וְהֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר.</p>\n<p>וְרָזָא דְמִלָּה (ישעיה סג יא) אַיֵּה הַשָּׂם בְּקִרְבּוֹ, דְּאִיהוּ (שמות ג יג) מַה שְּׁמוֹ, וְדָא אָדָם דְּאִיהוּ רְבִיעָאָה, וּבְגִינֵיהּ אִתְּמַר (עמוס ב ו) וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, לֹא אֲשִׁיבֶנּוּ בְגִלְגּוּלָא יַתִּיר, כֵּיוָן דְּנָח בֵּיהּ אֲבוֹי דְּאִיהוּ אָדָם, בְּהַהוּא זִמְנָא אִשְׁתְּמוֹדָע (משלי ל ד) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע, וְדָא אִיהוּ רָזָא מַה שְּׁמוֹ מָה אוֹמַר אֲלֵיהֶם, וְדָא אִיהוּ מֶרְכַּבְתָּא שְׁלֵימָא, ש תְּלַת חֵיוָון, דְּרָכִיב עֲלַיְיהוּ מ\"ה, וַעֲלַיְיהוּ אִתְּמַר הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל</p>"],[9500011234,"<p>פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית ד ב) וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, וַוי לְעָלְמָא דְאִית לוֹן עַיְינִין וְלָא חָזָאן, אוּדְנִין וְלָא שָׁמְעִין בְּרָזִין דְּאוֹרַיְיתָא, וְאָזְלִין בָּתַר בִּצְעִין דְּהַאי עָלְמָא, תָּא חֲזִי קַיִן אִיהוּ יֵצֶר הָרָע, הֶבֶל יֵצֶר הַטּוֹב, הֶבֶל אִיהוּ הַלֵּב, וְאִינוּן תְּרֵי בָּתֵּי לִבָּא, הֲדָא הוּא דִכְתִיב (קהלת י ב) לֵב חָכָם לִימִינוֹ וְלֵב כְּסִיל לִשְׂמֹאלוֹ, לֵב חָכָם לִימִינוֹ דָא הֶבֶל, דְּאִתְּמַר בֵּיהּ וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, אִיהוּ תוֹסֶפֶת רוּחַ הַקֹּדֶשׁ, קַיִן אִיהוּ רוּחַ הַטּוּמְאָה דְאִיהוּ גָרַע וְלָא אוֹסִיף, קַיִן גּוּפָא, קַן לְתַרְוַיְיהוּ, וּבְגִינָהּ אִתְּמַר אַל תִּסְתַּכֵּל בְּקַנְקַן אֶלָּא בַּמֶּה דְאִית בֵּיהּ, וַדַּאי קַיִן אִיהוּ לִבָּא, דְאִיהוּ קְלִיפָה דֶאֱגוֹזָא, לַאו הַהוּא דִלְעִילָא דְאִיהוּ אִיבָּא דְאִילָנָא דְחַיֵּי, וּבְגִין דְּהַאי קַיִן אִית בֵּיהּ טַב וּבִישׁ, אִתְּמַר בֵּיהּ (בראשית ב יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, עַד דְּאִתְעַבַּר הַהִיא קְלִיפָה מִנֵּיהּ דֶּאֱגוֹזָא, אִיבָּא אִתְקְרִי מִיתָה וְחַיֵּי אוֹר וְחֹשֶׁךְ, הֲבַל טַב וַהֲבַל בִּישׁ, הֲבַל דְּאוֹרַיְיתָא דְאִיהוּ לַהַב, עֲלָהּ אִתְּמַר (תהלים כט ז) קוֹל יהו\"ה חֹצֵב לַהֲבוֹת אֵשׁ, וְדָא ה' דְּמֹשֶׁה, מ' מֹשֶׁה, ש' שֵׁת, דְּאִתְּמַר בֵּיהּ (שמות ב י) כִּי מִן הַמַּיִם מְשִׁיתִיהוּ, ש' שֵׁם, וְלַאו לְמַגָּנָא הֲוָה שֵׁם קוֹבֵעַ מֶדְרָשׁוֹת בְּאוֹרַיְיתָא, וַהֲוָה שֵׁת סִיּוּמָא דְאַלְפָא בֵּיתָא, שֵׁת בְּגִין (תהלים ח ז) כֹּל שַׁתָּה תַחַת רַגְלָיו.</p>\n<p>וְהֶבֶל מִסִּטְרָא דִימִינָא אִיהוּ כְּלִיל ז' הֲבָלִים, וְאִינוּן אבגית\"ץ וכו', שִׁית סָלְקִין, דְּאִינוּן לְהָבִים בְּשִׁית עִזְקָאן דְּקָנֶה, וַהֲבַל דְּפֶה שְׁבִיעָאָה, וּלְקִבְלַיְיהוּ אָמַר דָּוִד שֶׁבַע קָלִין דְּהָבוּ לַיהו\"ה בְּנֵי אֵלִים, (תהלים כט) וְעַל אִלֵּין שֶׁבַע אִתְּמַר (דברים ח ג) כִּי לֹא עַל הַלֶּחֶם לְבַדּוֹ יִחְיֶה הָאָדָם כִּי עַל כָּל מוֹצָא פִי יהו\"ה יִחְיֶה הָאָדָם, וְאִלֵּין ז' קָלִין סָלְקִין בְּז' רְקִיעִין, וְאִית ז' דִּשְׂמָאלָא דְנָחֲתִין בְּשִׁבְעָה אַרְעִין, וַעֲלַיְיהוּ אָמַר קֹהֶלֶת (קהלת ג כז) (כי) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמָעִִלָה וכו'.</p>\n<p>שִׁבְעָה הֲבָלִים טָבִין אִלֵּין אִינוּן שֶׁבַע שְׁנֵי הַשָּׂבָע, וּלְקִבְלַיְיהוּ אָחֳרָנִין לָקֳבֵל שֶׁבַע שְׁנֵי הָרָעָב, אִלֵּין הֲבָלִים דְּחַיֵּי, וְאִלֵּין הֲבָלִים דְּמִיתָה, וּבְגִין דָּא יֵשׁ הֶבֶל וְיֵשׁ הֲבָלִים, ה' לֵב, ד' אַרְבַּע חֵיוָון דְּכָרְסַיָּיא, ו' שִׁית דַּרְגִּין דְּכָרְסַיָּיא, וַעֲלַיְיהוּ שַׁרְיָין עֲשַׂר אֲמִירָן דְּאִינוּן י', ו' דְּנָפִיק מֵהֶבֶל אִיהוּ קוֹל דְּאִיהוּ פּוֹרֵחַ בְּאַוִּיר, דְּאִיהוּ אוֹר חָמֵשׁ אוֹר וַדַּאי אִינוּן ה' עִלָּאָה, י' דִּבּוּר וַאֲמִירָה, וְאִינוּן הֲבָלִים הֲבַל סָלִיק בְּה' עִלָּאָה, וַהֲבַל נָחִית בְּה' תַּתָּאָה, נָחִית דִּבּוּר, וּבְאִלֵּין הֲבָלִים סָלִיק בְּחַד קָלָא סָלִיק, וּבְדָא נָחִית, בְּה' תַּתָּאָה סָלִיק קָלָא דְאִיהוּ ו', בְּה' עִלָּאָה נָחִית דִּבּוּר דְּאִיהוּ י'.</p>\n<p>וַהֲבָלִים סָלְקִין וְנָחֲתִין בְּלִבָּא, וְהִנֵּה מַלְאֲכֵי אלהי\"ם סָלְקִין וְנָחֲתִין תַּמָּן וְאִינוּן י\"ו, ה' תַּתָּאָה מוּצָב אַרְצָה, וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה דָא ה' עִלָּאָה דְאִתְקְרֵי הַשָּׁמָיְמָה, וְאִם לָא סָלְקִין בְּמַחֲשָׁבָה דְאִיהִי יו\"ד ה\"א וא\"ו ה\"א, לָא מִסְתַּכְּלִין בִּצְלוֹתִין, אִלֵּין הֲבָלִים דְּלַאו אִינוּן מִסִּטְרָא דְיִחוּדָא, וַהֲבָלִים אָחֳרָנִין אִינוּן בְּפִירוּדָא, וְסָלְקִין בְּמַחֲשָׁבָה בִּישָׁא, וּבְגִין דְּאִית תַּמָּן פִּירוּדָא אִתְּמַר בְּמַחֲשָׁבָה דִלְהוֹן מַחֲשָׁבָה בִּישָׁא מִצְטָרְפָא לְמַעֲשֶׂה, (והבלים דלית בהון פרודא מחשבה דלהון מצטרפא למעשה).</p>\n<p>וְעִקָּר דְּאַרְבַּע אַתְוָון וַעֲשַׂר אַתְוָון אִיהִי מַלְכוּתָא, דְאִיהִי כְלִילָא מִכָּל עֲשַׂר סְפִירָן, וּבֵיהּ צָרִיךְ כֹּלָּא לְאַכְלָלָא, דְּכָל מָאן דְּנָטִיל מַלְכוּת בְּלָא תֵּשַׁע סְפִירָן אִיהוּ מְקַצֵּץ בַּנְּטִיעָן, וְכָל מָאן דְּנָטִיל תֵּשַׁע סְפִירָן בְּלָא מַלְכוּת אִיהוּ כּוֹפֵר בְּעִיקָר.</p>\n<p>הֲבָלִים דְּסִטְרָא אָחֳרָא עֲלַיְיהוּ אִתְּמַר (ירמיה י טו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעִִתּוּעִים, דְּאִינוּן הֲבָלִים סָלְקִין בְּנִבְלוּת הַפֶּה וּבְשִׁקְרוּת, וְכֻלְּהוּ סָלְקִין לְגַבֵּי מוֹחָא אִית חַמָּה וּלְבָנָה וְכֹכְבַיָּא וּמַזָּלַיָּא בִרְקִיעִין דְּאִינוּן קְלִיפִין, דַּעֲלַיְיהוּ אִתְּמַר (ישעיה ה יח) הוֹי מוֹשְׁכֵי הֶעָוֹן בְּחַבְלֵי הַשָּׁוְא, וַעֲלַיְיהוּ אִתְּמַר (שם נא ו) כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ, וְחָפְרָה הַלְּבָנָה וּבוֹשָׁה הַחַמָּה וכו' (שם כד כג), וְכַמָּה הֲבָלִים אִית לוֹן דְּכֻלְּהוּ מַלְיָין שֶׁקֶר וְשָׁוְא, וְכָל מָאן דְּאַפִּיק מִלִּין דְּשִׁקְרָא כַּמָּה מַלְאֲכֵי חַבָּלָה פָּתְחִין גַּדְפַיְיהוּ לְקִבְלוֹן, הֲדָא הוּא דִכְתִיב (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וכו', וְאִלֵּין מִלּוּלִין אִינוּן בָּנִין כַּמָּה בִּנְיָינִין.</p>"],[9500011235,"<p>אמר המגיה, הנמשך אחר זה כבר נדפס בדף ק\"ד ע\"א, אמנם אחר כך מצאתי זאת הנסחא מדוייקת יותר מהאחרת, וכדי שלא לכפול הדברים ארמוז לך החלוף שיש ביניהם בלבד, בזאת הנסחא לא מצאתי או אשא על מיא בשורה ל', ובשורה ל\"ד נקודין מן י' טעמים מן ו' איהי בת קול, ובדף ק\"ה ע\"א שורה ז' צ\"ל ואיהי לב דכלהו בה אתכלילן ומינה נפיק דפיקו, ובשורה ט' וכד דפיק, ובשורה י' צ\"ל רשפים ובשורה י\"ב נחית צ\"ל אחיד, דף ק\"ד ע\"ב בשורה י\"ו דא צ\"ל דמלה, בשורה י\"ח ד' דילה צ\"ל ד' דלה, שורה ך' אויר קדמון צ\"ל אוירא קדמאה.</p>\n<p>אמר המגיה זה התקון מצאתיהו מפוזר ומפורד ומוטעה, והרבה עמלתי וטרחתי להגיהו ולסדר הדברים על אופניהם, ובמקומות ממנו כתבתי הדברים פעמים מפני חלוף הנסחאות.</p>\n<p>עוד ראה זה מצאתי.</p>\n<p>וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל (בראשית ד ב), תָּא חֲזִי הֶבֶל אִיהוּ הַלֵּב, וְאִית ב' בָּתִּים בְּלִבָּא, (קהלת י ג) לֵב חָכָם לִימִינוֹ הֶבֶל, לֵב כְּסִיל לִשְׂמֹאלוֹ דָא הֶבֶל, קַיִן אִיהוּ יָנִיק מִתַּרְוַיְיהוּ, וְאִיהוּ עִץ טוֹב וָרָע, וְקַיִן אִיהוּ זוּהֲמָא דְנָחָשׁ דְּאַטִּיל בְּחַוָּה, וַעֲלֵיהּ אִתְּמַר (ישעיה יד כט) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע, מָה אָרְחֵיהּ דְּחִוְיָא לְמִקְטַל, כַּךְ דָּא קָטַל, וּלְבָתַר אִתְחַרַט, וּבְגִין דָּא (בראשית ד טו) וַיָּשֶׂם יהו\"ה לְקַיִן אוֹת, אוֹת בְּרִית מִילָה, וּבְגִין דָּא אָמַר (שם) קָנִיתִי אִישׁ אֶת יהו\"ה, וְאַף עַל גַּב דְּקַיִ\"ן אִיהוּ זוּהֲמָא, יָכִיל לְמֶעֱבַד נָקִ\"י, כְּגוֹן יִתְרוֹ דְאִתְּמַר בֵּיהּ (שופטים א טז) וּבְנֵי קֵנִי חוֹתֵן מֹשֶׁה.</p>\n<p>וְרָזָא דְמִלָּה הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת, וְאָמְרוּ קַדְמָאִין אִית הֶבֶל וְאִית הֶבֶל, יֵשׁ צַדִּיקִים שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים וכו', (קהלת ח יד) אָמַרְתִּי שֶׁגַּם זֶה הָבֶל, הֶבֶל דִּימִינָא ה' כָּרְסַיָּא, ו' שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, ד' אַרְבַּע חֵיוָון, אִלֵּין הֲבָלִים אִינוּן לְבוּשָׁא לְתִפְאֶרֶת וּמַלְכוּת דְּאִינוּן ו\"ה, י\"ה כְּלִילָן, י' בְּאַוִּיר, ה' תַּתָּאָה דִבּוּר דְּסָלִיק בַּהֶבֶל, וְכֹלָּא אִתְכְּלִיל בִּשְׁמָא דְבַר נַשׁ דְּצַלִּי צְלוֹתָא אוֹ דְעָסִיק בְּאוֹרַיְיתָא, אֲבָל הֲבָלִים אָחֳרָנִין דְּאִתְעֲבִידָן בְּאַרְעָא, סָלְקִין בְּאַוִּיר דְּהַאי עָלְמָא בְּקוֹל וְדִבּוּר דְּחוֹל, וְיִשְׂרָאֵל מְצַלִּין בְּהוֹן הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל, וְאִית אָחֳרָנִין דְּאִתְּמַר בְּהוֹן (ירמיה י טו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעִִתּוּעִים, וְאִינוּן הֲבָלִים וְקוֹל וְדִבּוּר דְּנִבְלוּת הַפֶּה, אִינוּן מִסִּטְרָא דֶאֱלֹהִים אֲחֵרִים מְמַנָּן דִּשְׁאָר עַמִּין דְּאִינוּן סמא\"ל וְנָחָשׁ, עֲלַיְיהוּ אִתְּמַר בְּהַבְדָּלָה וּבֵין יִשְׂרָאֵל לְגוֹיִם, כָּל חַד כְּפוּם עוֹבָדוֹי כַּךְ בָּנֵי בִנְיָנָא, (קהלת ז יד) דְּזֶה לְעְִמַּת זֶה עָשָׂה הָאלהי\"ם.</p>\n<p>וְתָא חֲזִי מָאן דְּבִנְיָינָא דִילֵיהּ לְעִילָא בְסִטְרָא דְּדַכְיוּ, בְכָל אִלֵּין הֲבָלִים דְּאוֹרַיְיתָא וּצְלוֹתָא, עֲלֵיהּ אָמַר קְרָא (ישעיה לז טז) וָאָשִׂים דְּבָרַי בְּפִיךָ וכו' וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה, וְהָא אוּקְמוּהוּ אַל תִּקְרֵי עַמִּי, אֶלָּא עִמִּי, מָה אֲנָא בְמִלּוּלָא דִילִי עֲבָדִית שְׁמַיָּא וְאַרְעָא כְּמָה דְאַתְּ אָמַר (תהלים לג ו) בִּדְבַר יהו\"ה שָׁמַיִם נַעֲשׂוּ, כַּךְ אַנְתְּ בְּשׁוּתָּפוּ עִמִּי תַעֲבֵיד בְּמִלּוּלָא, אֲבָל אָחֳרָנִין דְּמַפְּקִין מִפּוּמַיְיהוּ הֲבָלִים דִּשְׁבוּעָה, עֲלַיְיהוּ אִתְּמַר (משלי ז כו) כִּי רַבִּים חֲלָלִים הִפִּילָה, וְאִלֵּין אִתְקְרִיאוּ חֲלָלִים, דִּמְחַלְּלִין שֵׁם יהו\"ה, וְנָפְקִין הֲבָלִים מִפּוּמַיְיהוּ וְקָלָא וְדִבּוּרָא לְשִׁקְרָא וְאוֹמָאָה לְשִׁקְרָא, וְדָכְרִין שְׁמֵיהּ לְמַגָּנָא וּלְשִׁקְרָא, בְּהַהוּא שְׁמָא דְנָפְקִין לְבַטָּלָא וּלְשִׁקְרָא בָּנִין לוֹן בִּנְיָנִין דְּבַטְלִין לוֹן מֵעָלְמָא, הֲדָא הוּא דִכְתִיב (ירמיה ב ז) לַשָּׁוְא הִכֵּתִי אֶת בְּנֵיכֶם, וַוי לוֹן לִבְנֵי נָשָׁא דְנָפְקִין מִפּוּמַיְיהוּ מִלּוּלִין וְאוֹמָאִין דְּשִׁקְרָא, טַב לוֹן דְּלָא יֵתוּן לְעָלְמָא, קָמוּ חַבְרַיָּא כֻּלְּהוּ וְאָמְרוּ רַחֲמָנָא לְשֵׁזְבָן רַחֲמָנָא לְשֵׁזְבָן.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, רַבָּנָן, כָּל אִלֵּין בִּנְיָנִין תַּלְיָין בְּמַחֲשָׁבָה, כְּמָה דְאַשְׁכַּחְנָא בְּקַיִן וְהֶבֶל, קַיִן הָיָה עוֹבֵד אֲדָמָה וּמַיְיתֵי בְּקָרְבָּנָא פִּשְׁתִּים, מֵהַהוּא סִטְרָא דְעִִרְוָה, הֲוָה מַחֲשָׁבָה לְקָרְבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עִִרְוָה, וּמִנַּיִן דְּפִשְׁתִּים אִיהוּ מִסִּטְרָא דְעִִרְוָה שֶׁנֶּאֱמַר (שמות כח מב) וַעֲשֵׂה לָהֶם מִכְנְסֵי בָד לְכַסּוֹת בְּשַׂר עִִרְוָה, הֶבֶל הֲוָה רוֹעִִה צֹאן, קָרִיב קָרְבָּנָא מִבְּכוֹרוֹת צֹאנוֹ, הֲדָא הוּא דִכְתִיב (בראשית ד ד) וְהֶבֶל הֵבִיא גַם הוּא מִבְּכוֹרוֹת צֹאנוֹ,</p>"],[9500011236,"<p>מַחֲשַׁבְתֵּיהּ הֲוָה בְהַהוּא אֲתַר דְּאִתְּמַר בֵּיהּ, (דניאל ז ט) וְעַתִּיק יוֹמִין יְתִיב לְבוּשֵׁהּ כִּתְלָג חִוָּור וּשְׂעַר רֵאשֵׁהּ כַּעֲמַר נְקֵא, וְקוּדְשָׁא בְּרִיךְ הוּא מַחֲשַׁבְתֵּיהּ טָבָא צָרְפָה לְמַעֲשֶׂה, וּבְגִין דָּא קַבִּיל לֵיהּ, וּמַחֲשָׁבָה רָעָה לָא מְצָרְפָה לְמַעֲשֶׂה, וְדָא הוּא קָרְבָּנָא דְקַיִן, וּבְגִין דָּא חָרָה לוֹ, מִיָּד וַיֹּאמֶר יהו\"ה לְקַיִן לָמָּה חָרָה לָךְ וכו', הֲלֹא אִם תֵּטִיב שְׂאֵת (בראשית ד ו), אִם תֵּטִיב עוֹבָדָךְ שְׂאֵת, אֲנָא מַאֲרִיךְ לָךְ וְאֶטּוֹל מַטּוּלָךְ עָלַי, וּמְנָלָן דִּשְׂאֵת מַטּוּלָא דְחוֹבִין הוּא, דִּכְתִיב (ישעיה א יד) נִלְאֵתִי נְשׂוֹא, וְאִם לֹא תֵטִיב עוֹבָדָךְ לַפֶּתַח חַטָּאת רוֹבֵץ, וְדָא פֶתַח דְּגֵיהִנָּם, דְּתַמָּן חוֹבִין דִּילָךְ שָׁלְטִין עֲלָךְ, וְאִם תֵּטִיב עוֹבָדָךְ אַתָּה תִּמְשׁוֹל בּוֹ.</p>\n<p>רַשִּׁיעַיָּא לָא שַׁלִּיט בְּהוֹן מוּסָר אֶלָּא נָטְרִין דְּבָבוּ, כְּגַוְונָא דְעִשָׂו וַיִּשְׂטֹם עִשָׂו אֶת יַעֲקֹב (בראשית כז מא), יַעֲקֹב כְּגַוְונָא דְהֶבֶל וְעִשָׂו כְּגַוְונָא דְקַיִן, וַיֹּאמֶר מֶה עָשִׂיתָ וכו' (שם ד י) חוֹבָא דָּא דִקְטַלְתְּ לַאֲחוּךְ לָא עֲבַדְתְּ לֵיהּ אֶלָּא לִשְׁמָא דְאִתְקְרִי מ\"ה, מָ\"ה אֲעִידֵךְ וְאַסְהִיד עֲלָךְ, וְאִיהִי תָּבְעָה לָךְ, וְלָא עוֹד אֶלָּא מ\"ה דְאִיהוּ אָדָם דְּעָבִיד לָךְ, גָּרַם דָּא דְּאַפִּיק מַלְאַךְ הַמָּוְת בָּךְ לְעָלְמָא, וְדָא אִיהוּ פּוֹקֵד עֲוֹן אָבוֹת עַל בָּנִים (שמות כ ה), וְהָא אִתְּמַר אִם אוֹחֲזִין מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם, אֶלָּא כַּךְ הֲוָה עוֹבְדֵי אֲבוּהָ הֲוָה בִידֵיהּ, עַל סִבָּה דְאִשָּׁה הֲוָה, כְּמָה דְאִתְּמַר וַיְהִי בִּהְיוֹתָם בַּשָּׁדֶה, וְאֵין שָׂדֶה אֶלָּא אִתְּתָא, אִתְּתָא גָרְמַת מִיתָה לְאָדָם, וְגָרְמַת מִיתָה לְהֶבֶל, כְּמָה דְאִתְּמַר בְּיַעֲקֹב עִם מְמַנָּא דְעִשָׂו וַיֵּאָבֵק אִישׁ עִמּוֹ (בראשית לב כה), כְּגַוְונָא דָא הֲוָה קַיִן וְהֶבֶל, וְנָצַח הֶבֶל לְקַיִן, וְאִיהוּ מִסִּטְרָא דְרַחֲמֵי דְחַיִּיס עֲלוֹי וְלָא בָעָא לְמִקְטְלֵיהּ, וְקָם הוּא וְקָטְלֵיהּ, וְאִתְּתָא גָרְמָא דָא, עֲלָהּ אִתְּמַר (משלי ה ה) רַגְלֶיהָ יוֹרְדוֹת מָוְת, וּבְקִנְאָה דִילֵיהּ קָטִל לֵיהּ.</p>\n<p>וַיֹּאמֶר קוֹל דְּמֵי אָחִיךָ צוֹעֲקִים אֵלַי מִן הָאֲדָמָה (בראשית ד י), אַנְתְּ הוּא בְרֵיהּ דְּחִוְיָא דְגָרַם מִיתָה לְאָדָם, דְּאִתְּמַר בֵּיהּ (שם ג יד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, כַּךְ אִית לָךְ לְיַרְתָא מִנֵּיהּ, דְּעוֹבָדָא דִילֵיהּ בִּידָךְ, בְּגִין דָּא אָרוּר אַתָּה מִן הָאֲדָמָה אֲשֶׁר פָּצְתָה אֶת פִּיהָ, דָא הֲוָה אַרְעָא דְּלַיִּיט לָהּ קוּדְשָׁא בְּרִיךְ הוּא תֵּשַׁע לְוָוטִין, לַיִּיט לְקַיִן חַד לְאַשְׁלָמָא לַעֲשָׂרָה, וּבְגִין דָּא אָמַר (שם יא) אָרוּר אַתָּה מִן הָאֲדָמָה וכו', כִּי תַעֲבוֹד אֶת הָאֲדָמָה וכו' דִּתְּהֵא תָּשַׁשׁ חֵילָהָא לְגַבָּךְ, וְלָא יִפְּקוּן מִינָךְ מַלְכִין וְשַׁלִּיטִין.</p>\n<p>נָע וָנָד תִּהְיֶה בָאָרֶץ, דַּאֲנָא אֲמָרִית לְאָדָם וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה (שם א כו), דְּאִנּוּן בְּנֵי נָשָׁא דְתַלְיָין בְּמַזָּלוֹת, דְּדַמְיָין לְחֵיוָון וּבְעִירָן וְעוֹפוֹת, כֻּלְּהוּ אָזְלוּ לְגַבָּךְ לְקַטְלָא לָךְ, וְאַנְתְּ תֵּזִיל נָע וָנָד מִקַּדְמָאֵי, נָ\"ע וָנָ\"ד עָוֹ\"ן דָּ\"ן, וְעוֹד נָע וָנָד בְּגִין דְּאַנְתְּ עָוֹ\"ן דְּנִדָּ\"ה, וּבַנִּדָּה אִתְעֲבִידַת דְּאִיהִי זוּהֲמָא דְהִטִּיל נָחָשׁ לְחַוָּה, בְּגִין דָּא נָע וָנָד תִּהְיֶה, וְעוֹד נָע בְּגִין דְּאַנְתְּ מִסִּטְרָא דְסמא\"ל, נָד בְּגִין דְּאַנְתְּ מִסִּטְרָא דְנָחָשׁ, נָע בְּעָלְמָא דֵין, נָד בְּעָלְמָא דְאָתֵי, דְּאִינוּן שְׁכִינְתָּא עִלָּאָה וּשְׁכִינְתָּא תַּתָּאָה, דְּנָטְלִין תַּרְוַיְיהוּ נוּקְמָא מִינָךְ.</p>\n<p>וּבְגִין דָּא כַּד שָׁמַע דְּבַאֲתַר עִלָּאָה דָא הֲוָה תַלְיָא הֶבֶל, מִיָּד וַיֹּאמֶר קַיִן אֶל יהו\"ה גָּדוֹל עֲוֹנִי מִנְּשׂוֹא (בראשית ד יג), הָכָא תָב בִּתְיוּבְתָּא וְאִתְחַרַט, בְּגִין דָּא וַיָּשֶׂם יהו\"ה לְקַיִן אוֹת (שם טו), הָכָא רָמַז אוֹת בְּרִית מִילָה דְקַבִּיל יִתְרוֹ, דְאִתְּמַר בֵּיהּ (שופטים א טז) וּבְנֵי קֵנִי חוֹתֵן מֹשֶׁה שֶׁנִּפְרַד מִקַּיִן, (צ\"ל (שם ד יא) וחבר הקני נפרד מקין), וּבְיִתְרוֹ אִתְתַּקַּן קַיִן מֵחוֹבֵיהּ, וְעוֹד בְּהַהוּא זִמְנָא קַבִּיל לֵיהּ, בְּגִין דְּאַחֲזֵי לֵיהּ בְּנוֹי דְקֵנִי חוֹתֵן מֹשֶׁה דַהֲווֹ עֲתִידִין לְמֶהֱוִי בְּלִשְׁכַּת הַגָּזִית, אָמַר וְכִי לְחַיָּיבָא קַבִּיל קוּדְשָׁא בְּרִיךְ הוּא בִּתְשׁוּבָה, עַל אַחַת כַּמָּה וְכַמָּה לַצַּדִּיקַיָּיא, מִיָּד וַיֵּצֵא קַיִן מִלִּפְנֵי יהו\"ה (בראשית ד טז), בְּהַאי נָפַק מִן דִּינָא, וְקַבִּיל עֲלֵיהּ כָּל מַה דְּאִתְגַּזַּר בֵּיהּ, דִּכְתִיב וַיֵּשֶׁב בְּאֶרֶץ נוֹד, מַה דְּאָמַר לֵיהּ נָד, שַׁוִּי עֲלֵיהּ ו' וְאִתְעֲבִיד נוֹד, וְדָא אִיהוּ דְאִתְּמַר בֵּיהּ וַיָּשֶׂם יהו\"ה לְקַיִן אוֹת לְבִלְתִּי הַכּוֹת אוֹתוֹ, דְּאִם הֲוָה נָד אִתְּמַר בֵּיהּ (שם) וְהָיָה כָל מוֹצְאִי יַהַרְגֵנִי, וּבְגִין דְּתָב בִּתְיוּבְתָּא וְקַבִּיל עֲלֵיהּ אוֹת בְּרִית, שַׁוִּי עֲלֵיהּ אוֹת ו' לְשֵׁזָבָא לֵיהּ, וְלָא עוֹד אֶלָּא דְשַׁוִּי לֵיהּ קִדְמַת עִדֶן, דִּבְגִינֵיהּ זָכָה לְגַן עִדֶן.</p>\n<p>וַיֵּדַע</p>"],[9500011237,"<p>קַיִן אֶת אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת חֲנוֹךְ (בראשית ד יז), כָּל אִלֵּין תּוֹלָדִין מָנְעִין לֵיהּ לְאַתְרָעָא בְהוֹן, וְאִינוּן חֲנוֹךְ וְעִירָד וּמְחוּיָאֵל וּמְתוּשָׁאֵל וְלֶמֶךְ, וְלֶמֶךְ נָטִיל תְּרֵי נְשִׁין עָדָה וְצִלָּה, עָדָה חֲנוֹךְ לְטָב, חֲנוֹךְ לְנַעַר עַל פִּי דַרְכּוֹ, צִלָּה חִנּוּכָא דְבִישׁ, וְדָא מַלְאַךְ הַמָּוְת דִּמְחַנֵּךְ לְבַר נַשׁ בְּחִנּוּכִין בִּישִׁין, עִירָד לְבָתַר אַעִיל רְעָדָה בְּבַר נַשׁ בְּאֵבָרִין דִּילֵיהּ, וּלְבָתַר דְּאַפִּיל לְבַר נַשׁ בְּחוֹבִין, אַלְשִׁין עֲלֵיהּ וְאַחֲזֵי לְאֵ\"ל כָּל מַה דְּעָבִיד, וְדָא אִיהוּ מְחוּיָאֵל מְחַוִּי אֵ\"ל, וּלְבָתַר נָחִית וַתָּשַׁשׁ חֵילֵיהּ וְקָטִיל לֵיהּ, וְדָא אִיהוּ מְתוּשָׁאֵל דְּתַמָּן מָוְת שְׁאֹל, וְאֵין מָוְת אֶלָּא עֲנִיּוּת, וּלְבָתַר אַמְלִיךְ עֲלֵיהּ וְדָא אִיהוּ לֶמֶךְ אִתְהַפַּךְ עֲלֵיהּ לְמֶלֶךְ, וּתְרֵין נְשִׁין דִּילֵיהּ חַד עָדָה דְמֵעִיד עַל חוֹבוֹי דְבַר נַשׁ, וְתִנְיָינָא צִלָּה דְאָזִיל עֲלֵיהּ כְּצֵל, כְּמָה דְאַתְּ אָמַר (איוב ח ט) כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ, וּכְתִיב (תהלים קמד ד) יָמָיו כְּצֵל עוֹבֵר.</p>\n<p>וַתֵּלֶד עָדָה אֶת יָבָל (בראשית ד כ), בָּתַר דְּקָטִיל לֵיהּ בַּעֲנִיּוּתָא, וְשָׁלְטִין עֲלֵיהּ עָדָה וְצִלָּה, יָבָל, כְּגַוְונָא דִשְׁמַיָּא וְאַרְעָא דְאִתְּמַר בְּהוֹן (ישעיה נא ו) כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה, וְיָבָל אִיהוּ אֲבִי יוֹשֵׁב אֹהֶל וּמִקְנֶה, דְכַנִּישׁ מָמוֹנָא, וּלְבָתַר אִתְּמַר בֵּיהּ (משלי יא ד) לֹא יוֹעִיל הוֹן, וְהָא אִתְּמַר דְּשַׁלִּיט עֲלֵיהּ עֲנִיּוּתָא דְאִיהוּ מָוְת, וְלֵית עֲנִיּוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּעֲנִיּוּתָא דְּאוֹרַיְיתָא, וְלֵית מָוְת כְּאִינוּן דְּעָבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא דְאִתְקְרִיאוּ מֵתִים, וּבְגִין דָּא אָמַר קְרָא (יחזקאל יא לב) שׁוּבוּ וִחְיוּ, וַאֲחִי יָבָל הָיָה אֲבִי כָּל תּוֹפֵשׂ כִּנּוֹר וְעְִגָּב, הַמְנַגְּנִין בְּכָל מִינֵי נִגּוּנִין, וּבַר נַשׁ דְּחָדֵי בְּהוּ וְאִשְׁתַּדַּל בְּהַבְלֵי עָלְמָא, עֲלֵיהּ אָמַר קֹהֶלֶת (קהלת יא ט) שְׂמַח בָּחוּר בְּיַלְדוּתֶךָ וכו', וּלְבָתַר מָה אָמַר לֵיהּ (שם) וְדָע כִּי עַל כָּל אֵלֶּה יְבִיאֲךָ הָאלהי\"ם בַּמִּשְׁפָּט, דַּעֲלַיְיהוּ אָמְרוּ מָארֵי מַתְנִיתִין, זִמְרָא בְּבֵיתָא חָרְבָּא בְּבֵיתָא, אֶלָּא וּשְׂמַחְתֶּם לִפְנֵי יהו\"ה אלהיכ\"ם (ויקרא כג מ), כְּגַוְונָא (דדוד) דְאִתְּמַר (ביה) (מלכים ב ג טו) וְהָיָה כְּנַגֵּן הַמְּנַגֵּן וַתְּהִי עָלָיו יַד יהו\"ה.</p>\n<p>וְצִלָּה גַם הִיא יָלְדָה אֶת תּוּבַל קַיִן, לוֹטֵשׁ כָּל חֹרֵשׁ נְחשֶׁת וּבַרְזֶל (בראשית ד כב), דָּא יֵצֶר הָרָע, דְּאִתְּמַר בֵּיהּ אִם יִצְרָךְ מִתְגַּבֵּר עֲלָךְ מָשְׁכֵהוּ לְבֵית הַמֶּדְרָשׁ וכו', וַאֲחוֹת תּוּבַל קַיִן נַעֲמָ\"ה דָא אִימָּן שֶׁל שֵׁדִים, וְלֶמֶךְ בְּשַׁעִִתָּא דְשַׁלִּיט עַל בַּר נַשׁ וְאִיהִי בֵּיהּ תַּקִּיף כְּאַבְנָא וּכְפַרְזְלָא, וְלָא עָסִיק בְּאוֹרַיְיתָא, שַׁלִּיט עֲלֵיהּ וְקָטִיל לֵיהּ, וְעָבִיד בֵּיהּ פֶּצַע וְחַבּוּרָה, כְּמָה דְאַתְּ אָמַר (שם כג) כִּי אִישׁ הָרַגְתִּי לְפִצְעִי וְיֶלֶד לְחַבּוּרָתִי, בְּהַהוּא זִמְנָא עָתִיד לְנַטְלָא קוּדְשָׁא בְּרִיךְ הוּא נוּקְמָא מִתַּרְוַיְיהוּ, הֲדָא הוּא דִכְתִיב (שם) כִּי שִׁבְעָתַיִם יוּקַם קָיִן וְלֶמֶךְ שִׁבְעִים וְשִׁבְעָה, הֲדָא הוּא דִכְתִיב (ישעיה כה ח) בִּלַּע הַמָּוְת לָנֶצַח.</p>\n<p>וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ וַתֵּלֶד בֵּן וַתִּקְרָא אֶת שְׁמוֹ שֵׁ\"ת, סִיּוּמָא דְאַלְפָא בֵּיתָא, וַעֲלֵיהּ אָמַר אִיּוֹב (איוב לח לו) מִי שָׁת בַּטּוּחוֹת חָכְמָה, מַאי חָכְמָה דָא דְחָסֵר מִנֵּיהּ י', דְּבָהּ הֲוָה שִׁית, דְּאִיהוּ בָרָא שִׁית, וְאִיהוּ רֵאשִׁית, וַהֲוָה אִתְּמַר בֵּיהּ (ישעיה מו י) מַגִּיד מֵרֵאשִׁית אַחֲרִית, הֲוָה מְשַׁמֵּשׁ שֵׁת בַּאֲתַר דְּהֶבֶל, וּבְגִין דְּחָסֵר מִנֵּיהּ י' אִתְקְרִי אַחֵר, בְּגִין דְּכַד חָב אָדָם פָּרַח מִנֵּיהּ י', וְעָבַד שֵׁת בְּלָא י' דְּאִיהִי חָכְמָה, וּבְגִין דָּא שֵׁירוּתָא הֲוָה מִן ח', דְּאִינוּן ח' יוֹמִין דִּבְּרִית מִילָה, כְּמָה דְאַתְּ אָמַר (בראשית ד כו) אָז הוּחַל לִקְרֹא בְּשֵׁם יהו\"ה, וּמִתַּמָּן עָבְרוּ בְּרִית מִילָה, וְאַעֲבָרוּ מִנֵּיהּ עָרְלָה וּפְרִיעָה לְמַעִִלָה בְּד' וְלָא בְּח', דְּשֵׁירוּתָא דְח' אִיהִי בִּינָה, לַמְנַצֵּחַ עַל הַשְּׁמִינִית (תהלים יב א), וַעֲלָהּ אִתְּמַר אָז הוּחַל, וְעוֹד אָז הוּחַל לִישָׁנָא דִצְלוֹתָא, כְּמָה דְאַתְּ אָמַר (ישעיה נח ט) אָז תִּקְרָא וַיהו\"ה יַעֲנֶה, דָּא הוּא נְטוּרָא טָבָא, דְּאַף עַל גַּב דְּהֶבֶל קָטִיל לֵיהּ קַיִן, דְּמִנֵּיהּ הֲוָה נָפִיק מָאן דְּנוֹקִים לֵיהּ, הֲדָא הוּא דִכְתִיב (שמות טו א) אָז יָשִׁיר מֹשֶׁה, רוֹעִִה נוֹקִים לְרוֹעִִה, וּלְבָתַר אָז אֶהְפּוֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יהו\"ה (צפניה ג ט), אֲבָל כַּד עֲמָלֵק דְּאִינוּן</p>"],[9500011238,"<p>בְּכוֹרֵי מִצְרָיִם עִרֶב רַב מְעוּרָבִין בְּיִשְׂרָאֵל, עֲלַיְיהוּ אִתְּמַר (דברים כה יט) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק, דְּלָא אִשְׁתָּאַר מִנְּהוֹן שָׂרִיד, דְּאִלֵּין אִינוּן עִרְבוּבְיָא מִכָּל אוּמִין וַאֲפִילוּ מִקַּיִן, וּמִיָּד דְּיִתְמַחוּן מֵעָלְמָא אָז הוּחַל לִקְרֹא בְּשֵׁם יהו\"ה (בראשית ד כו).</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית, וְדָא מטטרו\"ן, אוֹת בַּצָּבָא דִילֵיהּ, וּבְגִינֵיהּ אִתְּמַר (שם טו) וַיָּשֶׂם יהו\"ה לְקַיִן אוֹת לְאַגָּנָא עֲלֵיהּ, וּמַה דַּהֲוָה אָזִיל נָע וָנָד בְּגִלְגּוּלָא, אִתְעֲבִיד נוֹד, מִיָּד וַיֵּשֶׁב בְּאֶרֶץ נוֹד קִדְמַת עִדֶן, וְדָא אוֹת דִּבְּרִית מִילָה דְקַנְיֵיהּ עֲלֵיהּ בַּאֲחוּהָ בְּגִין דְּנוֹלַד מָהוּל, וּבְאָן אֲתַר זָכֵי לֵיהּ, בְּקֵנִי, בְּגִין דְּחָזַר תַּמָּן בִּתְיוּבְתָּא, וְנָפְקוּ בְּנוֹי מִינֵיהּ דְּעָאלוּ לְגַן עִדֶן, וּבְגִין דָּא וַיֵּשֶׁב בְּאֶרֶץ נוֹד קִדְמַת עִדֶן.</p>\n<p>לְבָתַר עָבִיד תּוֹלָדִין מִסִּטְרָא דְרָע, וְאִתְפַּשְׁטוּ בְגִלְגּוּלִין בְּעָלְמָא, וַעֲלַיְיהוּ אִתְּמַר (שם יז) וַיֵּדַע קַיִן אֶת אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת חֲנוֹךְ, חֲנוֹךְ מִסִּטְרָא דְקַיִן, וְדָא יֵצֶר הָרָע חִנּוּכָא לְבִישׁ, וְאִית חֲנוֹךְ מִסִּטְרָא דֶאֱנוֹשׁ, דְּאִיהוּ יֵצֶר הַטּוֹב חִנּוּכָא לְטָב, וְאִתְּמַר בֵּיהּ (שם ה כה) וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת הָאלהי\"ם וְאֵינֶנּוּ כִּי לָקַח אוֹתוֹ אלהי\"ם, וְדָא חֲנוֹךְ דְּאִתְהַפַּךְ בִּשְׂרֵיהּ לְלַפִּיד אֵשׁ.</p>\n<p>וּתְלָתָא אִינוּן אָדָם שֵׁת אֱנוֹשׁ, אֱנוֹשׁ דְּמִתַּמָּן אִתְיַחֲסוּ כָּל דָּרִין, הֲדָא הוּא דִכְתִיב (שם ד כו) אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה, מִתַּמָּן נִתְפַּשְׁטוּ כָּל גִּלְגּוּלִין דְּצַדִּיקַיָּיא, חֲנוֹךְ דְּנָפִק מֵאֱנוֹשׁ אִיהוּ מטטרו\"ן דְּנֶהְפַּךְ בְּשָׂרוֹ לְלַפִּיד אֵשׁ, וְאִיהוּ נוריא\"ל, וְעַל תַּרְוַיְיהוּ אִתְּמַר (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, רָצוֹא דָא נוריא\"ל, וָשׁוֹב דָּא מטטרו\"ן, הָכִי סָלְקִין בְּחוּשְׁבָּן, כְּמַרְאֵ\"ה הַבָּזָק, אֶלָּא אִיהוּ כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן (שם כח), דְּאִתְּמַר בֵּיהּ (בראשית ט יד) וְהָיָה בְּעַנְנִי עָנָן עַל הָאָרֶץ וְנִרְאֲתָה הַקֶּשֶׁת בֶּעָנָן, וּבְגִינֵיהּ אִתְּמַר (שם טו) וְלֹא יִהְיֶה מַבּוּל לְשַׁחֵת כָּל בָּשָׂר, בְּגִין דְּאִתְהַפַּךְ בְּשָׂרוֹ לְלַפִּיד אֵשׁ, וְכָל מַלְאָכִין דִּמְמַנָּן עַל נִשְׁמָתִין דְּגִלְגּוּלִין מִתַּמָּן הֲווֹ.</p>\n<p>וְעוֹד כְּמַרְאֵה הַקֶּשֶׁת, עֲלֵיהּ אִתְּמַר לְמֹשֶׁה (שמות כה מ) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר, כַּמַּרְאֶה אֲשֶׁר הֶרְאָה יהו\"ה אֶת מֹשֶׁה כֵּן עָשָׂה אֶת הַמְּנוֹרָה (במדבר ח ד), וְדָא מטטרו\"ן, מ' דִּילֵיהּ מְנוֹרָה, נוריא\"ל נוּ\"ר דִּילֵיהּ, וְהוּא ט\"ט, וְהָיוּ לְטֹטָפוֹ\"ת בֵּין עִינֶיךָ, וְכֹלָּא אִתְפַּשַּׁט מֵאֱנוֹשׁ, וּבְגִין דָּא אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה.</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית, וְאִינוּן שִׁית הֵיכָלִן, אִימָּא עִלָּאָה שְׁבִיעָאָה, וּבְאִלֵּין שִׁית וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ וַתֵּלֶד בֵּן וַתִּקְרָא אֶת שְׁמוֹ שֵׁת וכו' (בראשית ד כה), שֵׁת סִיּוּמָא דְאַתְוָון, תַּחַת הֶבֶל, הֲדָא הוּא דִכְתִיב (תהלים ח ז) כֹּל שַׁתָּה תַחַת רַגְלָיו, אִסְתַּלַּק י' מִן שִׁית וּנְחִיתַת בֵּיהּ ה' מִן הֶבֶל וְאִתְעֲבִיד שַׁתָּה, כֹּל שַׁתָּה תַחַת רַגְלָיו.</p>\n<p>וְעוֹד שֵׁת עַל שֵׁם (שמות ב ו) כִּי מִן הַמַּיִם מְשִׁיתִיהוּ, וְעוֹד שֵׁת עֲלֵיהּ אָמַר אִיּוֹב (איוב לח לו) מִי שָׁת בַּטּוּחוֹת חָכְמָה, וְדָא י' דְּבָהּ הֲוָה שִׁית, אוֹ מִי נָתַן לַשֶּׂכְוִי בִינָה (שם) דָא ה' מִן הֶבֶל, וְשֵׁת אִיהוּ גִלְגּוּלָא קַדְמָאָה דְהֶבֶל, לְהַהוּא דְאִתְּמַר בֵּיהּ בְּשַׁגָּם זֶה הֶבֶל, בְּשַׁגָּם זֶה מֹשֶׁה, וְהָא אוּקִימְנָא הַהוּא דְאִתְּמַר בֵּיהּ (שמות טו א) אָז יָשִׁיר מֹשֶׁה, וּבְגִין דָּא אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה (בראשית ד כו), הוּחַל תַּמָּן הַתְחָלָה דְגִלְגּוּלָא קַדְמָאָה.</p>\n<p>וְאִתְפַּשְׁטוּתָא דְאָת י' לְעִילָא מִשֵּׁת (נ\"א משית), אִתְפַּשְׁטַת עַד סְפִירָה שְׁתִיתָאָה דַרְגֵּיהּ דְּיַעֲקֹב, וְדָא אֶבֶן הַשְּׁתִיָּה דְמִתַּמָּן הוּשָׁתַת עָלְמָא, דְאִתְּמַר בָּהּ (שם מט כד) מִשָּׁם רוֹעִִה אֶבֶן יִשְׂרָאֵל, וְאַבַּתְרֵיהּ אָז, וְדָא מֹשֶׁה דְמִדְכְּרִין לֵיהּ בָּתַר יַעֲקֹב, וּבְגִין דָּא אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה, מִתַּמָּן וְאֵילֵךְ אָז תִּקְרָא וַיהו\"ה יַעֲנֶה (ישעיה נה ט), וּבְגִין דָּא שַׁתָּה, בָּתַר שֵׁת ה', וְאִינוּן י\"ה, י' מִן שִׁית ה' מִן הֶבֶל, וְאִינוּן אַבָּא וְאִימָּא, שִׁית ו' בְּרָא בְּאֶמְצָעִיתָא, וּתְלָתָא אַתְוָון אִתְכְּלִילוּ בְּיַעֲקֹב, כַּד אָתָא מֹשֶׁה בָּתַר יַעֲקֹב אִשְׁתַּלִּים בֵּיהּ ה' בַּתְרָאָה, וְשַׁרְיָא</p>"],[9500011239,"<p>עֲלֵיהּ יה\"ו, וְאִשְׁתַּלִּים בֵּיהּ יהו\"ה, וּבְגִין דָּא וּשְׁמִי יהו\"ה לֹא נוֹדַעִִתִּי לָהֶם (שמות ו ג), אֲבָל לְמֹשֶׁה וְאָמְרוּ לִ\"י מַ\"ה שְּׁמ\"וֹ מָ\"ה אוֹמַר אֲלֵיהֶם (שם ג יג), בְּגִין דְּאִשְׁתַּלִּים יהו\"ה בְּמֹשֶׁה, אָמַר אָז הוּחַל לִקְרוֹא בְּשֵׁם יהו\"ה, דִּבְקַדְמֵיתָא וּשְׁמִי יהו\"ה לֹא נוֹדַעִִתִּי לָהֶם, וּבָתַר דְּאִשְׁתַּלִּים בְּמֹשֶׁה יהו\"ה שַׁרְיָא עֲלֵיהּ יו\"ד ה\"א וא\"ו ה\"א, וְאִתְקְרֵי מַ\"ה, בְּהַהוּא זִמְנָא מַה דְּאִסְתַּלַּק בְּקַדְמֵיתָא אַהֲדַר לֵיהּ לְאַתְרֵיהּ, וְאִתְתַּקַּן כֹּלָּא.</p>\n<p>וְלָא עוֹד אֶלָּא תְּרֵין זִמְנִין אִתְּמַר בְּהַאי קְרָא מַה, הֲדָא הוּא דִכְתִיב וְאָמְרוּ לִי מַה שְּׁמוֹ מָה אוֹמַר אֲלֵיהֶם, דְּכֹלָּא חָזַר לְאַתְרֵיהּ, מַה דִּלְעִילָא מַה דִּלְתַתָּא, דְּאִינוּן מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ (משלי ל ד), וְחָזַר כֹּלָּא עַל תִּקּוּנֵיהּ, וְעִלַּת הָעִלּוֹת נָחִית עַל כֹּלָּא, בְּהַהוּא זִמְנָא דְהָדַר אֱמוּנָה (ס\"א ממונה) לְאַתְרָהּ, אָמַר מֹשֶׁה (דברים ו ד) שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, דְּהָא כֹלָּא בְיִחוּדָא חֲדָא לֵית תַּמָּן קִצּוּץ וּפִרוּד, וְאִי חָאב אֲבוֹי וְאַנָא וְעַבִידְנָא הַפְרָשָׁה הָא קַבֵּילְנָא עוֹנְשָׁא, וַחֲזַרְנָא כֹלָּא לְאַתְרֵיהּ בְּיִחוּדָא שְׁלִים בְּלָא קִצּוּץ וּפִרוּד.</p>\n<p>וְעוֹד בְּרֵאשִׁית בָּרָא אלהי\"ם, בָּרָא שִׁית, שִׁית הֵיכָלִין, אִימָּא עִלָּאָה הֵיכָלָא שְׁבִיעָאָה, תָּא חֲזִי שֶׁבַע הֵיכָלִין אִינוּן דְּבִנְיָנָא דִלְהוֹן בְּשֶׁבַע שְׁמָהָן אבגי\"תץ וכו'.</p>\n<p>הֵיכָלָא קַדְמָאָה מְרַקְּמָא בְּכָל מַה דְּאִית בְּיוֹמָא קַדְמָאָה דִבְּרֵאשִׁית, א' מִן אבגית\"ץ אִיהוּ כֶּתֶר אָמוֹן מוּפְלָא וּמְכוּסֶה, אָת ב אִיהוּ שְׁנֵי אֲלָפִים (יום) דַּהֲוָה אוֹרַיְיתָא טְמִירָא בְחֵיקוֹ, שַׁעֲשׁוּעִים יוֹם יוֹם, ג' גּוֹמֶלֶת וּמְגַדֶּלֶת, וְאִיהִי אִימָּא עִלָּאָה גוֹמֶלֶת חֶסֶד עִם סְפִירָה רְבִיעָאָה דְאִיהִי ד', ית\"ץ י' חָכְמָה, ת' תִּפְאֶרֶת, צ' צַדִּיק, וּמָאן אִיהוּ חָכְמָה י' הָכָא, דָּא חָכְמַת שְׁלֹמֹה.</p>\n<p>א' אָמוֹן מוּפְלָא, רָקִים וְצִיֵּיר צִיּוּרָא בְהֵיכָלָא דְאָדָם קַדְמָאָה דְכָל קְדוּמִים, דְּאִית אָדָם וְאִית אָדָם, אִית אָדָם דְּלֵית סְפִירָה דְלָא אִתְקְרִיאַת אָדָם, אֲבָל אָדָם קַדְמָאָה עִלָּאָה דְכֻלְּהוּ, כֶּתֶר עִִלְיוֹן, סָתִים וְטָמִיר, סָתִים דְּכָל סְתִימִין, עִלַּת הָעִלּוֹת, קַדְמוֹן לְכָל קְדוּמִים, בְּגִין הַאי אָדָם קַדְמוֹן אִתְּמַר בְּעִלַּת הָעִלּוֹת, וָאֶהְיֶה אֶצְלוֹ אָמוֹן, וּלְהַהוּא קַדְמוֹן אָמַר (בראשית א כו) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, אַנְתְּ יָהִיב כָּל צִיּוּרִין וְכָל דִּיּוֹקְנִין וְכָל תִּקּוּנִין סְתִימִין, וְכָל אֵבָרִין דְּכָל מִינִין, וְאַנְתְּ (נ\"א ואנא) יָהִיב חֵילָא בֵיהּ דְּאִשְׁתְּמוֹדַעִִנָא (דישתמודע) בֵּיהּ, דְּאִם לָא יְהִיב לֵיהּ שֵׂכֶל הָא לָא יָכִיל לְמִנְדַּע אֱמוּנָה דִילִי, וּבְדָא יְהֵא שַׁלִּיט עַל כָּל חֵילֵי שְׁמַיָּא וְאַרְעָא וְיַמָּא, הֲדָא הוּא דִכְתִיב (שם) וְיִרְדּוּ בִדְגַת הַיָּם וְגוֹמֵר.</p>\n<p>וּמַאי נִיהוּ הַאי אָדָם דְּאָמַר עֲלֵיהּ נַעֲשֶׂה אָדָם, דָּא חָכְמָה עִלָּאָה דְאִיהִי בְדִיּוֹקְנָא דְכֶתֶר, וְעוֹד נַעֲשֶׂה אָדָם דָּא עַמּוּדָא דְאֶמְצָעִיתָא, בְּצַלְמֵנוּ דָא חָכְמָה, כִּדְמוּתֵנוּ דָא אִימָּא עִלָּאָה, דִּכְמָה דְאִיהוּ אָדָם דִּבְּרִיאָה אָדָם דִּיצִירָה אָדָם דַּעֲשִׂיָּה, בְדִיּוֹקְנָא דְכֶתֶר עִִלְיוֹן חָכְמָה וּבִינָה, הָכִי אִיהוּ בְדִיּוֹקְנָא דְעַמּוּדָא דְאֶמְצָעִיתָא וְצַדִּיק וּשְׁכִינְתָּא תַּתָּאָה, דְבִסְפִירָן כֹּלָּא אִיהוּ אֲצִילוּת.</p>\n<p>וְעוֹד נַעֲשֶׂה אָדָם, עִלַּת הָעִלּוֹת לְמָאן אָמַר הַאי, אֶלָּא עִלַּת הָעִלּוֹת אָמַר לְיו\"ד ה\"א וא\"ו ה\"א דְאִיהוּ לְגוֹ מֵעֲשַׂר סְפִירָן, וּמַאי נִיהוּ עֲשַׂר סְפִירָן אל\"ף ה\"א יו\"ד ה\"א, וְהַהוּא דְאָמַר נַעֲשֶׂה אָדָם אִיהוּ יו\"ד ה\"י וא\"ו ה\"י, אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אלהי\"ם (ישעיה מד ו), תְּלַת יוּדִי\"ן מְעִידִין עֲלֵיהּ דְּלֵית לְעִילָא מִנֵּיהּ וְלֵית לְתַתָּא מִנֵּיהּ וְלַאו בְּאֶמְצָעִיתָא, לֵית אֱלוֹהַ בְּכָל צַד בַּר מִינֵיהּ, בְּהַאי שְׁמָא אִשְׁתְּמוֹדָע הוּא בְּלָא חוּשְׁבָּן.</p>\n<p>וְצִיּוּרָא דְּהַאי הֵיכָל, אִינוּן עֲשַׂר סְפִירָן דְּמִתְלַבְּשָׁן בַּעֲשָׂרָה דְבָרִים דְּאִתְבְּרִיאוּ בְיוֹמָא קַדְמָאָה, וְאִינוּן שָׁמַיִם וְאֶרֶץ, אוֹר וְחֹשֶׁךְ, תֹּהוּ וָבֹהוּ, רוּחַ וּמַיִם, מִדַּת יוֹם וּמִדַּת לַיְלָה, שָׁמַיִם אִית לְעִילָא מִן שָׁמַיִם דְּאִיהוּ שְׁמֵי הַשָּׁמַיִם הָעִִלְיוֹנִים, וְאִית אוֹר לְעִילָא לְעִילָא דְאִתְקְרִי אוֹר הַגָּנוּז לְצַדִּיקַיָּיא לְעָלְמָא דְאָתֵי, דְעִינָא לָא שַׁלִּיט עֲלֵיהּ, וְאִית חֹשֶׁךְ סָתִים דְּאִתְּמַר בֵּיהּ (תהלים יח יב) יָשֶׁת חֹשֶׁךְ סִתְרוֹ, וְאִית תֹּהוּ וָבֹהוּ לְעִילָא, דְאִתְּמַר בְּהוֹן (ישעיה לד יא) קַו תֹהוּ וְאַבְנֵי בֹהוּ.</p>"],[9500011240,"<p>וְאִית רוּחָא דְקוּדְשָׁא, דְאִתְּמַר בֵּיהּ רוּחוֹ הַקָּדוֹשׁ הַמְּרַחֶפֶת עַל אַנְפֵּי מַיָּא דְאוֹרַיְיתָא, מִדַּת יוֹם וּמִדַּת לַיְלָה, מִדַּת יוֹם שְׁכִינְתָּא עִלָּאָה, מַאי יוֹם עַמּוּדָא דְאֶמְצָעִיתָא, דְמִנֵּיהּ יוֹמִין אֲרוּכִין, הֲדָא הוּא דִכְתִיב (משלי ג ב) אֹרֶךְ יָמִים בִּימִינָהּ, הֲדָא הוּא דִכְתִיב (תהלים מב ט) יוֹמָם יְצַוְּה יהו\"ה חַסְדּוֹ, יוֹמִין זְעִירִין מִסִּטְרָא דִזְעִיר אַנְפִּין צַדִּיק, מִדַּת לַיְלָה אִימָּא תַּתָּאָה, עַד הָכָא א' מִן אב\"ג.</p>\n<p>מַאי ב' (בינה), בָּהּ אִשְׁתְּמוֹדְעִין דּוּ פַּרְצוּפִין דְּאָדָם עִלָּאָה, ג' תְּלַת דִּיּוֹקְנִין, כְּגַוְונָא דְאָדָם דִּבְּרִיאָה וְאָדָם דִּיצִירָה וְאָדָם דַּעֲשִׂיָּה, ג' אִית לָהּ רֵישָׁא וְגוּפָא וּזְנָבָא, רֵישָׁא דָא י', גּוּפָא פַּרְצוּפָא, קוֹצָא דִלְתַתָּא זָנָב, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין, אָדָם הָרִאשׁוֹן עָשָׂה לוֹ פַּרְצוּף וּלְבַסּוֹף זָנָב, זָנָב עֲלֵיהּ אִתְּמַר (בראשית כא ח) וַיִּגְדַּל הַיֶּלֶד וַיִּגָּמַל, עַד דְּיִתְעֲבִיד פַּרְצוּף.</p>\n<p>וְעוֹד אבגית\"ץ, א' אִיהִי מוֹרֶה עַל אֵ\"ל מִסְתַּתֵּר מֵעִינֵי כָּל חָי וְנֶעִִלָם מִכָּל הַיְצוּרִים כֻּלָּם, אדירירו\"ן עֲלֵיהּ אִתְּמַר קוֹמָה אַדִּיר יָרוֹן, וְאִית מְמַנָּא תְּחוֹת יְדֵיהּ דְּאִתְקְרִי אַדִּי\"ר אַדִּירִים, וּתְחוֹת מֶמְשַׁלְתֵּיהּ אתני\"ה, וְאִיהוּ נָפִיק מֵהַאי פָּסוּק (במדבר כד כא) אֵיתָ\"ן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּ\"ךָ, תַּמָּן אֵיתָ\"ן וְאִיהוּ תַנְיָ\"א, ק' קִנֶּךָ, קְנֵה חָכְמָה קְנֵה בִינָה (משלי ד ה), יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ (שם ח כב) לְעִילָא מִכֹּלָּא, קֶדֶם מִפְעָלָיו מֵאָז, מֵעוֹלָם נִסַּכְתִּי מֵרֹאשׁ מִקַּדְמֵי אָרֶץ (שם), מַאי מֵרֹאשׁ, אֶלָּא הָכִי אָמְרַת אוֹרַיְיתָא דְאִיהִי רֵאשִׁית, אֲנָא אַקְדִּימַת לְמֶהֱוֵי רֵישָׁא לְעָלַם.</p>\n<p>ב' ביהרירו\"ן (נ\"א ביהדירו\"ן) כִּי בְּיָ\"הּ יהו\"ה צוּר עוֹלָמִים (ישעיה כו ד), וְאִיהוּ ב' בָּרוּךְ, וְסִימָן בָּרוּ\"ךְ רָאשֵׁי אַתְוָון, ר' רֹאשׁ, ו' וּמָקוֹר, ך' כָּל, ב' בְּרָכוֹת, דְּדָא הוּא רֹאשׁ וּמְקוֹר לְכָל הַבְּרָכוֹת, וּבְגִין דָּא ב' אִיהִי חָכְמָה, וּמוֹרֶה עַל הַכֶּתֶר דְּאִיהוּ רֵישָׁא וּמַבּוּעָא דְכָל בִּרְכָאָן, וּבְגִין דָּא ב' תְּרֵין לְחִשְׁבְּנָא.</p>\n<p>ג' גיהדירו\"ן, וְאִיהוּ תְלִיתָאָה, וְדָא שְׁכִינְתָּא סְפִירָה תְלִיתָאָה, (ובגין דא ב' איהי חכמה, ומורה על הכתר דאיהו רישא דמבועא דכל ברכאן), וַעֲלָהּ אִתְּמַר (ישעיה מ ד) כָּל גֶּיא יִנָּשֵׂא, וְאִיהוּ גִמַּטְרִיָּאוֹת פַּרְפְּרָאוֹת לַחָכְמָה.</p>\n<p>וְעוֹד בָּרוּךְ ב' אַחֲזֵי תְּרֵין, שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, ר' רֵאשִׁית חָכְמָה, ו' אַחֲזֵי שִׁית סְפִירָן, ך' אַחֲזֵי עַל כֶּתֶר עִלָּאָה, וְדָא אִיהוּ רָזָא כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ מֵעִילָא לְתַתָּאָה, לְמִכְרַע בֵּיהּ לְהַהוּא (למנדע ביה בההוא) דְּכָל מַבּוּעִין וּמָקוֹרִין דְּבִרְכָאָן בִּידֵיהּ, דְּאִיהוּ עִלַּת הָעִלּוֹת, וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, צָרִיךְ לְזַקְפָא לֵיהּ בְּיו\"ד ה\"א וא\"ו ה\"א דְאִיהוּ מִלְּגָאו דַעֲשַׂר סְפִירָן, דְּאִיהוּ עִלָּאָה וְזָקִיף עַל כֹּלָּא, וְלֵית אֱלוֹ\"הַ לְעִיל מִנֵּיהּ, וּבְגִין דָּא ב' אַחֲזֵי עַל הַכְּרִיעָה, דְכָל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, דְּאִתְּמַר בֵּיהּ (בראשית יד כ) וּבָרוּךְ אֵ\"ל עִִלְיוֹן, ג' אַחֲזֵי עַל הַזְּקִיפָה דְאִיהוּ גָאֹה גָּאָה עַל כֹּלָּא, וְלֵית מָאן דְּיִתְגָּאֶה עֲלֵיהּ, וּבְמַאי אִתְגָּאָה עַל כֹּלָּא, בְּאָת י' מִן אבגית\"ץ, וְדָא יגבי\"ה, וְעוֹד אַשְׁכַּחְנָא בְגַוָּונָא אָחֳרָא יגבהי\"ה (נ\"א יגביהיה), וְאַתְוָון דִּילֵיהּ גַבֵּי הָיָה (נ\"א גבוה היה), עִלָּאָה דְכָל עִלָּאֵי.</p>\n<p>ת' תלמי\"ה, ת' תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ, דְּתַמָּן אִיהוּ הַהוּא דְכָל עַיְינִין וּמַחֲשַׁבְתִּין סָלְקִין לְגַבֵּיהּ, בְּגִין דָּא ת' תּוֹרָה קְדוּמָה דְכָל קְדוּמִין, תּוֹרַת חָכָם מְקוֹר חַיִּים (משלי יג יד), תּוֹרַת יהו\"ה תְּמִימָה (תהלים יט ח), וְעוֹד תלמי\"ה, תְּלָמֶיהָ רַוִּה נַחֵת גְּדוּדֶיהָ וְגוֹמֵר (שם סה יא), בְּהַאי שְׁמָא אִתְעֲבִיד יַמָּא תְּלָמִים תְּלָמִים, וְעוֹד תְּלָמֶיהָ דָא אוֹרַיְיתָא, דְתַלְיָין מִינָהּ כַּמָּה תִּלֵּי תִּלִּין דַּהֲלָכוֹת פְּסוּקוֹת דְּלֵית לוֹן חוּשְׁבָּן.</p>\n<p>צ' (צתני\"ה) צתני\"ה דָא צַדִּיק, עַמּוּד סָבִיל כֹּלָּא, וּבֵיהּ אִשְׁתְּמוֹדָע מָאן דְּאִיהוּ לְעִילָא מִכֹּלָּא, בְּגִין דְּצַדִּיק אִיהוּ כְלִיל כָּל סְפִירָן, וּבֵיהּ מִתְיַחֲדִין כֻּלְּהוּ, וְאִתְעֲבִידוּ אֲגוּדָה אַחַת, אִיהוּ לוּלָב אֲגַד דְּכֻלְּהוּ סְפִירָן, וְאָת צ' בֵּיהּ מְצוּיָירִין כָּל צִיּוּרִין דְּהֵיכָלִין דְּסָחֲרִין לְגִנְּתָא דְעִדֶן דִּלְעִילָא, בְּכַמָּה צִיּוּרִין דְּכָל עוֹבָדָא דִבְּרֵאשִׁית, דְּיָרְתִין לוֹן צַדִּיקַיָּא וּבֵיהּ</p>"],[9500011241,"<p>נְקוּדִין כָּל נְקוּדִין דְּאוֹרַיְיתָא, דְאִינוּן נְקוּדִין בְּהֵיכָלָא דְאִיהִי שְׁכִינְתָּא תַּתָּאָה, וְנַהֲרִין כֻּלְּהוּ עַל צִיּוּרִין, כְּאַבְנִי מַרְגְּלָאן דְּנַהֲרִין עַל רֵישָׁא דְכִתְרָא, וּכְגַוְונָא דְכֹכְבַיָּא נַהֲרִין בִּרְקִיעָא, וּבְגִין דְּכָל נְקוּדִין דְּכֹכְבַיָּא בֵּיהּ, אִתְּמַר (בראשית א יז) וַיִּתֵּן אֹתָם אלהי\"ם בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ, דָּא שְׁכִינְתָּא תַּתָּאָה (ס\"א דא נשמתהון דצדיקייא דמשתדלין באורייתא להוציא לאור כל תעלומה, הדא הוא דכתיב (דניאל יב ג) והמשכילים יזהירו כזהר הרקיע וגומר).</p>\n<p>הֵיכָלָא תִּנְיָנָא, מְרַקְמָא מִכַּמָּה צִיּוּרִין גְּלִידִין בְּמַיָּא, אַבְנִין מַרְגְּלָן כֻּלְּהוּ מַלְיָין מַיָּא, וְאִינוּן אַבְנֵי שַׁיִשׁ טָהוֹר, דְּהֵיכָלָא תִנְיָנָא בְּגַוִּיהּ, מִנַּיְיהוּ אִיהוּ בָּנוּי, בִּשְׁמָא דָא קְרַ\"ע שָׂטָ\"ן, וְאִיהוּ רָקִיעַ קָרַע, דְּבֵיהּ קָרַע יַמָּא, וְאַפְרִישׁ מִתַּמָּן הַשָּׂטָן דְּאִיהוּ מַיִּין מְסָאֲבִין, וּבְגִין דָּא יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם (בראשית א ו), דָּא הוּא שְׁמָא דְעָקֵר שָׂטָן מִן יַמָּא דְאוֹרַיְיתָא, וְאַפְרִישׁ לֵיהּ מִתַּמָּן, בְּגִין דְּאִיהוּ עָקַר הָאֱמוּנָה דְיִשְׂרָאֵל עִלָּאָה דְכָל עִלָּאִין, (ס\"א מצאתי, סמוך דישראל וביומא תנינא לית תמן טוב בגין דביה אתברי גיהנם, כאן חסר).</p>\n<p>זֶה סֵפֶר תּוֹלְדוֹת אָדָם (שם ה א), פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סְלִיקְנָא יָדִין לְמָאן דְּבָרָא עָלְמָא, דִיְגַלֵּי לָן רָזִין עִלָּאִין סְתִימִין גְּנִיזִין טְמִירִין, לְמֵימַר קַמֵּי שְׁכִינְתָּא, וְשִׁתִּין רִבּוֹא דַחֲיָילִין דִּילֵיהּ דְּמַלְאָכִין קַדִּישִׁין דִּלְעִילָא, וְשִׁתִּין רִבּוֹא דְמַלְאָכִין קַדִּישִׁין דִּלְתַתָּא דְלָא אֵיעוּל בְּכִסּוּפָא קֳדָמָךְ.</p>\n<p>פָּתַח וְאָמַר, זֶה סֵפֶר תּוֹלְדוֹת אָדָם, זֶה וַדַּאי כְּלִיל תְּרֵין עֲשַׂר מַזָּלוֹת דְּאָדָם דִּלְעִילָא, דְּאִתְּמַר עֲלַיְיהוּ (תהלים קכב ד) שִׁבְטֵי יָ\"הּ עִדוּת לְיִשְׂרָאֵל, זֶה וַדַּאי אִינוּן אַרְבַּע אַנְפִּין דְּאַרְיֵה, אַרְבַּע אַנְפִּין דְּשׁוֹר, אַרְבַּע אַנְפִּין דְּנֶשֶׁר, דִּבְהוֹן אִשְׁתְּמוֹדְעִין פַּרְצוּפִין דִּבְנֵי נָשָׁא, וְכֻלְּהוּ אַנְפִּין אִינוּן רְשִׁימִין בְּאַרְבַּע אַתְוָון דְּאִינוּן יהו\"ה, מַאי אָדָם יו\"ד ה\"א וא\"ו ה\"א, וַעֲלֵיהּ אִתְּמַר (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, מָאן בַּיִת דִּילֵיהּ, דָּא שְׁכִינְתָּא דְאִתְקְרִיאַת דְּמוּת אָדָם, דְּכָל דִּמְיוֹנִין וּפַרְצוּפִין דִּבְנֵי נָשָׁא בָהּ אִשְׁתְּמוֹדְעוּ, וְכָל צִיּוּרִין דְּעִלָּאִין וְתַתָּאִין, וּבְגִינָהּ אִתְּמַר (הושע יב יא) וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>(אמר המגיה, אתה בן אדם קודם שתכנס בעיון זה, להזהירך באתי שתעמד על רגליך על במותי האמונה האמתית, ותקעת יתד במקום נאמן, פן יפתוך רעיונים זדונים, ויעלו דברים על לבבך, ומלין לצד עלאה תמלל, בראותך בתיקון זה שידובר בו משערא ומצחא ואודנין ואנפין ושאר אברים גשמיים, השמר אל תפן אל און ליחס ולתאר לעלאה על כל עלאין סתימא על כל סתימין שמץ דבר מזה אפילו בהרהור, כי לעלת העלות לית מחשבה תפיסא ביה כלל, לית ביה לא דיוקן ולא דמיון ולא צורה ולא אברים גשמיים ולית ליה שם ידיע, אבל הוא ממלא כל שמהן, והוא שלימו דכלהו, ראה גם ראה מה שכתב התנא האלקי רבי שמעון בן יוחאי, כשרצה לגלות סתרי התורה באדרא, פתח ואמר ארור האיש אשר יעשה פסל ומסכה (דברים כז טו), וזה להסיר מלב כל המעיינים כל דבר עתק, פן ח\"ו יכשלו ונפלו, ועברו ממשכיות לבב, ימיקו וידברו ברע, מאחר שהיה רוצה לדבר מראש ועין ואזן ושאר אברים גשמיים, היה ירא שמא יטעו ליחס ולתאר לבורא יתברך גוף ותמונה, ומשה אמר כי לא ראיתם כל תמונה (דברים ד טו), וישעיה אמר (ישעיה מ יח) ואל מי תדמיון א\"ל ומה דמות תערכו לו, ואל מי תדמיוני ואשוה יאמר קדוש (שם כה), ודומיהם, שכלם יעידון יגידון שאין דמיון בינו יתברך ובינינו מצד</p>"],[9500011242,"<p>העצם והתבנית, אלא שהאברים שבנו הם עשויים כסימנים לדברים עליונים סתומים וחתומים שאין כח השכלי שבאדם יכול להשיגם, ואין שיח ואין שיג לו להבינם, וקצר מצע דעתו לרדת לעמקם, ואיני רשאי להכניס ראשי בין ההרים הרמים הלא הם בעלי הקבלה אשר העמיקו הרחיבו דבריהם על הדרוש הזה, רק מעי רתחו ולא דמו, מיראתי פן עובדי פשתים שריקות וארגים חורי קורי עכביש יארגו, בדעות כוזבות יאריכו למעניתם, לך נא ראה מה שכתב על זה ר' יוסף בן גיקיטיליא בהקדמת שערי אורה, ובמה שכתב בעל החנוך בהקדמתו לפירוש התורה, והאלקי ר' מנחם מריקנאטי ז\"ל בפרשת ויחי בפסוק בן פורת יוסף, ובמה שכתב ר' יהודה חייט בפירוש מערכת האלקות (ד, לד), וזה לשונו, סוף דבר כל מקום שתראה שידברו בענין הספירות, דברים שאין ראוי לאמרם בבורא יתברך, כגון שעור וקומה והדומים להם, הכל נאמר על הספירות, וכשתראה שידברו על דרך שבח והודאה הכל נאמר על הבורא שבתוכן, וכן בחוצה להן, כי אין דבר שיגבילהו, ועל כן אין לומר בבורא יתברך לא ימין ולא שמאל ולא פנים ואחור ומעלה ומטה כו' עיין שם. עוד כתב (בדף לה ע\"ב) כי אף על פי ששעור הקומה מהפרסאות הוא במדות ולא בבורא, אפילו הכי אין לחשוב חלילה שהפרסאות הללו הם שעור כמותי, אלא הם מלשון (דניאל ה כח) פרס פריסת מלכותך, וכל הפרסאות הללו שבשעור קומה הם אותיות, שכל אחת נקראת פרסה, על כי נחתכו מהעיסה, כאבנים הנחתכים מההר, ואמר שרבוי הפרסאות שהזכיר בכאן, רומז לניצוצות המתפוצצות מהכאת הפטיש בקורנס, והם השמות הנעשים מחבור האותיות והצרופים הנעשים מהאלפא ביתות דספר יצירה, שעמהם נבראו הדברים וכו', ואם תדקדק היטב בדברי רבי שמעון בענין זה, תשכיל ותדע כי דברי רבי יהודה חייט ז\"ל ואשר במסלתו ילכון, הם נכוחים למבין וישרים למוצאי דעת, ולא יעבטון ארחותיהם.)</p>\n<p>פָּתַח וְאָמַר, וְאַתָּה תֶחזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אלהי\"ם אַנְשֵׁי אֱמֶת שֹׂנְאֵי בָצַע (שמות יה כא), אַנְשֵׁי חַיִל מִסִּטְרָא דְחֶסֶד דְּתַמָּן י', וּבְגִינֵיהּ אִתְּמַר הָרוֹצֶה לְהַחְכִּים יַדְרִים, יִרְאֵי אלהי\"ם מִסִּטְרָא דִגְבוּרָה דְתַמָּן ה', וּבָהּ אִתְּמַר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, אַנְשֵׁי אֱמֶת מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא דְתַמָּן ו' וְתַמָּן אֱמֶת, שׂוֹנְאֵי בָצַע מִסִּטְרָא דְמַלְכוּת דְּתַמָּן ה', הָא הָכָא אַרְבַּע תִּקּוּנִין דְּאִינוּן פַּרְצוּפִין דִּבְנֵי נָשָׁא, אִלֵּין אִינוּן מַרְאֶה (ס\"א מראין).</p>\n<p>וְאִית אַרְבַּע דְּמִתְלַבְּשִׁין בְּהוֹן דְּאִינוּן דִּמְיוֹן וְאִינוּן אדנ\"י, וַעֲלַיְיהוּ אִתְּמַר (שם) וְשַׂמְתָּ עֲלֵיהֶם שָׂרֵי אֲלָפִים מִסִּטְרָא דְא', שָׂרֵי מֵאוֹת מִסִּטְרָא דְאָת ד', דְּאִיהוּ אַרְבַּע מֵאוֹת דְּאִשְׁתַּעֲבִידוּ יִשְׂרָאֵל בְּמִצְרַיִם בְּגִין דְּבָהּ חָאבוּ, הָא דְּאִתְּמַר בֵּיהּ (בראשית כג טו) אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף, וְשָׂרֵי חֲמִשִּׁים מִסִּטְרָא דְאָת נ', וְשָׂרֵי עֲשָׂרוֹת מִסִּטְרָא דְאָת י'.</p>\n<p>אִשְׁתָּאֲרוּ עִִשֶׂר תִּקּוּנִין, עֲלַיְיהוּ אִתְּמַר וְאַתָּה תֶחזֶה מִכָּל הָעָם, בְּשַׂעֲרָא בְּגַוָּונִין דִּילֵיהּ בַּאֲרִיכוּ דִילֵיהּ בַּקְּמִיטוּ דִילֵיהּ, בְּמִצְחָא בַּקְּמִיטוּ דְמִצְחָא בַּאֲרִיכוּ דְמִצְחָא בְּפוּתְיָא דְמִצְחָא בְּשִׁרְטוּטִין דְּמִצְחָא, בְּאוּדְנִין (בס\"א באודנין שערא דנחית עלייהו או תחותייהו), בְּאִלֵּין אִדְרִין דְּאוּדְנִין בְּשַׂעֲרָא דִתְּחוֹת אוּדְנִין, בְּאַנְפִּין בְּדִיּוֹקְנִין דְּאַנְפִּין בְּפַרְצוּפָא דְאַנְפִּין, בְּעַיְינִין בְּגַוָּונִין דְּעַיְינִין בַּקְּרִיצִין דְּעַל עַיְינִין, בְּחוֹטָמָא בַּאֲרִיכוּ דִילָהּ בְּפוּתְיָא דִילָהּ בִּקְמִיטוּ דִילָהּ, בְּפִימָא בִּפְתִיחוּ דִילָהּ בִּזְעִירוּ דִילָהּ, בְּצַוָּאר בַּאֲרִיכוּ דִילֵיהּ</p>"],[9500011243,"<p>בִּקְמִיטוּ דִילֵיהּ, בִּידַיִן בְּשִׁרְטוּטִין דִּידַיִן בִּפְתִיחוּ דִלְהוֹן בִּסְתִימוּ דִלְהוֹן, בְּגוּפָא בְּקוֹמָה דִילֵיהּ בַּאֲרִיכוּ דִילֵיהּ בִּקְמִיטוּ דִילֵיהּ.</p>\n<p>בְּשַׂעֲרָא בְּגַוָּונִין דְּשַׂעֲרָא, שַׂעֲרָא חִוְורָא אִיהוּ מֵאִלֵּין אַנְשֵׁי חַיִל, דְּאִתְּמַר בֵּיהּ (דניאל ז ט) וְעַתִּיק יוֹמִין יְתִיב לְבוּשֵׁיהּ כִּתְלָג חִוָּור וּשְׂעַר רֵאשֵׁהּ כַּעֲמַר נְקֵא, שַׂעֲרָא סוּמְקָא מֵאִלֵּין דְּאִתְקְרִיאוּ יִרְאֵי אלהי\"ם, שַׂעֲרָא יְרוֹקָא מֵאִלֵּין דְּאִתְקְרִיאוּ אַנְשֵׁי אֱמֶת, וְאִינוּן מִסִּטְרָא דְיַעֲקֹב דְּאִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב, וּתְלַת גַּוָּונִין, עֲלַיְיהוּ אִתְּמַר תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם, תְּלִיתָאָה פַּחַד יִצְחָק, גַּוָּון אוּכְמָא מִסִּטְרָא דְהַהוּא דְאִתְּמַר בָּהּ (שיר א ה) שְׁחוֹרָה אֲנִי וְנָאוָה, מִסִּטְרָא דְאִלֵּין דְּאִתְקְרִיאוּ שׂוֹנְאֵי בָצַע, וְאִיהִי שַׂעֲרָא דִילָהּ אוּכְמָא, וְאִיהִי שִׁעוּרָא דְאַתְוָון דְּאוֹרַיְיתָא, כָּל נִימָא וְנִימָא דִילֵיהּ, דְּאִתְּמַר עֲלַיְיהוּ (שם ה יא) קֶּוֵצּוֹתָיו תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב, וְכָל נִימָא אִית לֵיהּ מַבּוּעָא דְאִיהִי י', וְנִימָא שִׁעוּרָא דְאָת ו'.</p>\n<p>שַׂעֲרָא קְמִיטָא בְרָזָא דְה' זְעִירָא דְנָטְלַת מֵאָת י', שַׂעֲרָא אֲרִיכָא מִסִּטְרָא דְה' עִלָּאָה דְנָטְלָא מֵאָת ו', עִִשֶׂר תִּקּוּנִין אִלֵּין, כָּל תִּקּוּנָא וְתִקּוּנָא אִית לֵיהּ (נ\"א ביה) אַרְבַּע שִׁעוּרִין דְּסָלְקִין לְעִִשֶׂר, כְּגַוְונָא דִרְשׁוּת הַיָּחִיד דְּרָחְבּוֹ אַרְבָּעָה וְגָבְהוֹ עֲשָׂרָה, אַרְבָּעָה יהו\"ה עֲשָׂרָה יו\"ד ה\"א וא\"ו ה\"א, לֵית נִימָא דְשַׂעֲרָא דְלָא אַחֲזֵי עָלְמָא עִלָּאָה סְתִימָא, דַּעֲלַיְיהוּ אִתְּמַר (שם ו ח) וַעֲלָמוֹת אֵין מִסְפָּר, כָּל אִלֵּין עָלְמִין תַּלְיָין מִכִּתְרָא דְרֵישָׁא, כְגַוְונָא דְאַבְנִין וּמַרְגְּלָן דְּנַהֲרִין בְּכִתְרָא דְסֵפֶר תּוֹרָה אוֹ בַּעֲטָרָה דְמַלְכָּא, וְהָכִי אִינוּן נַהֲרִין כְּכֹכְבַיָּא בִרְקִיעָא וּבֵיהּ קְבוּעִין.</p>\n<p>וְהָכִי תַלְיָין צְבָא הַשָּׁמַיִם מִימִינָא וּמִשְּׂמָאלָא דְקוּדְשָׁא בְּרִיךְ הוּא, כְּגַוְונָא דְשַׂעֲרָא דְתַלְיָין מֵעַל אוּדְנִין מִימִינָא וּמִשְּׂמָאלָא, הֲדָא הוּא דִכְתִיב (מלכים א כב יט) וְכָל צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו מִימִינוֹ וּמִשְּׂמֹאלוֹ, וּבְגִין דָּא צָרִיךְ לְבַעֲרָא שַׂעֲרָא מֵעַל (ס\"א מגו) אוּדְנִין, דְּלָא יְהוֹן סְתִימִין תַּרְעִין דִּשְׁמִיעָה דִצְלוֹתָא, דִּבְהוֹן שָׁמַע צְלוֹתִין הַהוּא דְאִתְּמַר בֵּיהּ (תהלים סה ג) שׁוֹמֵעַ תְּפִלָּה עָדֶיךָ כָּל בָּשָׂר יָבֹאוּ.</p>\n<p>דְּאַרְבַּע תִּקּוּנִין אִינוּן, רְאִיָּה שְׁמִיעָה רֵיחָא דִּבּוּר, רְאִיָּה אִיהִי לַמִּזְרָח (נ\"א לדרום), וַעֲלֵיהּ אִתְּמַר (שמות יח כא) וְאַתָּה תֶחזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל, וְכַמָּה נְטוּרֵי תַרְעִין תַּמָּן דְּאִתְקְרִיאוּ עִינֵי יהו\"ה, וַעֲלַיְיהוּ אִתְּמַר (דניאל ט יח) פְּקַח עִינֶיךָ וּרְאֵה שׁוֹמְמֹתֵינוּ, שְׁמִיעָה יִרְאֵי אלהי\"ם, וַעֲלֵיהּ אִתְּמַר (שם) הַטֵּה יהו\"ה אָזְנְךָ וּשְׁמָע, וְתַמָּן דְּחִילוּ וּפַחַד יִצְחָק, הֲדָא הוּא דִכְתִיב (חבקוק ג ב) יהו\"ה שָׁמַעִִתִּי שִׁמְעֲךָ יָרֵאתִי, וּמָאן דִּי מִשְׁתַּמַּע תַּמָּן קָלֵיהּ בֵּין בְּאוֹרַיְיתָא בֵּין בִּצְלוֹתָא בֵּין בִּצְעָקָה בְּלָא דְחִילוּ, מִיָּד (במדבר יא א) וַיִּשְׁמַע יהו\"ה וַיִּחַר אַפּוֹ וַתִּבְעַר בָּם אֵשׁ יהו\"ה, וְכַמָּה נְטוּרֵי תַרְעִין תַּמָּן דְּאִתְקְרִיאוּ אָזְנֵי יהו\"ה.</p>\n<p>רֵיחָא תַּמָּן אַנְשֵׁי אֱמֶת, וְתַמָּן סָלְקִין כָּל רֵיחִין וּקְטוּרִין וַעֲשַׁנִּין דְּקָרְבָּנִין, וּצְלוֹתִין דְּאִתְחֲשִׁיבוּ כְקָרְבָּנִין, וְאִם לָא סָלִיק לוֹן בַּר נַשׁ בִּדְחִילוּ וּרְחִימוּ, מַה כְּתִיב בֵּיהּ (דברים כט יט) כִּי אָז יֶעִִשַּׁן אַף יהו\"ה וְקִנְאָתוֹ בָּאִישׁ הַהוּא, דִּבּוּר לָקֳבֵל שׂוֹנְאֵי בָצַע, תַּמָּן סָלְקִין קָלִין וְדִבּוּרִין דְּאוֹרַיְיתָא וּצְלוֹתָא, אִלֵּין דְּאִתְּמַר עֲלַיְיהוּ (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר, לָא אִית תִּקּוּנָא מֵאִלֵּין, אַרְבַּע דְּלֵית תַּמָּן יהו\"ה, וְאִיהוּ י אִסְתַּכַּל, ה וְשָׁמַע, ו וּמֵרִיחַ, ה וּמְמַלֵּל, בְּאִלֵּין אַרְבַּע תִּקּוּנִין.</p>\n<p>אַרְיֵה דָא רְאִיָּה, וְאִתְּמַר בֵּיהּ (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם, בְּכָל אֲתַר אַרְבַּעִִתָּם דָּא יהו\"ה, אַרְבַּע אַתְוָון דִּילֵיהּ דְּשָׁלְטִין עַל כֹּלָּא, וַהֲפוֹךְ אַרְיֵה וְתִשְׁכַּח לֵיהּ רְאִיָּה, וְאִיהוּ לִימִינָא דְחֶסֶד, דְּאִיהוּ יוֹמָא קַדְמָאָה, דְתַמָּן א' (נ\"א י') אוֹר, רְאוּבֵן דְּאִיהוּ לִימִינָא עַל שְׁמֵיהּ אִתְקְרֵי אוֹר בֵּן, שְׁמִיעָה לִשְׂמָאלָא, וַעֲלֵיהּ אִתְּמַר (שם) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל, נֶשֶׁר רֵיחָא בְאֶמְצָעִיתָא, עֲלֵיהּ אִתְּמַר (משלי ל ד) מִי אָסַף רוּחַ בְּחָפְנָיו, דְּאִינוּן תְּרֵין נוּקְבִין דְּחוֹטָמָא, פִּימָא דִבּוּרָא, דָא אָדָם כְּלִיל אַרְבַּע אַתְוָון וּכְלִיל עִִשֶׂר אַתְוָון, וְדָא שְׁכִינְתָּא, בְּאִלֵּין</p>"],[9500011244,"<p>אַרְבַּע תִּקּוּנִין אָמַר לְמֹשֶׁה וְאַתָּה תֶחזֶה מִכָּל הָעָם וְגוֹמֵר וְצָרִיךְ לְאַחְזָרָא עֲלַיְיהוּ.</p>\n<p>וְאַתָּה תֶחֱזֶה בְּשַׂעֲרָא, עֲלֵיהּ אִתְּמַר (שיר ה יא) רֹאשׁוֹ כֶּתֶם פָּז דָּא כֶּתֶר עִלָּאָה, וּמִלְּגָאו מוֹחָא, דְּמִנֵּיהּ נָפְקִין מַבּוּעִין לְכָל סִטְרָא, לְאַשְׁקָאָה לְכָל נִימָא וְנִימָא דְאִיהִי עָלְמָא סְתִימָאָה, וְכָל מַבּוּעָא אִתְעֲבִיד נִיצוֹץ, וְכָל נִימָא אִתְעֲבִיד שַׁרְבִיט, מוֹחָא סְתִימָא אִתְקְרֵי אֵין סוֹף, דְּאִתְפַּלַּג לִתְלַת מוֹחִין דְּאִינוּן י' י' י', דְּאִתְרְמִיזוּ בְּהַאי שְׁמָא (יו\"ד ה\"א וא\"ו ה\"א נ\"א יו\"ד ה\"י וא\"ו ה\"י). (קם סבא דסבין עתיקא דעתיקין, ואמר בוצינא קדישא, ודאי שמא דאתרמיזו תלת יודי\"ן דא) יו\"ד ה\"י וא\"ו ה\"י וְדָא אִיהוּ מִלְּגָאו, אֲבָל שְׁמָא דְאִיהוּ יו\"ד ה\"א וא\"ו ה\"א, אִיהוּ כְּלִיל תְּלַת אַלְפִין א' א' א', אִינוּן תְּלַת אַוִּירִין, דְּמִתְלַבְּשִׁין בְּהוֹן תְּלַת מוֹחִין י' י' י', שְׁמָא חַד אִיהוּ גוּפָא, וּשְׁמָא תִנְיָנָא מוֹחָא, דָּא מִלְּגָאו, וְדָא מִלְּבָר.</p>\n<p>תְּלַת וָוִי\"ן אִית בְּהַאי שְׁמָא, דְאִנּוּן שַׁרְבִיטִין, שֵׂעָר אִתְקְרֵי עַל שֵׁם שִׁעוּר קוֹמָתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל נִימָא וְנִימָא אִתְקְרֵי נִשְׁמָתָא, וְאִית נִימִין דְּאִתְקְרִיאוּ מַלְאָכִין, וְכָל נִיצוֹץ אִתְקְרֵי אוֹפָן וְאִתְקְרֵי גַלְגַּל, וְאִית מִנַּיְיהוּ דְאִינוּן נִימִין מֵאֶשָּׁא חִוְורָא כֻלְּהוּ רַחֲמֵי, וְאִית מִנַּיְיהוּ דְאִינוּן נִימִין דְּאִינוּן מֵאֶשָּׁא סוּמְקָא וְכֻלְּהוּ דִין, וְאִית נִימִין כֻּלְּהוּ יְרוֹקִין מֵאֶשָּׁא יְרוֹקָא, וְאִית נִימִין כֻּלְּהוּ מֵאֶשָּׁא אוּכְמָא, אִלֵּין אִתְקְרִיאוּ שֵׂעָר דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>כָּל נִיצוֹץ שִׁעוּר מַהֲלַךְ דִּילֵיהּ עִִשֶׂר אַלְפִין, וְכָל נִימָא אִיהִי שִׁעוּרָא דְאֶצְבָּעָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְכָל אֶצְבַּע אִיהוּ פַּרְסָה זְעִירָא, וְכָל פַּרְסָה אִית בָּהּ תְּלַת מִיל, לָקֳבֵל תְּלַת פִּרְקִין דְּאֶצְבָּעָא, וְכָל מִיל אִיהוּ עֲשֶׂרֶת אֲלָפִים, אֲבָל מִיל דְּפַרְסָה עִלָּאָה אִיהוּ עֲשֶׂרֶת אֲלָפִים רִבּוֹא, וְהָכִי דְרוֹעָא תִשְׁכַּח בָּהּ תְּלַת פִּרְקִין, וְכָל פֶּרֶק אִיהוּ י', וְכָל אַמָּה אִיהוּ ו', אֲבָל אֶצְבַּע וְאַמָּה דָּא שִׁעוּרֵיהּ זְעִיר מִסִּטְרָא דִזְעִיר אַנְפִּין, וְדָא שִׁעוּרֵיהּ רַב מִסִּטְרָא דַאֲרִיךְ אַנְפִּין.</p>\n<p>וּבְכָל אֵבֶר וְאֵבֶר אִיהוּ יהו\"ה, וְאִיהוּ שִׁעוּרָא דְכָל אֵבֶר וְאֵבֶר, בְּגָבְהָא בְאָרְכָּא עִילָא וְתַתָּא, וּלְאַרְבַּע סִטְרִין, וְאִיהוּ בֵּין כָּל אֵבֶר וְאֵבֶר, לֵית אֲתַר פָּנוּי מִנֵּיהּ, כְּנִשְׁמָתָא דְאִשְׁתַּכְּחַת בְּכָל אֵבֶר וְאֵבֶר דְּגוּפָא, וְאִית אֵבֶר עִלָּאָה דְאִתְקְרֵי יהו\"ה עַל שְׁמֵיהּ, דְּשָׁלְטָנוּתֵיהּ בַּאֲתַר יְדִיעָא, הֲדָא הוּא דִכְתִיב (זכריה יד ט) וְהָיָה יהו\"ה לְמֶלֶךְ עַל כָּל הָאָרֶץ.</p>\n<p>וְאִית תְּרֵין אֵבָרִין עִלָּאִין מִנֵּיהּ, דְּאִתְקְרִיאוּ יהו\"ה אלהי\"ם דְּשָׁלְטָנוּתְהוֹן בִּשְׁמַיָּא וּבְאַרְעָא, הֲדָא הוּא דִכְתִיב (דברים ד לה) כִּי יהו\"ה הוּא הָאלהי\"ם בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת אֵין עוֹד, וְאִית אֵבֶר דְּאִתְקְרֵי אלהי\"ם, וְשָׁלְטָנוּתֵיהּ בְּכָל אַרְעָא, הֲדָא הוּא דִכְתִיב (תהלים מ\"ז) מֶלֶךְ כָּל הָאָרֶץ אלהי\"ם, וְאִית אָחֳרָא דְשָׁלְטָנוּתֵיהּ אִיהוּ בִתְרֵין אֵבָרִין בְּמוֹחָא וּבְלִבָּא, וַעֲלֵיהּ אִתְּמַר (דברים ד') כִּי יהו\"ה הוּא הָאלהי\"ם אֵין עוֹד מִלְּבַדּוֹ, וְאַף עַל גַּב דְּהַאי קְרָא עַל קוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר דְּאֵין עוֹד מִלְּבַדּוֹ, עִם כָּל דָּא הָכָא רָזָא דְּדִיּוֹקְנָא עִלָּאָה דִילֵיהּ, לְאַחֲזָאָה בְּכָל אֵבֶר וְאֵבֶר דְּגוּפֵיהּ שׁוֹלְטָנוּתֵיהּ, לְאִשְׁתְּמוֹדְעָא לְבַר נַשׁ אֵיךְ אִתְנַהִיג עָלְמָא, וְיִנְדַּע לְמִקְרֵי לֵיהּ בְּכָל אֵבֶר כִּדְקָא יָאוּת לֵיהּ, וְאֵיךְ אִשְׁתַּנִּי שְׁמֵיהּ לְפוּם הַהוּא אֵבֶר.</p>\n<p>וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ יהו\"ה רַחֲמֵי, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ אלהי\"ם, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ אהי\"ה, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ צבאו\"ת, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ א\"ל, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ שד\"י, וְאִית אֵבֶר דְּאִתְקְרֵי בֵּיהּ אדנ\"י, יהו\"ה מְמַנָּא עַל קָלָא, הֲדָא הוּא דִכְתִיב (תהלים כט ד) קוֹל יהו\"ה בַּכֹּחַ, אהי\"ה עַל הֲוַיָּה וְהֶבֶל דְּלִבָּא, הַהוּא דְרָכִיב עַל קָלָא דְיהו\"ה אִיהוּ עִלַּת עַל כָּל הָעִלּוֹת, סָתִים וְטָמִיר וְלָא אִתְגַּלְיָא, וְאִיהוּ רָכִיב וְשַׁלִּיט עַל כֹּלָּא, אהי\"ה אַחֲזֵי עַל עִלַּת הָעִלּוֹת דְּאִיהוּ הָיָה</p>"],[9500011245,"<p>הוְֹה וְיִהְיֶה, וְאִיהוּ הֲבַל דְּסָלִיק עַד אֵין סוֹף, וּבֵיהּ רָכִיב עִלַּת עַל כָּל הָעִלּוֹת. אֵ\"ל אַחֲזֵי עַל אֱלָהוּ\"ת דְּעִלַּת עַל כָּל הָעִלּוֹת, וַעֲלֵיהּ אָמַר אִיוֹב (איוב ה ח) אֲנִי אֶדְרוֹשׁ אֶל אֵ\"ל, אֶל אלה\"י הָאלהי\"ם, וְכַד רָכִיב עַל אֵ\"ל אִשְׁתְּמוֹדְעִין לֵיהּ כָּל אלהי\"ם, וּמִזְדַּעִִזְעִין מִנֵּיהּ, וְכָל מַלְאָכַיָּא דְאִתְקְרִיאוּ בְּהַאי אֵ\"ל כְּגוֹן מִיכָאֵ\"ל גַּבְרִיאֵ\"ל, כֻּלְּהוּ מִזְדַּעִִזְעִין מֵהַאי אֵ\"ל דְּאִיהוּ אלה\"י הָאלהי\"ם, וּמָאן דְּקָרָא לוֹן בֵּיהּ, מִיָּד עוֹנִין לֵיהּ בְּכָל שַׁעִִתָּא, וְהָכִי כָּל מַלְאָכַיָּא דְאִתְקְרִיאוּ קָלִין בִּשְׁמָא דְיהו\"ה, כָּל מָאן דְּקָרָא לוֹן בְּיהו\"ה בְּעִלַּת עַל כָּל הָעִלּוֹת מִיָּד עוֹנִין לֵיהּ בְּקָלֵיהּ, דְּעִלַּת עַל כָּל הָעִלּוֹת אִיהוּ חַד בְּכָל שְׁמָהָן וְלָא אִשְׁתַּנִּי בְּכֻלְּהוּ, דְּשִׁנּוּיִין בִּשְׁמָהָן אִינוּן וְלַאו בֵּיהּ, דְּאִיהוּ בְּכֻלְּהוּ כְּנִשְׁמָתָא בְּכָל אֵבֶר וְאֵבֶר, אִית אֵבֶר דְּשָׁמַע בֵּיהּ כְּגוֹן אוּדְנִין, וְאִית אֵבֶר דְּמִסְתַּכֵּל מִנֵּיהּ (נ\"א ביה) עַל עָלְמָא, וְאִית אֵבֶר דְּאָרַח בֵּיהּ כָּל רֵיחִין וּבוּסְמִין דִּצְלוֹתִין, וְרֵיחִין טָבִין דַּהֲבָלִים דְּנָפְקִין מֵאוֹרַיְיתָא מִפּוּמָא דִבְנֵי נָשָׁא, וְדָא רֵיחָא דְחוֹטָמָא, וְאִית אֵבֶר דְּמַלֵּיל בֵּיהּ, וּבְאִלֵּין אֵבָרִין אִית שִׁנּוּיָיא, אֲבָל בֵּיהּ לֵית שִׁנּוּיָיא, וְאִית אֵבֶר דִּמְמַנָּא עַל דִּבּוּרָא וְדָא אדנ\"י, וְאֵבֶר דִּמְמַנָּא עַל מַחֲשָׁבָה, וְאֵבָרִין אִלֵּין כֻּלְּהוּ בִסְפִירָן.</p>\n<p>רֵישָׁא כֶתֶר עִִלְיוֹן, מוֹחָא חָכְמָה, בִּינָה לִבָּא וּבָהּ לֵב מֵבִין, תְּרֵין דְּרוֹעִין חֶסֶד גְּבוּרָה, גּוּפָא עַמּוּדָא דְאֶמְצָעִיתָא, תְּרֵין שׁוֹקִין נֶצַח וָהוֹד, יְסוֹד אָמָה, שְׁכִינְתָּא אוֹת דִּילֵיהּ. כֶּתֶר אִתְקְרֵי אֵ\"ל עִִלְיוֹן, קוֹנֵה הַכֹּל, (חכמה ובינה) אלהינ\"ו בִּינָה, וִאלה\"י אֲבוֹתֵינוּ חָכְמָה, וְאִיהוּ אלה\"י אַבְרָהָם אלה\"י יִצְחָק וִאלה\"י יַעֲקֹב, הָאֵ\"ל הַגָּדוֹל מִסִּטְרָא דִגְדוּלָה, וְהַגִּבּוֹר מִסִּטְרָא דִגְבוּרָה, וְהַנּוֹרָא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ קָא נָחִית, וְאָמַר רַבִּי בּוֹצִינָא קַדִּישָׁא, שְׁמַעִִנָא לְעִילָא תִּקּוּנָא דִילָךְ בִּשְׁמָהָן דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבִצְלוֹתָא דִילֵיהּ, חֲזוֹר בָּךְ, דְּאַתְּ צָרִיךְ לְתַקָּנָא שְׁמָהָן דְּקוּדְשָׁא בְּרִיךְ הוּא כִּדְקָא יָאוּת, דְּהָא כֻּלְּהוּ אָזְלִין בִּתְלַת תְּלַת, מִסִּטְרָא דְרַחֲמֵי אִתְקְרִיאוּ יהו\"ה יהו\"ה יהו\"ה תְּלַת אֲבָהָן, וְאִינוּן אֵשׁ דְּלָא אִיהוּ שׂוֹרֵף, וְאִתְקְרִיאוּ בִּתְלַת שְׁמָהָן אהי\"ה אהי\"ה אהי\"ה, וְהַאי אִיהוּ אֵשׁ דְּאִיהוּ שׂוֹרֵף וְלָא אָכִיל, וְאִית שְׁמָהָן דְּאִתְקְרִיאוּ אדנ\"י אדנ\"י אדנ\"י, וְדָא אֵשׁ דְּאִיהוּ שׂוֹרֵף וְאָכִיל וְשֵׁצֵי כֹּלָּא, הֲדָא הוּא דִכְתִיב (ויקרא ט כד) וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעוֹלָה וְאֶת הַחֲלָבִים.</p>\n<p>א' אִיהוּ כֶּתֶר עַל כֻּלְּהוּ שְׁמָהָן, וְאִיהוּ אִתְקְרֵי א\"ל, אהי\"ה, אדנ\"י, אלהי\"ם, אלה\"י, אֱלוֹ\"הַּ, אלהינ\"ו אי\"ה, או\"ה, (ורזא דמלה א\"ל אלהי\"ם יהו\"ה דבר ויקרא ארץ) (תהלים נ א). י' בֵּיהּ אִתְקְרֵי י\"ה, יה\"ו, יהו\"ה, יה\"י, יהי\"ה, כֻּלְּהוּ שְׁמָהָן דְּפָתְחִין בַּהֲוַיּוֹ\"ת בְּי', עִקָּרָא דִלְהוֹן בְּחָכְמָה, וְכֻלְּהוּ שְׁמָהָן דְּפָתְחִין בְּא', עִקָּרָא דִלְהוֹן אִימָּא עִלָּאָה, וּכְמָה דְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ כְּלִיל מִימִינָא וּמִשְּׂמָאלָא, הָכִי כֶּתֶר עִלָּאָה כְּלִיל תְּרֵין שְׁמָהָן אִלֵּין דְּאַבָּא וְאִימָּא, וְאִיהוּ כֶּתֶר עַל רֵישַׁיְיהוּ, וְאַשְׁכַּחְנָא תִּקּוּנָא כְּגַוְונָא דָא, אהי\"ה כֶּתֶר עִלָּאָה, יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, אדנ\"י שְׁכִינְתָּא תַּתָּאָה.</p>\n<p>וּמִסִּטְרָא דְכֶתֶר אִתְקְרִיאוּ תְּלַת סְפִירָן אֶהְיֶ\"ה אֲשֶׁר אֶהְיֶ\"ה, חֶסֶד אֵ\"ל, גְּבוּרָה אלהי\"ם, עַמּוּדָא דְאֶמְצָעִיתָא יהו\"ה, וְרָזָא דְמִלָּה אֵ\"ל אלהי\"ם יהו\"ה דִּבֶּר וַיִּקְרָא אָרֶץ, נֶצַח וְהוֹד צְבָאוֹ\"ת, צַדִּיק שד\"י, מַלְכוּת אדנ\"י.</p>\n<p>וּבִצְלוֹתָא בָּרוּךְ אַתָּה יהו\"ה, כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, וְדָא צַדִּיק חַי עָלְמִין, וַעֲלֵיהּ אִתְּמַר (מכלים א ב מה) וְהַמֶּלֶךְ שְׁלֹמֹה בָּרוּךְ, אַתָּה אָת ה' זְעִירָא, בָהּ צָרִיךְ לְנַחְתָא בִרְכָאָן, וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם דָּא יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, אלהינ\"ו אִימָּא עִלָּאָה, וִאלה\"י אֲבוֹתֵינוּ אַבָּא, הָאֵ\"ל הַגָּדוֹל חֶסֶד, הַגִּבּוֹר גְּבוּרָה, וְהַנּוֹרָא עַמּוּדָא דְאֶמְצָעִיתָא, דְבֵיהּ אִתְכְּלִילָן מִתַּתָּא לְעִילָא וּמֵעִילָא לְתַתָּא, כָּל סְפִירָאן בְּעַמּוּדָא דְאֶמְצָעִיתָא, וּבְגִין</p>"],[9500011246,"<p>דָּא צָרִיךְ לְאַכְלָלָא בֵּיהּ תַּתָּאִין בְּהַכְרָעָה, וּלְבָתַר עִלָּאִין בִּזְקִיפָה. אֵ\"ל עִִלְיוֹן, גּוֹמֵל חֲסָדִים טוֹבִים קוֹנֵה הַכֹּל, וְזוֹכֵר חַסְדֵּי אָבוֹת, דָּא כֶּתֶר עִִלְיוֹן עַל כֻּלְּהוּ, וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם דַּאֲבָהָן, אִלֵּין נֶצַח וָהוֹד, לְמַעַן שְׁמוֹ בְּאַהֲבָה דָא שְׁכִינְתָּא תַּתָּאָה, וְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ כְּלִיל תְּלַת בִּרְכָאָן קַדְמָאִין, דְּאִינוּן אֲבָהָן וּגְבוּרוֹת וּקְדוּשַׁת הַשֵּׁם, וְאִיהוּ כְּלִיל תְּלַת בַּתְרָאִין בַּעֲבוֹדָה, וְאִיהוּ כְּלִיל אֶמְצָעִיּוֹת, לְקַיְימָא בֵיהּ אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אלהי\"ם (ישעיה מד ו), זַכָּאָה אִיהוּ מָאן דְּיָדַע לְצַלָּאָה לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל תִּקּוּנִין דִּילֵיהּ כִּדְקָא יָאוּת, וּלְמִשְׁאַל מִנֵּיהּ בְּכָל דַּרְגָּא וְדַרְגָּא כִּדְקָא יָאוּת.</p>\n<p>חַכִּימִין כֻּלְּהוּ אִינוּן רְשִׁימִין דִּיּוֹקְנֵיהוֹן בַּחָכְמָה, וּנְבוֹנִין רְשִׁימִין דִּיּוֹקְנֵיהוֹן בְּבִינָה, וּמָארֵי גְמִילוּת חֲסָדִים דִּיּוֹקְנֵיהוֹן רְשִׁימִין בְּחֶסֶד, וְגִבָּרִין בְּיִצְרֵיהוֹן כֻּלְּהוּ רְשִׁימִין בִּגְבוּרָה, וּמָארֵי תּוֹרָה כֻּלְּהוּ רְשִׁימִין דִּיּוֹקְנֵיהוֹן בְּעַמּוּדָא דְאֶמְצָעִיתָא, וּנְבִיאִים כֻּלְּהוּ רְשִׁימִין דִּיּוֹקְנֵיהוֹן בְּנֶצַח וָהוֹד דְּאִינוּן תְּרֵי סַמְכֵי קְשׁוֹט, וְצַדִּיקִים נָטְרֵי בְרִית כֻּלְּהוּ רְשִׁימִין דִּיוֹקְנֵיהוֹן בְּצַדִּיק, וּמָארֵי מַלְכוּתָא כֻּלְּהוּ רְשִׁימִין בַּמַּלְכוּת, וּמָארֵי יִחוּדָא כֻּלְּהוּ רְשִׁימִין בְּכֶתֶר עִלָּאָה דְאִיהוּ מַחֲשָׁבָה, דְתַמָּן צָרִיךְ לְסַלְקָא יִחוּדָא בְּמַחֲשָׁבָה סְתִימָא, וּבְכֻלְּהוּ תִּקּוּנִין אִלֵּין צָרִיךְ לְשַׁבְּחָא לְעִלַּת עַל כָּל הָעִלּוֹת, דְּאִיהוּ מִלְגָאו כְּנִשְׁמָתָא בְגוּפָא, וּבְגִין דִּבְנֵי נָשָׁא רְשִׁימִין בְּאִלֵּין דִּיּוֹקְנִין, אָמַר לְמֹשֶׁה וְאַתָּה תֶחזֶה וְגוֹמֵר.</p>\n<p>וְאַתָּה תֶחֱזֶה בְּשַׂעֲרָא, אִי אֲרִיךְ, אוֹ קָמוּט, אוֹ עָגוּל, שַׂעֲרָא שְׁעִיעַ אֲרִיךְ, אָרְחָא מִתְפַּלַּג בֵּיהּ לְכַמָּה אוֹרְחִין, עֲלָהּ אִתְּמַר (ישעיה מג טז) הַנּוֹתֵן בַּיָּם דָּרֶךְ, וְאָרְחִין אָחֳרָנִין דְּמִתְפָּרְשִׁין מִינָהּ, אִינוּן נְתִיבִין, הֲדָא הוּא דִכְתִיב (שם) וּבְמַיִם עַזִּים נְתִיבָה, תְּלָתִין וּתְרֵין שְׁבִילִין מִתְפָּרְשָׁאן מֵהַאי אָרְחָא.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ אָתֵי לְגַבֵּיהּ, וְאָמַר לֵיהּ, וְהָא דִיּוֹקְנִין אִלֵּין צָרִיךְ לְתַקְנָא לוֹן בַּאֲתַר דִּלְהוֹן, אָמַר רַבִּי שִׁמְעוֹן בְּוַדַּאי, אַף עַל גַּב דִּבְעָלְמָא דְפִירוּדָא, דִיּוֹקְנִין אִית סַגִּיאִין דְּאַכְחִשִׁין עוֹבָדָא דִבְּרֵאשִׁית, דְּלַאו אִינוּן אוֹרַח מִישׁוֹר, וְאִינוּן חֲשׁוֹכִין, מִגּוֹ חֲשׁוֹכָא אִשְׁתְּמוֹדָע נְהוֹרָא, דִיּוֹקְנִין דְּגִנְּתָא דְאַנְהָרָן בְּצִיּוּרָא דְעוֹבָדָא דִבְּרֵאשִׁית, מְרַקְּמֵי בְּכַמָּה גַוָּונִין נְהִירִין, וְאִינוּן כֻּלְּהוּ בְּקַו וּבְמִדָּה, וְאִלֵּין דְּעָלְמָא דְפִירוּדָא אִינוּן כִּקְלִיפִין דֶּאֱגוֹזָא לְגַבַּיְיהוּ, דְאִינוּן מוֹחָא מִלְּגָאו, וְעִם כָּל דָּא מִגּוֹ חֲשׁוֹכָא אִשְׁתְּמוֹדָע נְהוֹרָא, וּמִגּוֹ אִלֵּין קְלִיפִין דְּאִינוּן דִּיּוֹקְנִין חֲשׁוֹכִין, אִשְׁתְּמוֹדְעָן צִיּוּרִין דְּגִנְּתָא דְעִדֶן דִּלְתַתָּא, דְאִינוּן דִּיּוֹקְנָא דְמָאנֵי מַשְׁכְּנָא, אָמַר וַדַּאי הָכִי הוּא.</p>\n<p>פָּתַח וְאָמַר, שַׂעֲרָא שְׁעִיעַ אֲרִיךְ אִיהוּ רַחֲמֵי מִסִּטְרָא דַאֲרִיךְ אַנְפִּין, דְּאִיהוּ א, תְּרֵין אַנְפִּין דִּילֵיהּ ו' ו', כְּגַוְונָא דָא וָאו א בֵּינַיְיהוּ, וְאִיהוּ סָבָא דְסָבִין עַתִּיק דְּעַתִּיקִין, וְאִיהוּ (ס\"א ואתקרי) אֶרֶךְ אַפַּיִם. שַׂעֲרָא קְמִיטָא וְלָא שְׁעִיעַ אֶלָּא קָמִיט וְחָרִישׁ (נ\"א וחריט) אִיהוּ דִינָא, דָא רַחֲמֵי וְדָא דִינָא, דָּא אֲרִיךְ אַנְפִּין מִסִּטְרָא דְו', וְדָא זְעִיר אַנְפִּין מִסִּטְרָא דְי', שַׂעֲרָא לָא קָמִיט וְלָא אֲרִיךְ אִיהוּ בֵּינוּנִי.</p>\n<p>וְאִיהוּ שַׂעֲרָא דַאֲרִיךְ אַנְפִּין כְּגַוְונָא דִתְקִיעָה, וְקָמִיט וְחָרִישׁ (נ\"א ואריך) כְּגַוְונָא דִשְׁבָרִים ו' ו' ו', לָא אֲרִיךְ וְלָא קָמִיט אִיהוּ כְּגַוְונָא דִתְּרוּעָה, שַׁלְשֶׁלֶ\"ת דְּתַרְוַיְיהוּ, שַׂעֲרָא בְעִגּוּלָא כְּלִיל כֹּלָּא, וְאִיהוּ כְמִין כִּיפָּה דִרְקִיעָא דְאַסְחַר כֹּלָּא.</p>\n<p>כְגַוְונָא דָא יהו\"ה דָּא מַלְכוּתָא קַדִּישָׁא, אַנְשֵׁי חַיִל שַׂעֲרָא שְׁעִיעַ אֲרִיךְ, יִרְאֵי אלהי\"ם שַׂעֲרָא חָרִישׁ (נ\"א אריך) וְקָמִיט, אַנְשֵׁי אֱמֶת שַׂעֲרָא לָא אֲרִיךְ וְלָא קָמִיט, שַׁלְשֶׁלֶת דְּכֻלְּהוּ, שׂוֹנְאֵי בָצַע שַׂעֲרָא בְעִגּוּלָא.</p>\n<p>דָּוִד שִׁבְעָה מִינֵי דַהֲבָא הֲוָה בְּשַׂעֲרוֹי, זָהָב יְרַקְרַק, זָהָב אוֹפָז, זָהָב אוֹפִיר, זָהָב פַּרְוָיִם, זָהָב סָגוּר, זָהָב תַּרְשִׁישׁ, זָהָב כְּלִיל כָּל גּוּוָנִים, וְאִיהוּ</p>"],[9500011247,"<p>זְהַב שְׁבָא, וְהַאי אִיהוּ זָהָב מְזוּקָק שִׁבְעָתַיִם, וְהָכִי אִינוּן שִׁבְעָה מִינֵי חִוְורוּ, וְשֶׁבַע מִינֵי סוּמְקוּ, כָּל סְפִירָן אִתְקְרִיאוּ שְׁבִיעִיּוֹת מִסִּטְרָא דְצַדִּיק, עַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ כְּלִיל כָּל גַּוָּונִין, שַׂעֲרָא חִוְורָא אִיהוּ מִסִּטְרָא דִימִינָא, סוּמְקָא מִסִּטְרָא דִשְׂמָאלָא, יְרוֹקָא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, וְכֻלְּהוּ שִׁבְעָה שִׁבְעָה, שַׂעֲרָא אוּכְמָא מִסִּטְרָא דִשְׁכִינְתָּא, דְאִתְּמַר בָּהּ (שיר א ה) שְׁחוֹרָה אֲנִי וְנָאוָה, גַּוָּון יְחִידָה (נ\"א יחידאית) דְלָא תָּפִיס בָּהּ גַּוָּון כְּלָל, מִלְּגָאו דִּילָהּ גַּוָּון חִוָּור, וְרָזָא דְמִלָּה יָשֶׁת חֹשֶׁךְ סִתְרוֹ (תהלים יח יב).</p>\n<p>שַׂעֲרָא סוּמְקָא צָרִיךְ לְבַעִִרָא לֵיהּ מִכֹּל וָכֹל, בְּגִין דְּאִיהוּ בֵי דִינָא, וּלְוִיִּים בְּגִין דַּהֲווֹ מִסִּטְרָא דְּדִינָא, אִתְּמַר בְּהוֹן (במדבר ח ז) וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם, וְאִתְּתָא בְגִין דְּאִיהִי מִסִּטְרָא דִשְׂמָאלָא, לָא צָרִיךְ לְאִתְגַּלְיָא בָּהּ שַׂעֲרָא, דְּלָא יִשְׁתְּמוֹדְעִין בָּהּ מָארֵי דְּדִינָא, וְשַׂעֲרִין אָחֳרָנִין דְּבַר נַשׁ צָרִיךְ לְבַעֲרָא לֵיהּ תְּחוֹת אוּדְנִין, בְּגִין דְּלָא יִתְקְרִיבוּ בֵּיהּ מָארֵי דְּדִינִין לְגַבֵּי תַּרְעִין דְּשָׁמְעִין בְּהוֹן צְלוֹתִין, (ס\"א ושערא דאיהו תחות אודנין צריך לבערא, דאתקרי מארי דדינא לגביכו) שַׂעֲרָא שְׁעִיעַ עֲלֵיהּ אִתְּמַר (במדבר ו ה) גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, וְצָרִיךְ לְגַדְלָא לֵיהּ, דְּלָא צָרִיךְ לְאַכְחָשָׁא סִדּוּרָא דְעוֹבָדָא דִבְּרֵאשִׁית, אֲבָל שַׂעֲרָא דְעַמּוּדָא דְאֶמָצָעִיתָא צָרִיךְ דְּלָא יְהֵא לָא אֲרִיךְ וְלָא קְצִר, וַוי לֵיהּ לְמָאן דְּשַׁנִּי בֵיהּ סִדְרֵי בְרֵאשִׁית.</p>\n<p>שַׂעֲרָא אוּכְמָא, וְעַיְינִין אוּכְמִין, וְאַנְפּוֹי אוּכְמִין, וְגוּפֵיהּ אוּכְמָא, אִם הוּא זַכָּאָה אִיהוּ מִסִּטְרָא דִשְׁכִינְתָּא, דְאִתְּמַר בָּהּ שְׁחוֹרָה אֲנִי וְנָאוָה, דְכָל גַּוָּונִין דְּסִטְרָא דְּדַכְיוּ הָכִי אִינוּן כְּגַוְונָא דָא, וְאִם הוּא חַיָּיבָא הוּא מִסִּטְרָא דְשַׁבְּתַא\"י, פַּתְיָא אוּכְמָא, מִצַּד נוּקְבָא דִקְלִיפָה, דְתַמָּן כָּל קִסְמִין דְּעוֹרְבִין אוּכְמִין וְעוֹפִין אוּכְמִין מִסִּטְרָא דִמְסָאֲבוּ, דְאִית עֲלַיְיהוּ כַּמָּה מְמַנָּן דְּאִתְקְרִיאוּ לֵילוֹת, דַּעֲלַיְיהוּ אָמַר דָּוִד (תהלים טז ו) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי, מִפַּחַד בַּלֵּילוֹת (שיר ג ח).</p>\n<p>וְכֻלְּהוּ נָחֲתִין תְּחוֹת גַּדְפוֹי דְּעוֹרְבִין, וְאַחֲזֵי לוֹן בִּתְּנוּעָה דִלְהוֹן כַּמָּה דִינִין דְּנָחֲתִין עַל עָלְמָא, וְאִית אָחֳרָנִין דִּמְמַנָּן עַל קָלִין דִּלְהוֹן, וְצָוְוחִין קָלָא בָתַר קָלָא כֻּלְּהוּ בַשְּׁבָרִים, לְאַחֲזָאָה תְּבִירוּ עַל בְּנֵי נָשָׁא, וּלְזִמְנִין צָוְוחִין בִּתְלַת סִימָנִין דְּאִינוּן קר\"ק, דְּאִיהוּ תְּקִיעָה תְּרוּעָה תְּקִיעָה, לְאַחֲזָאָה דִינָא רַפְיָא בְרֵישָׁא וּבְסֵיפָא, וּבְאֶמְצָעִיתָא תְּבִירָא סַגִּי, בִתְרוּעָה דָּחֲקָא בָתַר דָּחֲקָא בִמְהִירוּ, וְרָזָא דְמִלָּה וּבְחַדְרֵי מִשְׁכָּבְךָ אַל תְּקַלֵּל עָשִׁיר, כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל (קהלת י כ), נָחָשׁ רְכִיב עַל קָלָא דְעוֹרְבָא אֵל אַחֵר, בַּת זוּגֵיהּ קֶסֶם סַם הַמָּוְת, דְּבָהּ אִשְׁתַּלִּים סמא\"ל אֵל אַחֵר.</p>\n<p>רְכִיבַת אִיהִי עַל תְּנוּעִין דְּגוּפָא דְעוֹרֵב, וְאִיהִי תְנוּעָה דְכֻלְּהוּ, דְנָפְקַת לְאַסְטָאָה לִבְנֵי נָשָׁא בְּפָרָשַׁת אוֹרְחִין, תְּנוּעָה דִילָהּ בְּרֵישָׁא דְעוֹרְבָא, וּבִזְנָבָא וּבְגוּפָא וּבְגַדְפִין דְּעוֹרְבָא, נָחָשׁ שַׁרְיָא בִקְרִיאָה וַאֲמִירָה וְקָלָא וְדִבּוּר דְּעוֹרְבָא, וּבְאִלֵּין תְּנוּעִין שַׁרְיָין כָּל הוֹלֵךְ עַל גָּחוֹן וְכָל הוֹלֵךְ עַל אַרְבַּע מִסִּטְרָא דִמְסָאֲבוּ.</p>\n<p>וּמְנָא יָדְעִין כּוּלֵי הַאי, בְּגִין דְּסמא\"ל וְנָחָשׁ מְמַנָּן עַל חוֹבִין דִּבְנֵי נָשָׁא, דְאִתְדָּנוּ מִסִּטְרָא דִשְׂמָאלָא דְאִיהוּ גְבוּרָה, וְכַד בַּר נַשׁ עָבִיד חוֹבִין, כְּפוּם הַהוּא בַּר נַשׁ הָכִי סָלִיק חוֹבֵיהּ לַאֲתַר דְּאִתְגַּזַּר נִשְׁמָתֵיהּ, וְלָא זָז מִתַּמָּן הַהוּא חוֹבָא עַד דְּאִתְפַּרַע מֵהַהוּא בַּר נַשׁ, וְאִם בַּר נַשׁ אִיהוּ נִשְׁמָתֵיהּ בְּאֹרַח אֲצִילוּת, אִם חָאב, חוֹבֵיהּ מְטֵי עַד סְפִירָן, וְעוֹנְשָׁא אִיהוּ סַגִּי כְּפוּם דַּרְגֵיהּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא וְכִי חוֹבָא אִיהוּ בְּבַר נַשׁ דְּתַלְיָא נִשְׁמָתֵיהּ מֵהַהוּא אֲתַר, וְכִי אִית לֵיהּ חוֹבִין, וְהָא כְּתִיב (משלי יב כא) לֹא יְאֻנֶּה לַצַּדִּיק כָּל אָוְן, אָמַר לֵיהּ אִין, הֲדָא הוּא דִכְתִיב (ישעיה נט ב) כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם לְבֵין אלהיכ\"ם, מַאי מַבְדִּילִים, אֶלָּא דְסָלִיק הַהִיא נִשְׁמָתָא דַאֲצִילוּתָא מִנֵּיהּ וְאִתְפָּרַשׁ מִנֵּיהּ.</p>"],[9500011248,"<p>וְרָזָא דְמִלָּה, וַיֹּאמֶר אלהי\"ם יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה וְגוֹמֵר (בראשית א ו), אִסְתַּלַּק נִשְׁמָתֵיהּ מִנֵּיהּ וְאִשְׁתָּאַר גּוּפָא יְבֵשָׁא, מָאן גּוּפָא הָכָא, דָא נִשְׁמָתָא דְכָרְסַיָּא יְקָרָא (נ\"א דקב\"ה יהו\"ה) דְּאִשְׁתְּאָרַת יְבֵשָׁה, בְּגִין דְּאִסְתַּלְקַת מִנֵּיהּ נִשְׁמָתָא בְאֹרַח אֲצִילוּת, דְּהַאי נִשְׁמָתָא אִיהִי גוּפָא לְנִשְׁמָתָא עִלָּאָה, וְאִי בָּעִי דְתַחֲזוֹר לְגַבֵּי הַהוּא נִשְׁמָתָא, לֵית לָהּ רְשׁוּ לְאַחֲזָרָא לְגַבֵּיהּ, עַד דְּהַהוּא חוֹבָא אִתְעַבְרַת מִנֵּיהּ, וְרָזָא דְמִלָּה שׁוּבוּ אֵלַי וְאָשׁוּבָה אֲלֵיכֶם (מלאכי ג ז).</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אֲבוֹי, אַבָּא אִלֵּין תְּנוּעִין דְּעוֹרְבָא מַאי לְאִשְׁתְּמוֹדָע בְּהוּ בַּר נַשׁ בְּגִין דְּיַחֲזוֹר בִּתְיוּבְתָּא, אָמַר לֵיהּ בְּרִי וַדַּאי אֲסִיר לְאִסְתַּכְּלָא בְּהוֹן לְעַמָּא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב (במדבר כג כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, אֲבָל אִם יִזְדַּמַּן לְבַר נַשׁ לְפוּם שַׁעִִתָּא וְיֵדַע בְּהוֹן, יִסְתַּכַּל בְּהוֹן בְּגִין דְּיַחֲזוֹר מֵחוֹבוֹי בִּתְיוּבְתָּא, וְהַאי לְבַר נַשׁ דְּכָל (נ\"א דלא) עוֹבָדוֹי כְּיַעֲקֹב וּכְיִשְׂרָאֵל, דְּבַר נַשׁ דְּיַעֲבִיד עֹבְדֵי דְּיַעֲקֹב דְּאִתְּמַר בֵּיהּ (בראשית כה כג) וְיַעֲקֹב אִישׁ תָּם, מַה כְּתִיב בֵּיהּ (ירמיה י טז) לֹא כְאֵלֶּה חֵלֶק יַעֲקֹב.</p>\n<p>דְּמִסִּטְרָא דְיַעֲקֹב וְיִשְׂרָאֵל בָּעָא בִּלְעָם חַיָּיבָא לְאִסְתַּכְּלָא בְּנַחֲשׁוֹי וּבְקִסְמוֹי, וְלָא אַשְׁכַּח אֲתַר לְאַעָלָא לְגַבֵּיהּ, וּבְגִין דָּא אָמַר כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְהָא בְּלָבָן כְּתִיב (בראשית ל כז) נִחַשְׁתִּי וַיְבָרַכֵנִי יהו\"ה בִּגְלָלֶךָ, אִם כֵּן אַמַּאי אַעִִרַב בֵּיהּ, אָמַר בְּרִי הָכָא רָזָא עִלָּאָה, דִלְזִמְנִין שׁוֹשַׁנָּה אִשְׁתַּכְּחַת בֵּין קוֹצִים, וְהָכָא רָזָא דְגִלְגּוּלָא, אָמַר לֵיהּ יְדַעִִנָא, וְעִם כָּל דָּא בְּרִי, אַף עַל גַּב דְּאִתְּמַר כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, בַּר נַשׁ צָרִיךְ לְמִנְדַּע כֹּלָּא וַאֲפִילוּ חָרָשִׁין, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, לֹא תִלְמַד לַעֲשׂוֹת (דברים יח ט), אֲבָל אַתָּה לָמֵד לְהָבִין וּלְהוֹרוֹת.</p>\n<p>וּבְגִין דָּא תְּנוּעִין דְּעוֹרְבָא, אִית תְּנוּעָה דְסָלִיק בְּרָבִי\"עַ, וְאַחֲזֵי דְחוֹבָא דִילֵיהּ תַּלְיָא לְעִילָא בְעָלְמָא דְאָתֵי, וְאִית תְּנוּעָה דְנָחִית לָהּ בַּתְּבִי\"ר בַּשְּׁבָרִים, וְאַחֲזֵי דְחוֹבָא דִילֵיהּ נָחִית לְתַתָּא בְעָלְמָא דֵין, לְמֶהֱוִי לֵיהּ תְּבִירוּ בְּגִינֵיהּ, וְכָל אִלֵּין סִימָנִין אִיהִי אַחֲזֵי בְּאָרְחָא, כְּגַוְונָא דַעֲמָלֵק דְּאָמַר בְּגִינֵיהּ (שם כה יח) אֲשֶׁר קָרְךָ בַּדֶּרֶךְ, דְּסִטְרִין אָחֳרָנִין אִינוּן כְּלִסְטִים דְּנָפְקִין בְּאָרְחִין, וּבְגִין דָּא עוֹרְבִין חֵילָא דִלְהוֹן בְּאוֹרְחִין.</p>\n<p>וְאִינוּן דְּמַזָּלְהוֹן תַּלְיָא בְּשַׁבְּתַ\"י, אִינוּן עֲצִיבִין, וְאִינוּן דּוֹחֲקִין רַגְלֵי שְׁכִינְתָּא בְּגָלוּתָא, דִּבְזִמְנָא דְאִלֵּין אִתְפַּשְׁטוּ בְעָלְמָא, אִתְּמַר בְּרַגְלֵי שְׁכִינְתָּא וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה (בראשית מט לג), אִתְכְּנִישַׁת לְגַבֵּי זַרְעִיהּ דְּיַעֲקֹב מִטָּה שְׁלֵמָה, וּבְגִין דָּא וַיִּשְׁכּוֹן יִשְׂרָאֵל בֶּטַח בָּדָד עִין יַעֲקֹב (דברים לג כח), דְּלָא זָזַת שְׁכִינְתָּא מִינַיְיהוּ בְּגָלוּתָא, בְּגִין דְּלֵית בְּהוּ פִסּוּלָא, וְשַׁבְּתַא\"י אִית לֵיהּ תְּרֵין בָּתִּין, חַד שְׁפַל רֹאשׁ, וְתִנְיָינָא בֵּית הַסֹּהַר, דַּאֲסִירֵי מַלְכָּא אֲסִירִין תַּמָּן בְּגָלוּתָא, וְאִינוּן דָּחֲקִין שְׁכִינְתָּא וְיִשְׂרָאֵל (נ\"א שעתא לישראל) בְּגָלוּתָא, וּבִשְׁפַל רֹאשׁ יִשְׂרָאֵל אִינוּן שְׁפֵלִין לְתַתָּא, וּמֵהַאי כֹּכָבָא יֵיתֵי כַפְנָא וַעֲנִיּוּתָא לְיִשְׂרָאֵל, וּמָאן דְּבָעִי לְאִסְתַּמְרָא מִנֵּיהּ, צָרִיךְ לְשַׁנּוּיֵי שְׁמֵיהּ וּלְשַׁנּוּיֵי אַתְרֵיהּ וּלְשַׁנּוּיֵי עוֹבָדוֹי, וְדָא אִיהוּ שִׁנּוּי מָקוֹם שִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה, וְהָא אוּקְמוּהוּ הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר (איוב לג כט).</p>\n<p>שַׂעֲרָא חִוְורָא וְעִינוֹי חִוְורִין וְאַנְפּוֹי חִוְורִין וְגוּפָא חִוְורָא, אִי אִית בֵּיהּ עוֹבָדִין טָבִין דָּא אִיהוּ מִסִּטְרָא דִימִינָא, מִסִּטְרָא דִרְחִימוּ דְאִיהוּ אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד (ירמיה לא ב). שַׂעֲרָא חִוְורָא וְעִינוֹי חִוְורִין וְאַנְפִּין חִוְורִין וְגוּפָא חִוְורָא, דְלֵית בֵּיהּ גְּמִילוּת חֲסָדִים בִּרְחִימוּ דְאַהֲבָה, הַאי הוּא רַמַּאי מִסִּטְרָא דְלָבָן הָאֲרַמִּי, אִסְתַּמַּר מִנֵּיהּ, בַּהֶרֶת לְבָנָה הִיא, וְלִילִי\"ת הִיא בַּהֶרֶת לְבָנָה אוּכְמָא סוּמְקָא יְרוֹקָא, הֲדָא הוּא דִכְתִיב (ויקרא יג ד) וְאִם בַּהֶרֶת לְבָנָה הִיא בְּעוֹר בְּשָׂרוֹ וְעָמוֹק אֵין מַרְאֵהוּ מִן הָעוֹר, בַּהֶרֶת שְׁחוֹרָה וּשְׁפָלָה אֵינֶנָּה מִן הָעוֹר וְהִיא כֵהָה, תְּרֵין</p>"],[9500011249,"<p>גַּוָּונִין תִּנְיָינִין אִינוּן יְרַקְרַק אוֹ אֲדַמְדָּם, כֻּלְּהוּ מִתְהַפְּכִין עִינוֹי בְּכַעִִסָא לְחִוְורוּ וְאוּכְמוּ וְסוּמְקוּ וִירוֹקָא, וְכָל דָּא בְּמַאי אִשְׁתְּמוֹדָע, דְּלֵית בַּר נַשׁ דְּלָא אִתְכְּלִילָן בֵּיהּ אִלֵּין אַרְבַּע גַּוָּונִין, אֶלָּא הַהוּא גַוָּון דְּשַׁלִּיט עַל כֻּלְּהוּ אָחֳרָנִין, בֵּיהּ אִתְקְרֵי, וּבֵיהּ אִשְׁתְּמוֹדָע לְאִתְקְרֵי חִוָּור אוֹ אוּכַם אוֹ סוּמַק אוֹ יָרוֹק, וְאִלֵּין אַרְבַּע גַּוָּונִין בִּישִׁין אִינוּן אַרְבַּע קְלִיפִין דֶּאֱגוֹזָא, תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וּתְהוֹם, וְאִלֵּין אִינוּן (דברים ח טו) נָחָשׁ שָׂרָף וְעַקְרָב וְצִמָּאוֹן, נָחָשׁ גַּוָּון חִוָּור בַּהֶרֶת לְבָנָה, שָׂרָף וְעַקְרָב, אֲדַמְדָּם שָׂרָף, אוֹ יְרַקְרַק עַקְרָב, וְצִמָּאוֹן שְׁחוֹרָה, אִלֵּין אִינוּן אַרְבַּע גַּוָּונִין דְּאֶשָּׁא דְגֵיהִנָּם.</p>\n<p>וְאִתְּתָא בִּישָׁא מִתַּמָּן קָא אַתְיָא, עֲלָהּ אִתְּמַר (ויקרא יד מה) וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עִצָיו בַּעֲנִיּוּתָא, דְלָא אִשְׁתָּאַר בְּבֵיתָא, וּבְגִין דָּא חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ, וְאִוְּלֶת בְּיָדֶיהָ תֶהֶרְסֶנּוּ (משלי יד א), אִלֵּין אִינוּן אַרְבַּע גַּוָּונִין דְּאֶשָּׁא דְגֵיהִנָּם, דְּמִסְתַּלְקֵי בְּעַיְינִין בְּאַנְפִּין בְּשַׂעֲרָא, וּמֵאָן אֲתַר מִסְתַּלְקֵי, מִמָּרָה אוּכְמָא דִטְחוֹל, וּמִמָּרָה סוּמְקָא דְכָבֵד, וּמִמָּרָה יְרוֹקָא דְמָרָה, וּמִמָּרָה חִוְורָא דְרֵיאָה, אִלֵּין אִינוּן אַרְבַּע גַּוָּונִין חֲשׁוֹכִין דְּמַלְאֲכֵי חַבָּלָה, וְכֻלְּהוּ כְּלִילָן בְּלִילִי\"ת סַם הַמָּוְת, מַאֲדִי\"ם אִיהוּ בְמָרָה אֲדוּמָה לְמִשְׁפַּךְ דְּמָא, וְאִיהוּ מַכַּת חֶרֶב וְהֶרֶג וְאַבְּדָן.</p>\n<p>וְהָכִי שְׁכִינְתָּא אִשְׁתְּמוֹדְעַת בְּאַרְבַּע גַּוָּונִין שַׁפִּירִין נְהִירִין, גַּוָּון חִוָּור מִסִּטְרָא דְחֶסֶד, סוּמַק מִסִּטְרָא דִגְבוּרָה, יָרוֹק מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, אוּכַם מִסִּטְרָא דְאִימָּא עִלָּאָה, דְאִתְּמַר בָּהּ (משלי א ח) שְׁמַע בְּנִי מוּסַר אָבִיךָ וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ, וְאִתְּמַר בָּהּ (שיר א ה) שְׁחוֹרָה אֲנִי וְנָאוָה, אִימָּא תַּתָּאָה נְטִילַת גַּוָּון מֵאִימָּא עִלָּאָה, שׁוֹקָא יְמִינָא נָטִיל גַּוָּון מִדְּרוֹעָא יְמִינָא, הֲדָא הוּא דִכְתִיב (תהלים טז יא) נְעִימוֹת בִּימִינְךָ נֶצַח, שׁוֹקָא שְׂמָאלָא נָטִיל גַּוָּון מִדְּרוֹעָא שְׂמָאלָא, אוֹת בְּרִית נָטִיל גַּוָּון מִגּוּפָא, עַמּוּדָא דְאֶמְצָעִיתָא נָטִיל חָכְמָה, אָדָם דְּרָכִיב עַל כֹּלָּא, עֲלָהּ אִתְּמַר (קהלת ח א) חָכְמַת אָדָם תָּאִיר פָּנָיו, וַעֲלֵיהּ אִתְּמַר (תהלים קד כד) יהו\"ה כֻּלָּם בְּחָכְמָה עָשִׂיתָ, כֶּתֶר עִלָּאָה אִיהוּ סָתִים לָא אִשְׁתְּמוֹדָע בֵּיהּ גַּוָּון כְּלָל לְעִילָא, וּבְעַמּוּדָא דְאֶמְצָעִיתָא אַחֲזֵי כָּל גַּוָּונִין.</p>\n<p>הָא הָכָא רָזָא דְשַׂעֲרָא, דְבֵיהּ אִשְׁתְּמוֹדְעָאן אַנְשֵׁי חַיִל בְּגַוָּון חִוָּור, יִרְאֵי אלהי\"ם בְּגַוָּון סוּמַק, אַנְשֵׁי אֱמֶת בְּגַוָּון יָרוֹק, שׂוֹנְאֵי בָצַע בְּגַוָּון אוּכַם, אַרְבַּע אַתְוָון מִתְלַבְּשִׁין בְּאַרְבַּע גַּוָּונִין אִלֵּין, י' בְּגַוָּון חִוָּור, ה' בְּגַוָּון סוּמַק, ו' בְּגַוָּון יָרוֹק, ה' בְּגַוָּון אוּכַם, הַאי שְׁמָא אִיהוּ דְרָקִים גַּוָּונִין בְּכָל אֲתַר, וְאִיהוּ דְצִיֵּיר שִׁרְטוּטִין בְּמִצְחָא, כְּגַוְונָא דָא יהו\"ה, וְאִינוּן אַרְבַּע רְשִׁימִין דְּשִׁרְטוּטִין, דְּאִינוּן עֹמֶק רוּם וְעֹמֶק תַּחַת וְעֹמֶק מִזְרָח וְעֹמֶק מַעֲרָב, שִׁרְטוּטִין זְעִירִין דִּקְרִיצִין דְּעִינָא מִסִּטְרָא דְאָת י', שִׁרְטוּטִין בְּאוּרְכָא בְפוּתְיָא בְּגָבְהָא מִסִּטְרָא דִתְלַת אַתְוָון דְּאִינוּן הו\"ה, כֻּלְּהוֹן אִשְׁתְּמוֹדְעִין בְּשִׁעוּר קוֹמָה דְבַר נַשׁ, בְּאוּרְכָא מִסִּטְרָא דַאֲרִיךְ קוֹמָה, דְאִינוּן אַנְשֵׁי חַיִל, בְּפוּתְיָא קָצֵר קוֹמָה וּרְחָבָא דְקוֹמָה, וְאִינוּן יִרְאֵי אלהי\"ם, בְּגָבְהָא גְבַהּ קוֹמָה וְאִינוּן אַנְשֵׁי אֱמֶת, זְעִירִין בְּעִגּוּלָא שׂוֹנְאֵי בָצַע מִסִּטְרָא דְאָת י', וְדָוִד מִסִּטְרָא דְאָת י' אִתְּמַר בֵּיהּ (שמואל א יז יד) וְדָוִד הוּא הַקָּטָן, וְאִלֵּין אִינוּן שׂוֹנְאֵי בָצַע, שִׁרְטוּטִין אִלֵּין בְּאֹרַח מֵישַׁר, כְּשִׁרְטוּטִין דְּגֵט פִּטּוּרִין דְּצָרִיךְ שִׁרְטוּטֵי, אוֹ אִלֵּין דִּמְחַיְּיבָא אוֹרַיְיתָא, וְעַל אִלֵּין שִׁרְטוּטִין אִתְּמַר (תהלים כה י) כָּל אָרְחוֹת יהו\"ה חֶסֶד וְאֱמֶת לְנֹצְרֵי בְרִיתוֹ וְעִדוֹתָיו.</p>\n<p>שִׁרְטוּטִין בַּאֲרִיכוּ מִסִּטְרָא דְרָבִי\"עַ כְּגַוְונָא דִתְּקִיעָה, וְאִלֵּין אִינוּן אֲרִיכִין דְּקוֹמָה מִסִּטְרָא דִיְמִינָא, אֶרֶךְ אַפַּיִם, אֲרִיכִין בְּקָלָא בִּצְלוֹתִין בְּאוֹרַיְיתָא, אֲרִיכִין בְּרוּגְזָא, אֲרִיכִין בְּשַׂעֲרָא בְּעַיְינִין בְּאַנְפִּין בְּחוֹטָמָא בְּשִׂפְוָון בְּדִיקְנָא בְּגוּפָא בִּדְרוֹעִין בְּרַגְלִין בְּאֶצְבְּעָן</p>"],[9500011250,"<p>רְשִׁימוּ דִלְהוֹן חִוָּור, וַוי לוֹן לְאִלֵּין דְּמַכְחִישִׁין דִּיּוֹקְנֵיהוֹן לְעִילָא, כְּאִלּוּ מַכְחִישִׁין סִדְרֵי בְרֵאשִׁית, וּכְאִלּוּ מְמַעֲטִין אֶת הַדְּמוּת, דְּאִיהוּ שִׁיעוּר קוֹמָה דִלְעִילָא, דְּאִלֵּין דְּשִׁרְטוּטֵיהוֹן אֲרִיכִין, וְקוֹמָה דִלְהוֹן וְאֵבָרִים דִּלְהוֹן, צְרִיכִין לְמֶהֱוֵי מָארֵי דְחֶסֶד, אֲרִיכִין דְּרוּגְזָא, מָארֵי דִרְחִימוּ, הַהוּא דְאִתְּמַר בֵּיהּ (ישעיה מא ח) זֶרַע אַבְרָהָם אוֹהֲבִי.</p>\n<p>שִׁרְטוּטִין בְּרָחְבָּא, כְּגַוְונָא דִשְׁבָרִים, תְּנוּעָה דִלְהוֹן תְּבִי\"ר, וְאִינוּן רְחָבִים וּקְצָרִים דְּקוֹמָה, וְאַנְפִּין רְחָבִין וּקְצָרִין, וְעִינוֹי רְחָבִים, וְחוֹטָמוֹי רְחָבִים, וְשִׂפְוָון רְחָבִים, אִלֵּין אִינוּן יִרְאֵי אלהי\"ם, מָארֵי דְיִרְאָה מִסִּטְרָא דְיִצְחָק, וַוי לְמָאן דְּאַכְחִישׁ קוֹמָתֵיהּ בְּעוֹבְדִין בִּישִׁין, דְּיָרִית נִשְׁמָתָא בִּישָׁא דְרָכִיב עַל דִּיּוֹקְנֵיהּ, דְּאַכְחִישׁ פַּמַּלְיָא לְעִילָא. שִׁרְטוּטִין גְּבוֹהִין, וְאַנְפִּין גַּבְהָנִין, וְעִינוֹי גַּבְהָנִין, וְחוֹטָמָא וְשִׂפְוָון גַּבְהָנִין, וְגוּפָא גָבוֹהַּ, אִלֵּין אִינוּן מָארֵי דִקְשׁוֹט זֶרַע אֱמֶת, מֵהַהוּא דְאִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב.</p>\n<p>וְאִלֵּין אִינוּן אדנ\"י, א' אֲרִיךְ אַנְפִּין וַעֲלֵיהּ שַׁרְיָא י', ד' רָחְבָּא דְאַנְפִּין וַעֲלֵיהּ שַׁרְיָא ה', נ' גּוֹבַהּ דְּאַנְפִּין וַעֲלֵיהּ שַׁרְיָא ו', י' רָחְבָּא דְאַנְפִּין וַעֲלֵיהּ שַׁרְיָא ה', שִׁרְטוּטִין זְעִירִין מִסִּטְרָא דִתְּרוּעָה בְעִגּוּלָא בְדִיּוֹקְנָא דְאָת י', שׂוֹנְאֵי בָצַע, מִסִּטְרָא דְּדָוִד דְּאִתְּמַר בֵּיהּ (שמואל א יז יד) וְדָוִד הוּא הַקָּטָן, וְאִינוּן עַיְינִין זְעִירִין שַׁפִּירִין בְּעִגּוּלָא, אַנְפִּין זְעִירִין בְּעִגּוּלָא שַׁפִּירִין, חוֹטָמָא זְעִירָא פִּימָא זְעִירָא גּוּפָא דִילֵיהּ זְעִירָא, שַׁפִּיר בְּכֹלָּא, וַעֲלֵיהּ שַׁרְיָא ה'.</p>\n<p>שִׁרְטוּטִין גַּבְהָנִין מִסִּטְרָא דִתְּרוּעָה, שַׁלְשְׁלָאָ\"ה דִתְּקִיעָה וּשְׁבָרִים, דָּא סָלִיק קָלָא בִתְרוּעָה, וְדָא תַּבַּר לָהּ בַּשְּׁבָרִים, וְדָא בֵינוּנִי בְקָלֵיהּ, שַׁלְשְׁלָאָה דִתְּקִיעָה וּשְׁבָרִים, לָא אֲרִיךְ וְלָא קְצִר, מָאן דְּאִיהוּ בְּדִיּוֹקְנָא דְאָת יו\"ד אִיהוּ קוֹל דְּמָמָה דַקָּה, וְדָא מִדָּה לְכָל אֵבָרִין דְּאַנְפִּין לְעִילָא, מִתַּתָּא לְעִילָא, אִיהִי מִדָּה לְכָל סְפִירָה וּסְפִירָה מֵעֲשַׂר סְפִירָאן, וּבָהּ סְלִיקַת כָּל סְפִירָה לַעֲשֶׂרֶת אֲלָפִים רִבֵּי רְבָבוֹת, ו' שִׁעוּרֵיהּ בְּכָל סְפִירָה וּסְפִירָה שֵׁשֶׁת אֲלָפִים רִבֵּי רְבָבוֹת, ה' ה' אִינוּן מַהֲלַךְ בְּכָל סְפִירָה וּסְפִירָה ה' אֲלָפִים רִבֵּי רְבָבוֹת, מֵעִילָא לְתַתָּא, וּמִתַּתָּא לְעִילָא.</p>\n<p>שִׁרְטוּטִין עֲקִימִין דְּלַאו אִינוּן רְשִׁימִין בְּאֹרַח מֵישַׁר, אִנּוּן רְשִׁימִין דְּנָחָשׁ עֲקַלָּתוֹן, דְּשִׁרְטוּטִין כְּשַׁלְשְׁלָאָה כְּגַוְונָא דָא (אינון מהלך דנונין דימא), (נ\"א מהלך דלהון כנונין בימא), דְּאִינוּן כְּגַוְונָא דְתַלְמִידֵי חֲכָמִים דְּמִתְרַבִּין בְּיַמָּא, וְאִינוּן רָזָא דִתְּרוּעָה, [ציור] וְשַׁלְשֶׁלֶת וְהָכִי מַהֲלַךְ דְּנוּנַיָּא כְּגַוְונָא דִתְּרוּעָה, וְאִינוּן דַּרְגָּ\"א לְתַתָּא, שַׁלְשֶׁלֶת לְעִילָא, כְּגַוְונָא דִקְדוּשָׁה הָכִי אִינוּן רְשִׁימִין מִסִּטְרָא דִמְסָאֲבוּ, דְּהָכִי אוּקְמוּה מָארֵי מַתְנִיתִין (קהלת ז יד) זֶה לְעְִמַּת זֶה עָשָׂה הָאלהי\"ם.</p>\n<p>שִׁרְטוּטִין אִינוּן כְּגַוְונָא דְלוּלָב, דְּאִתְּמַר בֵּיהּ נִפְרְצוּ עַלָּיו פָּסוּל, הָכִי שִׁרְטוּטִין דְּאִית בְּהוּ פְרִידוּ וּפְרִיצוּ, דָא אַחֲזֵי בְּגִלְגּוּלָא דִילֵיהּ קֳדָם דְּאַתְיָא לְעָלְמָא, דַהֲוָה מְקַצֵּץ בִּנְטִיעוֹת וְעָבִיד פִּרוּדָא בְּאִילָנָא דְחַיֵּי, בַּאֲתַר דְּאִתְגְּזַרַת נִשְׁמָתֵיהּ, וּבְמַאי אִשְׁתְּמוֹדָע, אֶלָּא שִׁרְטוּטִין דְּאִינוּן אֲרִיכִין כְּגַוְונָא דָא [ציור] (נ\"א [ציור]) לֵית בְּהוּ פָסֵק שַׁלְמִין אִינוּן, הַאי בַּר נַשׁ לָא אַכְחִישׁ דִּיּוֹקְנֵיהּ, וְלָא עָבַד פִּרוּדָא בְּאִילָנָא דְחַיֵּי.</p>\n<p>וְאִם אִית בְּהוּ פָסֵק כְּגַוְונָא דָא (נ\"א) הַאי בַּר נַשׁ אַכְחִישׁ דִּיּוֹקְנֵיהּ, וְעָבַד פְּגַם וּמוּם, וּבְהַהוּא פְגַם שַׁרְיָא מוּם, כְּפוּם מוּם דְּסִיהֲרָא, פָּרִיץ אִיהוּ, מֵצַח אִשָּׁה זוֹנָה (ירמיה ג ג), שַׁרְיָא בֵּיהּ פְּרִיצוּ בְּמִצְחוֹ, מֵהַהוּא אֲתַר אִיהוּ פְגִים, וְצָרִיךְ לְכַסָּאָה מִצְחוֹ דְלָא יִתְגְּלֵי עִִרְיָתֵיהּ לְמָארֵי דְּדִינָא, וְאִם חָזַר בִּתְיוּבְתָא, יְהֵא פְּגִימוּ דִילֵיהּ נָחִית לְתַתָּא, לָקֳבֵל בָּהּ עָנְשָׁא, וְאִם לַאו אִיהוּ חוֹזֵר בִּתְיוּבְתָּא, מִסְתַּלְקַת לְעִילָא לְתַבְעָא לֵיהּ דִּינָא בְעָלְמָא דְאָתֵי, בְהַהוּא אֲתַר דְּפַגִּים, עֲלֵיהּ אִתְּמַר (שמות כא טז) מֵעִם מִזְבְּחִי תִּקָּחֶנּוּ לָמוּת, וְלָא לְמַגָּנָא אָמְרוּ קַדְמָאִין, בְּמָקוֹם שֶׁאָמְרוּ לְהַאֲרִיךְ אֵינוֹ רַשַּׁאי לְקַצֵּר, לְקַצֵּר אֵינוֹ רַשַּׁאי לְהַאֲרִיךְ, דְּלָא יַכְחִישׁ דִּיּוֹקְנֵיהּ וְיַעֲבֵיד</p>"],[9500011251,"<p>פְּרִיצוּ בְדִיּוֹקְנָא דִלְעִילָא.</p>\n<p>בְאוֹרַיְיתָא דִלְעִילָא מָאן דְּרָשִׁים וְצִיֵּיר אִלֵּין שִׁרְטוּטִין, אִיהוּ אָמוֹן מוּפְלָא וּמְכוּסֶה, מָאן דְּאִסְתַּכַּל בְּשִׁפּוּלֵי מַשְׁכְּנָא, אִשְׁתְּמוֹדָע בְּאִלֵּין רְשִׁימִין וְצִיּוּרִין, דְּאִתְּמַר בְּהוֹן (תהלים קלט טו) רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ, צִיּוּרָא דְאַרְבַּע שִׁרְטוּטִין אִלֵּין, אִינוּן אַרְיֵה שׁוֹר נֶשֶׁר אָדָם, בְּכֻלְּהוּ אַרְבַּע רְשִׁימִין, הֲדָא הוּא דִכְתִיב (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם, וְדָא מִיכָאֵ\"ל שַׂר הַחֶסֶד לִימִינָא, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעִִתָּן, דָּא גַבְרִיאֵ\"ל שַׂר הַגְּבוּרָה, וּפְנֵי נֶשֶׁר לְאַרְבַּעִִתָּן דָּא נוּרִיאֵ\"ל (נ\"א אוריא\"ל) שַׂר שָׁלוֹם עַמּוּדָא דְאֶמְצָעִיתָא, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, רְפָאֵ\"ל שַׂר שְׁכִינְתָּא, דְתַמָּן פְּאֵר, דְּאִתְּמַר בָּהּ (יחזקאל כד יז) פְּאֵרְךָ חֲבוֹשׁ עָלֶיךָ.</p>\n<p>מָאן דְּלָא אִתְחַזְיָין שִׁרְטוּטִין בֵּיהּ, לֵית לֵיהּ דִּיּוֹקְנָא כְלָל לְעִילָא, זְכוּתֵיהּ נָחִית לְתַתָּא, עֲלֵיהּ אִתְּמַר (תהלים סט כט) יִמָּחוּ מִסֵּפֶר חַיִּים, אֶלָּא אִם תָּב בִּתְיוּבְתָּא, דְּדָא אִשְׁתַּכַּח דְּלֵית לֵיהּ בַּמֶּה דְיֵיתֵי בְּגִלְגּוּלָא, מָאן דְּשִׁרְטוּטִין דִּילֵיהּ רְכִיבִין כְּגַוְונָא דָא [ציור] (נ\"א [ציור]) דָּא אַחֲזֵי דְקָא אַתְיָא בְגִלְגּוּלָא חֲדָא, וְאִם תְּרֵין שִׁרְטוּטִין מוּרְכָּבִין כְּגַוְונָא דָא [ציור] (נ\"א [ציור]), אַחֲזֵי תְּרֵין גִּלְגּוּלִין, וְאִם תְּלַת שִׁרְטוּטִין בְּמִצְחֵיהּ מוּרְכָּבִין, הָא אַשְׁלִים (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, וְאִם לֵית לֵיהּ שִׁרְטוּטִין בְּמִצְחֵיהּ, וְאִית שִׁרְטוּטִין עַל קְרִיצִין דְּעַיְינִין, דָּא אַחֲזֵי עַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ (עמוס ב א).</p>\n<p>שִׁרְטוּטִין אִינוּן בְּאַתְוָון דְּאִינוּן יהו\"ה, צִיּוּרִין בִּנְקוּדִין דְּאִינוּן יו\"ד ה\"י וא\"ו ה\"י, וְצִיּוּרִין אִינוּן בְּעַיְינִין בְּאוּדְנִין בְּאַנְפִּין בְּנוּקְבִין דְּחוֹטָמָא בְּפוּמָא, קָמֵ\"ץ שִׁרְטוּט וְצִיּוּר, שִׁרְטוּט לְעִילָא וּנְקוּדָה לְתַתָּא, דָּא אַחֲזֵי עַל גִּלְגּוּלָא קַדְמָאָה, דְקָא נָחִית לְתַתָּא.</p>\n<p>נִיצוֹץ אִיהוּ חַיָּה תְּחוֹת רָקִיעַ, הֲדָא הוּא דִכְתִיב (יחזקאל א כב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ, רָקִיעַ וַדַּאי עַל רֵישָׁא דְחַיָּה, אִיהוּ קָמֵ\"ץ, נִיצוּץ חַיָּה, רָקִיעַ לְעִילָא מִינָהּ, נִיצוֹץ אִיהוּ י' סָלִיק בְּאָת ו' דְּאִיהוּ רָקִיעַ, שִׁית זִמְנִין עִִשֶׂר וְאִתְעֲבִידַת ס, וּבָהּ (תהלים קמה יד) סוֹמֵךְ יהו\"ה לְכָל הַנּוֹפְלִים, וְחַיָּה אִיהוּ סָמַךְ (נ\"א איהי י' סמוך) לָרָקִיעַ.</p>\n<p>רָקִיעַ עִם נִיצוֹץ אִיהוּ גִלְגּוּל, רָקִיעַ בְּלָא נִיצוֹץ אִיהוּ גַלְגַּל, כְּמָה דְאוּקְמוּהוּ גַלְגַּל הוּא שֶׁחוֹזֵר בָּעוֹלָם, דְּאַחֲזִיר לְעָלְמָא, וְדָא פַתָח, וְלָא אִית לֵיהּ הַרְכָּבָה בְגִלְגּוּל, דְּלֵית לֵיהּ חַיָּה דְרָכִיב עֲלָהּ, וְדָא שַׁרְבִיט הַכֹּכָב, דְּאִתְּמַר בֵּיהּ (במדבר כד יז) דָּרַךְ כֹּכָב מִיַּעֲקֹב, דָּרַךְ בֵּין שְׁתֵּי חַיּוֹת דְּאִינוּן צֵרִ\"י, וְאִתְעֲבִיד וַיִּיצֶר, וּבְהוֹן קָא אַתְיָא בִּתְרֵין גִּלְגּוּלִין, וְדָא אָדָם דִּיְצִירָה, דְּקָמֵ\"ץ אִיהוּ אָדָם דִּבְּרִיאָה, וְכַד אָתָא בִתְלַת גִּלְגּוּלִין דְּאִינוּן סֶגוֹ\"ל, אִתְעֲבִיד שַׁלְשֶׁלֶ\"ת מְשׁוּלָשׁ בְּהוֹן, וְדָא אָדָם דַּעֲשִׂיָּה.</p>\n<p>וְהָכִי אִיהוּ שַׁרְבִיט דְּכֹכָב, כַּד אִיהוּ עוֹבֵר בֵּין שְׁתֵּי אוֹפַנִּים דְּאִינוּן שְׁבָ\"א, אִתְעֲבִיד שׁוּרֻ\"ק, דַּרְגָּ\"א, וְאִינוּן שַׁלְשֶׁלֶ\"ת לְעִילָא, בְסֶגוֹ\"ל, בְּסֶגוֹלְתָּ\"א, דַּרְגָּ\"א לְתַתָּא בְשׁוּרֻ\"ק, שְׁבָ\"א צֵרִ\"י, חֹלֵ\"ם כַּד אִסְתַּלִּיק בְּצֵרִ\"י אִתְעֲבִיד סֶגוֹלְתָּ\"א, חִרֵ\"ק דְּנָחֲתָא בְצֵרִ\"י אִתְעֲבִיד סֶגוֹ\"ל, וְכַד עָאל בִּשְׁבָ\"א אִתְעֲבִיד שֻׁרֵ\"ק, וְכֹלָּא נְקֻדָּה חֲדָא, חֹלֵ\"ם אִיהוּ לְעִילָא בְּסֶגוֹלְתָּ\"א, חִרֵ\"ק אִיהוּ לְתַתָּא בְּסֶגוֹ\"ל, שׁוּרֻק אִיהוּ בְּאֶמְצָעִיתָא כְּגַוְונָא דָא וּ, הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר (איוב לב כט).</p>\n<p>אַחֲזֵי גִלְגּוּלָא קַדְמָאָה יֹהוֹֹ\"הֹ, אַחֲזֵי גִלְגּוּלָא תִנְיָנָא יִהִוִ\"הִ (נ\"א וי\"ה וי\"ה), אַחֲזֵי גִלְגּוּלָא תְלִיתָאָה יוּ הוּ ווּ הוּ, (נ\"א אתגליא ואחזי גלגולא קדמאה יהו\"ה גלגולא תנינא תלת י' י' י'), הַרְכָּבָה דְכֻלְּהוּ תְּלַת אדנ\"י, וְרָזָא דָא י' י' י', חֹלֵ\"ם חִרֵ\"ק שׁוּרֻ\"ק, תְּלַת יוּדִי\"ן, אָמוֹן מוּפְלָא אָמוֹן נִסְתָּר אָמוֹן מְכוּסֶה, דְּאִתְרְמִיזוּ בְּהַאי שְׁמָא יו\"ד ה\"י וא\"ו ה\"י, אָמוֹן מוּפְלָא דְאִשְׁתְּמוֹדָע בְּכֻלְּהוּ, חַד שַׁרְיָא בְּנֶפֶשׁ הַזִּכָּרוֹן, וְתִנְיָנָא בְּנֶפֶשׁ הַמַּחֲשָׁבָה, וּתְלִיתָאָה בְּנֶפֶשׁ הַמְּצוּיָיר, דְּאִינוּן תְּלַת מוֹחִין י' י' י', רִיהֲטָא</p>"],[9500011252,"<p>דְסָחִיר לוֹן כְּגַוְונָא דָא אִיהִי קַרְקַפְתָּא דִתְּפִלִּין, שִׁרְטוּטִין כְּגַוְונָא דָא יַהָוָ\"הַ, יהו\"ה בְּהוֹן מֶלֶךְ הָא הָכָא שִׁרְטוּטִין דְּמִצְחָא. עַיְינִין, בְּהוֹן וְאַתָּה תֶחזֶה מִכָּל הָעָם, אַנְשֵׁי חַיִל בְּגַוָּון חִוָּור יִרְאֵי אלהי\"ם בְּגַוָּון סוּמַק, אַנְשֵׁי אֱמֶת בְּגַוָּון יָרוֹק, שׂוֹנְאֵי בָצַע בְּבַת עַיִן דְּאִיהִי אוּכְמָא, וְדָא רָזָא דְשַׁבָּת, ש תְּלַת עַנְפֵי תְּלַת גַּוָּונִין דְּעִינָא, בַּ\"ת דְּשַׁבָּת דָּא בַת עַיִן, וַעֲלַיְיהוּ אִתְּמַר (שמות לא טז) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת וְגוֹמֵר, וְהָא אוּקְמוּהוּ דְאִינוּן תְּרֵין שַׁבָּתוֹת, אִימָּא עִלָּאָה בִּתְלַת דַּרְגִּין, וְאִימָּא תַּתָּאָה בִּתְלַת דַּרְגִּין, עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל שִׁית סִטְרִין דְּאִינוּן שִׁית דַּרְגִּין, עַיְינִין דְּמִסְתַּכְּלִין בְּאֹרַח מֵישַׁר בְּחִוְורוּ, אִלֵּין אִינוּן עַיְינִין דִּרְחִימוּ, וּבְהוֹן שְׁכִינְתָּא אִיהִי יָפָה כַּלְּבָנָה דְּלֵית בָּהּ פְּגִימוּ, דְאִתְּמַר בָּהּ (שיר א טו) הִנָּךְ יָפָה רַעִִיָתִי הִנָּךְ יָפָה עִינַיִךְ יוֹנִים.</p>\n<p>וְאִית עַיְינִין דְּהַהוּא חִוְיָא אִיהוּ כָּרוּךְ בְּהוֹן, נָחָשׁ הַקַּדְמוֹנִי, וְלַאו מִסְתַּכְּלִין בְּאֹרַח מֵישַׁר, בְּכָל מַה דְּאִסְתַּכַּל אִתְלַטְיָא. עִינָא אִיהוּ כְּגַלְגַּל, גַּוָּון חִוָּור כְּגַוְונָא דְיַמָּא דְאַסְחַר כָּל עָלְמָא, וְתִנְיָינָא כְּגַוְונָא דְאַרְעָא, תְּלִיתָאָה כְּגַוְונָא דְאַרְעָא דְיִשְׂרָאֵל, נְקוּדָה זְעִירָא דְבַת עַיִן אִיהִי כְּגַוְונָא דְצִיּוֹן, דְּאִיהִי נְקוּדָה דְעָלְמָא דְמִתַּמָּן הוּשָׁתַת עָלְמָא.</p>\n<p>וְאִית בַּר נַשׁ דְּגַוָּון דִּילֵיהּ תְּכֵלֶת דְּאִיהוּ דוֹמֶה לְרָקִיעַ, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין תְּכֵלֶת דּוֹמֶה לְיָם, וְיָם דּוֹמֶה לְרָקִיעַ, וְרָקִיעַ דּוֹמֶה לַכִּסֵּא הַכָּבוֹד. וּתְלַת גַּוָּונִין אִינוּן בְּעִינָא חִוָּור אוּכַם תְּכֵלֶת, לָקֳבֵל אֵשׁ דְּלַאו אִיהוּ שׂוֹרֵף, וְאֵשׁ דְּאִיהוּ שׂוֹרֵף וְלָא אָכִיל, תְּלִיתָאָה דְאִיהוּ תְכֵלֶת לָקֳבֵל אֵשׁ דְּאִיהוּ שׂוֹרֵף וְאָכִיל, רְבִיעָאָה לַבַּת אֵשׁ וְדָא שְׁכִינְתָּא בַת עַיִן, וַעֲלָהּ אִתְּמַר (שמות ג ב) וַיֵּרָא מַלְאַךְ יהו\"ה אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה דָּא בַת עַיִן, וַיַּרְא וְהִנֵּה הַסְּנֶה בּוֹעִר בָּאֵשׁ דָּא גַוָּון דְּעַל בַּת עַיִן דְּאִיהוּ גַוָּון תִּנְיָינָא, וְהַסְּנֶה אֵינֶנּוּ אֻכָּל גַּוָּון תְּלִיתָאָה, וַיֹּאמֶר מֹשֶׁה אָסֻרָה נָּא וְאֶרְאֶה וְגוֹמֵר (שם ג) גַּוָּון חִוָּור דִּשְׁרַגָּא עִלָּאָה, וּבִתְלַת גַּוָּונִין אִלֵּין אִתְאָחֳדַת (נ\"א אתחברת) בַּת עַיִן דְּאִיהִי שְׁכִינְתָּא,</p>\n<p>וּבְהוֹן סָלְקָא בִתְלַת צְלוֹתִין קֳדָם יהו\"ה, הֲדָא הוּא דִכְתִיב (ויקרא ו ב) זֹאת תּוֹרַת הָעוֹלָה וְגוֹמֵר, זֹאת תּוֹרַת דָּא בַת עַיִן שְׁכִינְתָּא דְסָלְקָא בִתְלַת אֲבָהָן דְּתַקִּינוּ תְּלַת צְלוֹתִין, וּבְגִין דָּא זֹאת תּוֹרַת הָעוֹלָה וְגוֹמֵר, זֹאת תּוֹרַת הָעוֹלָה בִּימִינָא דְאִיהוּ אֵשׁ דְּלָא שׂוֹרֵף, דְּתַמָּן חָכְמָה דְאִיהוּ מַבּוּעָא דְמַיָּא, דְאִתְּמַר בֵּיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, דְּתָשַׁשׁ חֵילָא דְאֶשָּׁא, דְּאִיהוּ גַוָּון חִוָּור דִּשְׁרַגָּא דְלָא יְהֵא שׂוֹרֵף, וּנְקוּדָה דִילָהּ קָמֵ\"ץ, דְּאִתְּמַר בֵּיהּ וְקָמַץ הַכֹּהֵן (ויקרא ה יב), וְכַהֲנָא אִיהוּ לִימִינָא, קָמֵ\"ץ נְקוּדָה דְאָת י' מִסִּטְרָא דִימִינָא לָא אִתְחַיַּיב נְקוּדָה אָחֳרָא.</p>\n<p>הִיא הָעוֹלָה גַּוָּון תִּנְיָנָא דְאִתְאֲחִיד בִּצְלוֹתָא דְמִנְחָה, בֵּיהּ סָלְקָא בְרַתָּא לְגַבֵּי שְׂמָאלָא דְתַמָּן ה' עִלָּאָה, וּבָהּ הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, וּבְגִין דְּאִתְּתָא מִתַּמָּן, אָמְרוּ מָארֵי מַתְנִיתִין אוֹקִירוּ נְשַׁיְיכוּ כִּי הֵיכִי דְתִתְעַתְרוּן, בְּגִין דְּמִצָּפוֹן אִינוּן, (איוב לז כב) וּמִצָּפוֹן זָהָב יֶאֱתֶה, וּנְקוּדָה דְאִיהוּ מְחַיְּיבָא לְאָת ה' מִסִּטְרָא דִשְׂמָאלָא שְׁבָ\"א, וַעֲלֵיהּ אִתְּמַר (ישעיה סו טז) כִּי בָאֵ\"שׁ יהו\"ה נִשְׁפָּט, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה עַד הַבֹּקֶר (ויקרא ו ב) דָּא גַוָּון תְּכֵלֶת, דְּאִיהוּ אֲחִיד בִּצְלוֹתָא דְעַרְבִית, וּבֵיהּ סָלְקָא שְׁכִינְתָּא לְגַבֵּי עַמּוּדָא דְאֶמְצָעִיתָא, וּצְלוֹתָא דְעַרְבִית לָקֳבֵל אֵמוּרִין וּפְדָרִין דְּמִתְאַכְלִין כָּל הַלַּיְלָה, וּבְגִין דָּא תְּכֵלֶת דּוֹמֶה לָרָקִיעַ, דְּאִתְּמַר (בראשית א ו) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, דְּאַפְרִישׁ מַחֲלוֹקֶת בֵּין יְמִינָא וּשְׂמָאלָא, וּנְקוּדָה דְרָקִיעַ חֹלֵ\"ם, וּמָאן רָקִיעַ דָּא ו' דְּאִיהוּ כְגַוְונָא דָא [ציור] רָקִיעַ, וְהַהוּא נִיצוֹץ חֹלֵ\"ם עֲלֵיהּ, וְהַאי נְקוּדָה אִיהִי מְחַיְּיבַת לְאָת ו', וְרָזָא דִנְקוּדָה יָהוְה, וְרָזָא דְמִלָּה רַק בַּאֲבוֹתֶיךָ חָשַׁ\"ק יהו\"ה, (דברים י טו) כִּי בִי חָשַׁ\"ק וַאֲפַלְּטֵהוּ (תהלים צד יד), כִּ\"י בִ\"י רָזָא דִשְׁמָא דְאַרְבְּעִין וּתְרֵין, כִּ\"י בִ\"י יִרְבּוּ יָמֶיךָ וְגוֹמֵר (משלי ט יא).</p>\n<p>וְאִית מָאן דְּאִיהוּ מְפָרֵשׁ אִלֵּין</p>"],[9500011253,"<p>תְּלַת גַּוָּונִין בִּרְקִיעָא, דְּאִינוּן חִוָּור וְאוּכַם וּתְכֵלֶת, חַד חִוָּור לְעִילָא מִן שְׁרַגָּא, וְחַד תְּכֵלֶת לְתַתָּא, אוּכַם בְּאֶמְצָעִיתָא אַפְרִישׁ בְּתַרְוַיְיהוּ, וְלָא אִשְׁתְּמוֹדְעוּ בְּקַדְרוּתָא דִילֵיהּ, וְרָזָא דָא מָארֵי מַתְנִיתִין אוּקְמוּהוּ כְּגַוְונָא דָא, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית, כְּדֵי שֶׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן, מִיָּד דְּאִתְעַבַּר קִדְרוּתָא דִשְׁמַיָּא, דְאִתְּמַר בָּהּ (ישעיה נ ג) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, מִיָּד נָהִיר שְׁמַיָּא וְאִשְׁתְּמוֹדָע אִיהוּ בֵּין תְּכֵלֶת לְלָבָן, וְאִשְׁתְּמוֹדָע הָכָא תְּכֵלֶת מִסִּטְרָא דִשְׂמָאלָא, לָבָן מִסִּטְרָא דִיְמִינָא, עַמּוּדָא דְאֶמְצָעִיתָא אֲחִיד בְּתַרְוַיְיהוּ, וּבֵיהּ קוֹרִין קְרִיאַת שְׁמַע בְּשַׁחֲרִית, דְּאִיהִי שְׁכִינְתָּא בַת עַיִן.</p>\n<p>וְהָכִי קְרִיאַת שְׁמַע דְּעַרְבִית צְרִיכִין לְיַיחֲדָא לָהּ בְּעַמּוּדָא דְאֶמְצָעִיתָא, כְּמָה דְתַקִּינוּ מָארֵי מַתְנִיתִין, לִקְרוֹת קְרִיאַת שְׁמַע בַּכֹּכָבִים דְּאִינוּן בֵּינוּנִים (כנויים), דְּהָכִי אוּקְמוּהוּ, לֹא מִן הַכֹּכָבִים הַנִּרְאִים בַּיּוֹם, וְלֹא מִן הַכֹּכָבִים הַנִּרְאִים בַּלַּיְלָה, אֶלָּא מִן הַבֵּינוּנִים, דְּאִינוּן מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, הָא הָכָא תְּלַת גַּוָּונִין בִּשְׁרַגָּא, שְׁכִינְתָּא נֵר דְּאִתְאָחֳדַת בְּהוֹן, (משלי ו כג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר, אוֹר דָּא אוֹרַיְיתָא דְבִכְתָב, דְּאִיהִי נִשְׁמַת אָדָם, דִּנְהִירַת עַל נֵר, עַל תַּרְוַיְיהוּ אִתְּמַר, (בראשית א טז) אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם, וְאֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה.</p>\n<p>גַּוָּון חִוָּור בֵּיהּ אֵ\"ל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים וּמִתְנַהֵג בַּחֲסִידוּת, גַּוָּון תְּכֵלֶת כָּרְסַיָּא דְּדִין, דְּאִינוּן אִימָּא עִלָּאָה אִימָּא תַּתָּאָה, אהי\"ה אדנ\"י, מֶלֶךְ דַּאֲחִיד בְּתַרְוַיְיהוּ יהו\"ה יהו\"ה, עֲלֵיהּ אִתְּמַר (משלי ל ד) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע, וְאִינוּן חָכְמָה וְעַמּוּדָא דְאֶמְצָעִיתָא, מִסִּטְרָא דְּדִין אָמַר קוּדְשָׁא בְּרִיךְ הוּא אֲנִי אָמִית (דברים לב לט), וּמִסִּטְרָא דְכָרְסַיָּא דְרַחֲמֵי אָמַר קוּדְשָׁא בְּרִיךְ הוּא וַאֲחַיֶּה, וּבְגִין דָּא תַּלְמִידֵי חֲכָמִים כַּד הֲווֹ מִסְתַּכְּלִין בְּגַוָּון תְּכֵלֶת דְּעִינָא הֲווֹ מַעֲנִישִׁין בֵּיהּ, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, בְּכָל מָקוֹם שֶׁנָּתְנוּ חֲכָמִים עִינֵיהֶם אוֹ מִיתָה אוֹ עוֹנִי.</p>\n<p>דִּבְגַוָּון חִוָּור מִתְלַבַּשׁ אֵ\"ל מִן מִיכָאֵ\"ל שַׂר הַחֶסֶד, וּתְחוֹתֵיהּ נָחָשׁ, וּפוֹרֵץ גָּדֵר יִשְּׁכֶנּוּ נָחָשׁ, בְּגַוָּון סוּמַק אִתְלַבַּשׁ גַּבְרִיאֵ\"ל שַׂר הַגְּבוּרָה, וּתְחוֹתֵיהּ שָׂרָף, בְּגַוָּון יָרוֹק אִתְלַבַּשׁ אוּרִיאֵ\"ל נוּרִיאֵ\"ל שַׂר שָׁלוֹם, וּתְחוֹתֵיהּ עַקְרָב, בְּגַוָּון אוּכַם אִתְלַבַּשׁ רְפָאֵ\"ל שַׂר דִּשְׁכִינְתָּא, וּתְחוֹתֵיהּ צִמָּאוֹן.</p>\n<p>וּבְכָל אֲתַר דַּהֲווֹ מִסְתַּכְּלִין בְּגַוָּון חִוָּור הֲווֹ מְחַיֵּי, וּבְזִמְנָא דְאִסְתַּלַּק יהו\"ה מִכָּרְסַיָּא דְּדִין וּמִכָּרְסַיָּא דְרַחֲמֵי, לֵית תַּמָּן עוֹנְשָׁא וְלָא אַגְרָא, וּבְגִין דְיהו\"ה אִסְתַּלַּק בְּמַזָּלָא קַדִּישָׁא עִלָּאָה דְאִיהוּ כֶּתֶר עִלָּאָה, בְּהַהוּא זִמְנָא בָּנֵי חַיֵּי וּמְזוֹנֵי לַאו בִּזְכוּתָא תַלְיָא מִלְתָא, אֶלָּא בְּמַזָּלָא תַלְיָא מִלְתָא, וּבְהַהוּא זִמְנָא הַכֹּל תָּלוּי בְּמַזָּל וַאֲפִילוּ סֵפֶר תּוֹרָה בְּהֵיכָל, מַה דַּהֲוָה קָרוֹב יהו\"ה לְכָל קוֹרְאָיו, בְּהַהוּא זִמְנָא אִתְּמַר בֵּיהּ (קהלת ז כד) רָחוֹק מַה שֶּׁהָיָה, וְעָמֹק עָמֹק מִי יִמְצָאֶנּוּ, לֵית מָאן דְּאַשִּׂיג לֵיהּ אֶלָּא בְחָכְמָה וּבְבִינָה, וּבְגִין דָּא כַד אִסְתַּלַּק לְהַהוּא אֲתַר לָא מַשִּׂיגִין לֵיהּ בְּכָל סְפִירָן, אֶלָּא בַחָכְמָה וּבְבִינָה, דְאִינוּן י\"ם י' חָכְמָה מ' בִּינָה, וּבְגִין דָּא רָחוֹק מַה שֶּׁהָיָה, וְעָמֹק עָמֹק מִ\"י יִמְצָאֶנּוּ, וְרָזָא דְמִלָּה (מלכים א ה כט) קְרוֹבִים אֶל יהו\"ה אלהינ\"ו.</p>\n<p>וְכַד אִסְתַּכַּל דָּוִד בְּרוּחָא דְקוּדְשָׁא, וְחָזָא דְאִסְתַּלַּק לְאַיִ\"ן בְּגָלוּתָא בַּתְרָאָה, אָמַר עֲלַיְיהוּ (תהלים קכד א) אֶשָּׂא עִינַי אֶל הֶהָרִים מֵאַיִן יָבֹא עִִזְרִי, אַיִ\"ן א' כֶּתֶר עִלָּאָה י' חָכְמָה ן' בִּינָה, חָזָא דְלָא הֲווֹ מַשִּׂיגִין לֵיהּ, אֶלָּא בִּתְלַת צְלוֹתִין דְּתַקִּינוּ אֲבָהָן, דְּאִתְקְרִיאוּ הָרֵי יהו\"ה, אָמַר עֲלַיְיהוּ אֶשָּׂא עִינַי אֶל הֶהָרִים מֵאַיִן יָבֹא עִִזְרִי, עִִזְרִי מֵעִם יהו\"ה, דָּא מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים, וְכִסֵּא דִין אִסְתַּלַּק מִתַּמָּן, וְדָא יהו\"ה דְּאִיהוּ מִלְּגָאו דְּכָל סְפִירָה וּסְפִירָה, עֲלֵיהּ אִתְּמַר (ד\"ה א כט) לְךָ יהו\"ה הַגְּדוּלָה וְהַגְּבוּרָה וְגוֹמֵר, בַּעֲשַׂר סְפִירָן שַׁבַּח לֵיהּ דָּוִד, בְּגִין דְּאִיהוּ לְגוֹ מִכֻּלְּהוּ, וְאִיהוּ מִלְּבָר דְּכָל סְפִירָה וּסְפִירָה, וְאִיהוּ בֵּין כָּל סְפִירָה וּסְפִירָה, לָא אִשְׁתַּנִּי בְּכָל אֲתַר.</p>\n<p>אִית עַיְינִין מִכַּמָּה גַוָּונִין, כְּגוֹן אַרְגָּמָ\"ן רְגָמָ\"ן, ר' רְפָאֵ\"ל, ג' גַּבְרִיאֵ\"ל, מ' מִיכָאֵ\"ל, ן' נוריא\"ל, וְרָזָא דְמִלָּה מֶרְכָּבוֹ אַרְגָּמָ\"ן (שיר ה ו), א' אוֹר דְּנָהִיר בְּאִלֵּין אַרְבַּע גַּוָּונִין, א' אורפניא\"ל וְאִיהוּ</p>"],[9500011254,"<p>מטטרו\"ן, אוֹר פְּנִיאֵ\"ל, וּבְגִין דָּא אִתְקְרֵי שַׂר הַפָּנִים, וְאִיהוּ רזיא\"ל וְאִיהוּ אוּרִיאֵ\"ל, דְּהָכִי סָלִיק לְחֻשְׁבַּן רזיא\"ל, וְאִיהוּ סָלִיק לְחֻשְׁבַּן רְמַ\"ח פִּקּוּדִין דְּאוֹרַיְיתָא, כְּחֻשְׁבַּן אַבְרָהָ\"ם, וְדָא מַלְאַךְ הַחֶסֶד, דְּמִתַּמָּן, אוֹרַיְיתָא אִתְיְיהִיבַת, הֲדָא הוּא דִכְתִיב (דברים לג ב) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וְאִיהוּ מְמוּנֶה עַל רָזֵי אוֹרַיְיתָא, וְהוּא גָּלֵי עֲמִיקָתָא וּמְסַתְּרָתָא, יָדַע מָה בַחֲשׁוֹכָא, בְּגִין דְּחֹשֶׁךְ אִיהוּ לְבוּשָׁא דְאוֹר, וּבֵיהּ אֵלִ\"י דְאִתְּמַר בֵּיהּ (שמות טו ב) זֶה אֵלִ\"י וְאַנְוִהוּ, אוֹר הוּא רָ\"ז, וְכָל מָאן דְּיָדַע בְּהוּ עֲלֵיהּ אִתְּמַר (דניאל ד ו) וְכָל רָז לָא אָנֵיס לָךְ, וְאִיהוּ נָהִיר בְּגַוָּון חִוָּור דְּעִינָא, וְאִיהוּ נוריא\"ל נוּר דָּלֵיק מִסִּטְרָא דִשְׂמָאלָא, דְתַמָּן רי\"ו גְבוּרָה, וּמִתַּמָּן פִּקּוּדִין דְּלֹא תַעֲשֶׂה, כָּרְסַיָּא דְרַחֲמֵי לִימִינָא כָּרְסַיָּא דְּדִינָא לִשְׂמָאלָא, עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ וּבֵיהּ יהו\"ה, דְּכָפַל שְׁמֵיהּ תְּרֵין זִמְנִין יהו\"ה יהו\"ה, וּמֹשֶׁה דְאִתְאֲחִיד בֵּיהּ כָּפַל שְׁמֵיהּ מֹשֶׁה מֹשֶׁה, וּבְגִין דָּא וָאֵדָעֲךָ בְּ שֵׁ\"ם (שמות לג יז) בִּתְרֵין שְׁמָהָן.</p>\n<p>עַיְינִין מְרַקְּמָן נְקִידִין בִּנְקוּדִין חִוְורִין, כְּגוֹן נְקוּדִין דְּעַל לוּלֵ\"א, אִסְתַּמַּר מִנֵּיהּ רַמַּאי אִיהוּ, וּמַאי דְּאִיהוּ בִּנְקוּדִין סוּמְקִין אוֹשִׁיד דְּמָא אִיהוּ, בִּנְקוּדִין יְרוֹקִין כַּעֲסָן אִיהוּ מִסִּטְרָא דְמָרָה, בִּנְקוּדִין אוּכְמִין גַּזְלָן אִיהוּ גַּנָּב, כָּל בִּישִׁין דְּעָלְמָא אִית בֵּיהּ, עַיְינִין עֲמִיקִין אִית בְּהוֹן עוֹמֶק טוֹב וְעוֹמֶק רָע, הַאי לָא יָדַע בַּר נַשׁ לִבֵּיהּ, לִבֵּיהּ עָמוֹק עָמוֹק מִי יִמְצָאֶנּוּ, אִם הוּא עוֹמֶק טוֹב לָא יָכִיל בַּר נַשׁ לְמִנְדַּע חָכְמָתֵיהּ, וְאִם הוּא עַם הָאָרֶץ כַּמָּה עֲמוּקִין מַחֲשַׁבְתִּין דִּילֵיהּ בִּישִׁין, הַאי אִיהוּ קֶבֶר פָּתוּחַ, הֲדָא הוּא דִכְתִיב (תהלים ה י) קֶבֶר פָּתוּחַ גְּרוֹנָם וכו', לְשׁוֹנָם עָמָל וָאָוְן, אִסְתַּמַּר מֵעִינָא דָא, בְּכָל מַה דְּאִסְתַּכַּל אִתְלַטְיָא, אִיהוּ מִסְתַּכַּל לְתַתָּא לְמֶחְשַׁב כָּל מַחֲשָׁבִין בִּישִׁין, לֵית סוֹפָא לְרַשִּׁיעוּתֵיהּ.</p>\n<p>עַיְינִין גַּבְהָנִין בְּהִפּוּכָא, עֲלַיְיהוּ אִתְּמַר (יחזקאל א יח) וְגַבֵּיהֶן וְגֹבַהּ לָהֶם וְיִרְאָה לָהֶם, וְגַבּוֹתָם מְלֵאוֹת עִינַיִם וְגוֹמֵר, כְּמָה דְעַיְינִין עֲמִיקִין אִינוּן דִּינָא וּמוֹתָא, הָכִי עַיְינִין גַּבְהָנִין אִינוּן חַיֵּי וְרַחֲמֵי, וְאִית עַיְינִין גַּבְהָנִין מִסִּטְרָא דְהַהוּא דְאִתְּמַר בֵּיהּ (שמות טו א) כִּי גָאֹה גָּאָה, סוּס וְרֹכְבוֹ רָמָה בַיָּם, וְאִית מִנְּהוֹן דְּאִתְחַזְיָין גַּבֵּיהּ (נ\"א דאיחזיין על גבי) רוּחָא, וְאָחֳרָנִין דְּאִתְקְרִיאוּ גְאוֹנִים בְּאוֹרַיְיתָא, וְכֻלְּהוּ אִית לוֹן עִקָּרָא לְעִילָא, וּבְגִין דָּא וְגַבֵּיהֶן וְגֹבַהּ לָהֶם וְיִרְאָה לָהֶם, מִסִּטְרָא דְהַהוּא דְאִתְּמַר בֵּיהּ (קהלת ה ז) כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר, וְדָא מֶרְכָּבָה לְעִילָא מִן מֶרְכָּבָה, וּגְבֹהִים עֲלֵיהֶם, הֲדָא הוּא דִכְתִיב (ישעיה כב א) מַשָּׂא גֵּיא חִזָּיוֹן מַה לָּךְ אֵיפֹה כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת, וְאִלֵּין אִינוּן דְּרָכְבִין עַל מֶרְכָּבוֹת.</p>\n<p>וְעוֹד וְגַבֵּיהֶן אִלֵּין אִינוּן אוֹפַנִּים, דְּאִינוּן כְּגַוְונָא דְאַתְוָון, וְגֹבַהּ לָהֶם אִלֵּין אִינוּן שְׂרָפִים דְּאִינוּן לָקֳבֵל טַעֲמֵי דִלְעִילָא, כִּתְרִין עַל אַתְוָון, וְגַבּוֹתָם מְלֵאוֹת עִינַיִם אִלֵּין נְקוּדִין, דְּאַתְוָון מְלֵאוֹת עִינַיִם מִנַּיְיהוּ, כְּמָה דְאַתְּ אָמַר (זכריה ד י) עִינֵי יהו\"ה הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ, מַאי לְאַרְבַּעִִתָּם, אִלֵּין תְּלַת חֵיוָון, אִינוּן דְּאִתְקְרִיאוּ בִשְׁמָא דְיהו\"ה, תְּלַת זִמְנִין כְּגַוְונָא דָא יהו\"ה יהו\"ה יהו\"ה, אִלֵּין אִינוּן אַרְבַּע אַנְפִּין לְכָל סְטַר לְכָל חַיָּה, וְגַבּוֹתָם מְלֵאוֹת עִינַיִם כְּגַוְונָא דָא [ציור] הָא הָכָא שִׁבְעִים וּתְרֵין עַיְינִין דְּאִינוּן לָקֳבֵל שִׁבְעִים סַנְהֶדְרִין, וּמֹשֶׁה וְאַהֲרֹן עַל גַּבֵּיהוֹן, אִלֵּין אִינוּן וְגַבֵּיהֶן וְגֹבַהּ לָהֶם.</p>"],[9500011255,"<p>כְּגַוְונָא דָא [ציור] הָא הָכָא חָמֵשׁ וְאַרְבְּעִין עַיְינִין כְּחֻשְׁבַּן אָדָם וְאִינוּן יה\"ו הו\"י וה\"י. וְעוֹד וְגַבֵּיהֶן דָּא שְׁכִינְתָּא דְאִיהִי עַל גַּבֵּי חֵיוָון וּמַשִּׁרְיָין כֻּלְּהוּ, הֲדָא הוּא דִכְתִיב (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, וְגֹבַהּ לָהֶם דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דִּשְׁכִינְתָּא אִיהִי עַל גַּבֵּי אוֹפַנִּים, וְעַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ כְּלִיל שִׁית סְפִירָן עַל גַּבֵּי חֵיוָון, דְּאִיהוּ כָּלִיל לוֹן מטטרו\"ן, וְדָא אִיהוּ כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבוֹהִים עֲלֵיהֶם (קהלת ה ז), אִלֵּין אִינוּן אַבָּא וְאִימָּא, כִּתְרָא עַל רָאשֵׁהוֹן, דְּאִינוּן עַל גַּבֵּי שְׂרָפִים דְּתַלְיָין מִכָּרְסַיָּא.</p>\n<p>וְעוֹד וְגַבֵּיהֶן דָּא אִימָּא עִלָּאָה, דְאִיהִי עַל גַּבֵּי סְפִירָן דְּאִינוּן תְּחוֹתָהּ, דְּמִינָהּ כָּל אַתְוָון, וְגֹבַהּ לָהֶם דָּא חָכְמָה, דְמִתַּמָּן נְקוּדִין, וְיִרְאָה לָהֶם דָּא כִּתְרָא דְתַמָּן טַעֲמֵי, וְגַבּוֹתָם מְלֵאוֹת עִינַיִם, אִינוּן אוֹר צַח אוֹר מְצוּחְצָח אוֹר קַדְמוֹן, וְכַמָּה נְהוֹרִין דְּתַלְיָין מִנַּיְיהוּ דְנָהֲרִין מִלְּגָאו, כְּנִשְׁמָתָא בְגוּפָא.</p>\n<p>וְעוֹד וְגַבֵּיהֶן אִלֵּין אִינוּן שִׁבְעָה גִלְדֵּי עִינָא, דְאִינוּן דָּא עַל גַּב דָּא כְּגִלְדֵּי בְצָלִים, וְגֹבַהּ לָהֶם דָא עִינָא דְאִיהוּ כְּלִיל כָּל גַּוָּונִין, וְגַבּוֹתָם מְלֵאוֹת עִינַיִם אִלֵּין כַּנְפֵי עִינָא וְעַפְעַפֵּי וּכְרוּבֵי עִינָא, דְּאַרְבַּע גַּוָּונִין אִית בְּעִינָא לָקֳבֵל אַרְבַּע אַנְפִּין דְּכָל חַיָּה, וּתְרֵין כַּנְפֵי עִינָא דְאִינוּן עַפְעַפַּיִם, וּתְרֵי כְּרוּבֵי עִינָא, אִינוּן לָקֳבֵל אַרְבַּע גַּדְפִין דְּכָל חַיָּה, וּבְאִלֵּין אַרְבַּע גַּוָּונִין דְּעִינָא נָהֲרִין אַרְבַּע אַתְוָון יהו\"ה, וּבְאַרְבַּע כַּנְפֵי עִינָא נָהִיר אדנ\"י, דָּא אִיהוּ כִּי גָּבוֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר, וּגְבֹהִים עֲלֵיהֶם (שם) אִלֵּין אִינוּן יהו\"ה אהי\"ה אַבָּא וְאִימָּא.</p>\n<p>וְעוֹד עַיְינִין גְּבוֹהִין מִסִּטְרָא דִימִינָא, וְעַיְינִין עֲמִיקִין מִסִּטְרָא דִשְׂמָאלָא, דָּא עָנָו וְדָא בַיְישָׁן, מִסִּטְרָא אָחֳרָא דָא גַס רוּחַ וְדָא עַז פָּנִים, כְּרוּבֵי עִינָא וְעַפְעַפֵּי עִינָא עֲלַיְיהוּ אִתְּמַר (שמות כה כ) וְהָיוּ הַכְּרוּבִים פּוֹרְשֵׂי כְנָפַיִם לְמַעִִלָה, סוֹכְכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת, דָּא כַּפּוּרְתָּא דְעִינָא, תְּלַת גַּוָּונִין דְּעִינָא אִינוּן אהי\"ה יהו\"ה אדנ\"י, כְּלָל וּפְרָט וּכְלָל, וְאִינוּן יִחוּדָא בְּרָכָה קְדוּשָׁה, וְסִימָן יַ עֲנֵנוּ בְ יוֹם קָ רְאֵנוּ (תהלים כ י), דְּהָכִי סָלִיק חֻשְׁבַּן תְּלַת שְׁמָהָן אִלֵּין כְּחוּשְׁבַּן יב\"ק, אהי\"ה כֶּתֶר עִלָּאָה, יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, אדנ\"י שְׁכִינְתָּא תַּתָּאָה, אדנ\"י כְּלָל (נ\"א יהו\"ה), אהי\"ה פְּרָט, יהו\"ה (נ\"א אדנ\"י) וּכְלָל.</p>\n<p>וְעוֹד עִינָא כְּגַוְונָא דְגוּפָא, תְּרֵין כְּרוּבִין דִּילֵיהּ כְּגַוְונָא דִתְרֵין שׁוֹקִין, תְּרֵין עַפְעַפֵּי עִינָא לָקֳבֵל תְּרֵין דְּרוֹעִין, אִלֵּין מְסַכְּכִין וְאִלֵּין פָּרְחִין, וְאִית כְּרוּבֵי עִינָא רַבְרְבִין וְעִינָא זְעִירָא וְאִית כְּרוּבֵי עִינָא זְעִירִין וְעִינָא רַבְרְבָא, בְּגִין דָּא אָמַר לְאַהֲרֹן וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד (ויקרא ו ג), וְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, מַאי מִדּוֹ כְּמִדָּתוֹ, הָכִי צְרִיכִין לְבוּשֵׁי עִינָא דְאִינוּן כְּרוּבֵי עִינָא, דְאִינוּן דּוּ פַּרְצוּפִין כָּתְנוֹת עוֹר, דִּיְהוֹן כְּמִדָּה דְעִינָא.</p>\n<p>וּבְגִין דָּא (דברים כה יג) לֹא יִהְיֶה לְךָ בְּבֵיתְךָ אֶבֶן וָאָבֶן אֵיפָה וְאֵיפָה גְּדוֹלָה וּקְטַנָּה, דְּגוֹדָל אִיהוּ מִדָּה לְעַיְינִין לְחוֹטָמָא לְשִׂפְוָון לְאוּדְנִין לְפוּמָא, הַאי אִיהוּ מִדָּה דְכֹלָּא, וּבְגִין דָּא אָמַר קְרָא (שמות כו ב) מִדָּה אַחַת לְכָל הַיְרִיעוֹת, וְעַל כַּנְפֵי עִינָא אִתְּמַר (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לוֹהֵט, אִלֵּין אִינוּן גַּוְּונֵי עִינָא, וְלָקֳבֵל תְּרֵין כַּנְפֵי עִינָא אִינוּן תְּרֵין שִׂפְוָון דְּפָתְחִין וְסָגְרִין, וּלְקִבְלַיְיהוּ תְּרֵין כַּנְפֵי רֵיאָה, וְעִינָא לָקֳבֵל לִבָּא דְאִיהוּ אֵשׁ לוֹהֵט, וּבְכַנְפֵי רֵיאָה רוּחָא דְנָשֵׁיב בְּהוֹן, עֲלַיְיהוּ אִתְּמַר עוֹשֶׂה מַלְאָכָיו רוּחוֹת.</p>\n<p>וְכָל אֵבֶר וְאֵבֶר בָּרָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בַּמִּדָּה בַּמִּשְׁקָל, וְאִם תִּשְׁכַּח עַיְינִין חַד זְעִיר וְחַד רַבְרְבָא, לַאו אִיהוּ דָא בַּמִּשְׁקָל וּבְמִדָּה, שַׁקְרָן אִיהוּ, אִסְתַּמַּר מִינֵיהּ, אוֹ אִם עַיְינִין רַבְרְבִין וּפוּמָא זְעִירָא, וְחוֹטָמָא אֲרִיכָא וְאַנְפִּין זְעִירִין, (נ\"א עקימין) דְּלָא אָזְלִין כֻּלְּהוֹן בְּמִדָּה, עַיְינִין וְחוֹטָמָא וְאַנְפִּין וּפוּמָא, עַוְלָן אִיהוּ דָא, וּבְגִין דָּא לֹא תַעֲשׂוּ עָוְל בַּמִּשְׁפָּט בַּמִּדָּה וְגוֹמֵר (ויקרא יט לה), בַּמִּדָּה דָא מִדָּה דְשִׁיעוּר קוֹמָה.</p>"],[9500011256,"<p>דְכָל מָאן דְּלָא אִיהוּ בַּעַל מִדּוֹת, אַכְחִישׁ שִׁעוּר קוֹמָה דִלְעִילָא, וְלָא אִתְנְטִיל מִתַּמָּן, דַּעֲשַׂר סְפִירָן דִּלְעִילָא כֻּלְּהוּ אָזְלִין בַּמִּדָּה מִסִּטְרָא דְאָת י', וּבַמִּשְׁקָל מִסִּטְרָא דְאָת ו', תְּרֵי מֹאזְנֵי הַשֶּׁקֶל אִינוּן ה' ה', מִדָּה אַחַת.</p>\n<p>תָּא חֲזִי י' אִיהוּ רֵישָׁא, וְאִיהוּ מִדָּה דְעַיְינִין דְּאוּדְנִין דְּאַנְפִּין דִּתְרֵין נוּקְבִין דְּחוֹטָמָא, מִדָּה דְפוּמָא, שֶׁקֶל הַקֹּדֶשׁ דָּא ו', שֶׁקֶל דְּגוּפָא, כַּנְפֵי הַשֶּׁקֶל ה' אֶצְבְּעָן דִּימִינָא וְה' דִשְׂמָאלָא, וּבְגִין דִּשְׁמָא דְיהו\"ה אִיהוּ מִדָּה וְשִׁעוּר וּמִשְׁקָל, אָמַר קְרָא (ויקרא יט לה) לֹא תַעֲשׂוּ עָוְל בַּמִּשְׁפָּט בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה, וּכְגַוְונָא דָא לֹא יִהְיֶה לְךָ בְּכִיסְךָ אֶבֶן וָאָבֶן גְּדוֹלָה וּקְטַנָּה (דברים כה יג), מַאי כִּיס הָכָא דָא פוּמָא.</p>\n<p>אַדְהָכִי הָא סָבָא עִלָּאָה אִזְדַּמַּן לְגַבֵּיהּ, וְאָמַר וְהָא אִם עַיְינִין שְׁקִילִין הָא אִינוּן בַּמִּדָּה, אֲבָל אִם אִינוּן עַיְינִין רַבְרְבָן וְשִׂפְוָון זְעִירִין לָא אַכְחִישׁ מִדָּה, אֶלָּא אִם עַיְינִין דָּא רַב וְדָא קְצִר, דָּא עָב וְדָא כָּחוּשׁ, אוֹ אַנְפִּין דָּא אֲרִיךְ וְדָא קְצִר, דָּא עָב וְדָא כָּחוּשׁ, אֶלָּא בָּתַר דְּזִיווּגִין שְׁקִילִין כָּל חַד לְמִינֵיהּ, וַדַּאי לָא אַכְחִישׁ עוֹבָדָא דִבְּרֵאשִׁית.</p>\n<p>ב' בְּתוֹסֶפֶת, תְּרֵין כִּיסוֹת פִּימָא וְלִבָּא, דְּהָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין עֲלַיְיהוּ, מִי שֶׁאֵין תּוֹכוֹ כְּבַרוֹ אַל יִכָּנֵס לְבֵית הַמֶּדְרָשׁ, דְּוַדַּאי אִיהוּ מֵאִילָנָא דְטוֹב וָרָע, דְּאִיהוּ יֵימָא חַד בְּלֵב וְחַד בְּפֶה, מָאן דְּאִיהוּ מֵאִילָנָא דְחַיֵּי אִיהוּ תּוֹכוֹ כְּבַרוֹ, פִימָא וְלִבָּא שָׁוִים, וַעֲלַיְיהוּ אִתְּמַר (בראשית ג כב) וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, אֲבָל אָחֳרָא דְאֵין תּוֹכוֹ כְּבַרוֹ דְלַאו פִּימֵיהּ וְלִבֵּיהּ שָׁוִין, עֲלֵיהּ אִתְּמַר (שם ב יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, דְוַדַּאי דָּא אִיהוּ עִרְבוּבְיָא בִּישָׁא, דִמְשַׁקֵּר מוֹנְיָיטָא דְמַלְכָּא, דִּמְעָרֵב כַּסְפָּא בַעוֹפֶרֶת. וְדָא הֲוָה חֵטְא דְחַוָּה דְהִטִּיל בָּהּ נָחָשׁ זוּהֲמָא, דְאִיהוּ עוֹפֶרֶת דְּאִתְעָרֵב בְּטִפָּה (נ\"א בכספא) חִוְורָא כַסְפָּא מְזוּקָק, וְלָא אִתְדַּכֵּי זוּהֲמָא מִנֵיהּ עַד דְּאָתָא אַבְרָהָם וְעָאל בְּנוּרָא וְאִתְלַבַּן כַּסְפָּא, וְנָפִיק עוֹפֶרֶת לְבָר דְּאִיהוּ יִשְׁמָעִאל, וְאִתְּמַר בְּאָדָם מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה, אִתְעָרֵב עִרְבוּבְיָא בְדַהֲבָא, אִצְטְרִיף בְּיִצְחָק, וְאַפִּיק זוּהֲמָא לְבָר וְדָא עִשָׂו, בְּיַעֲקֹב נָח וְאִשְׁתָּרַשׁ וְאַפִּיק תּוֹלָדִין, וְאִתְרַבֵּי עִץ הַחַיִּים בְּעַנְפּוֹי וְשָׁרָשׁוֹי.</p>\n<p>עַיְינִין בְּעִגּוּלָא מִסִּטְרָא דְאָת י', בַּאֲרִיכוּ מִסִּטְרָא דְאָת ו', כַּנְפֵי עִינָא אִינוּן ה\"ה, בְּאַרְבַּע אַתְוָון אִלֵּין אִיהוּ עִינָא בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה, וְהָכִי כָּל אֵבֶר וְאֵבֶר בֵּיהּ תִּשְׁכַּח יהו\"ה, דְּאָזִיל בַּמִּדָּה וּבַמִּשְׁקָל, וְאִיהוּ בַּמִּדָּה וּבַמִּשְׁקָל דְּדִבּוּרָא, קָלָא אִיהוּ שֶׁקֶל, מִדָּה דִבּוּר, כַּנְפֵי תִּקְלָא תְּרֵין הֲבָלִין דְּאִינוּן אֲמִירָה וּקְרִיאָה.</p>\n<p>גַּוָּונִין דְּעִינָא, חִוָּור לְבָנָ\"ה סוּמָק מַאֲדִי\"ם, יָרוֹק חַמָּ\"ה, אוּכָּם שַׁבְּתַא\"י, תְּכֵלֶת צֶדֶ\"ק, וְאִינוּן כְּגַוְונָא דְחֶסֶד גְּבוּרָה תִּפְאֶרֶת יְסוֹד וּמַלְכוּת, תְּרֵי כְּרוּבֵי עִינָא נֶצַח וְהוֹד לְקִבְלַיְיהוּ נֹגַ\"הּ כֹּכָ\"ב, כְּגַוְונָא דְסִטְרָא דְּדַכְיוּ, הָכִי אִינוּן מִסִּטְרָא אָחֲרָא.</p>\n<p>שִׁבְעָה כֹּכְבֵי לֶכֶת אִינוּן שֶׁבַע כְּפוּלוֹת ב ג ד כ פ ר ת כְּגַוְונָא דָא ב בּ ג גּ ד דּ כ כּ פ פּ ר רּ ת תּ, דִּינָא רַפְיָא וְדִינָא קַשְׁיָא, וּבְהוֹן וְהַחַיּוֹת רָצוֹא וָשׁוֹב (יחזקאל א יד), רָצוֹא בְדָגֶ\"שׁ וָשׁוֹב בְּרָפֵ\"ה, וְאִינוּן דִּינָא וְרַחֲמֵי, וְהָכִי אִינוּן מִסִּטְרָא אָחֳרָא שֶׁבַע כְּפוּלוֹת, לְקִבְלַיְיהוּ שֶׁבַע רְקִיעִין שֶׁבַע אַרְעִין, וְאִינוּן שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת (זכריה ד ב), וְהָכִי אִינוּן שֶׁבַע תַּרְעִין דְּגֵיהִנָּם וְשֶׁבַע הֵיכָלִין, מַלְיָין נְחָשִׁים וְעַקְרַבִּים וַחֲשׁוֹכָא, דְּמִתַּמָּן הֲוָה מִתְנַבֵּא בִּלְעָם חַיָּיבָא, וַעֲלַיְיהוּ אִתְּמַר (ישעיה נא ו) כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה, וְכֹכְבַיָּא דִלְהוֹן עֲלַיְיהוּ אִתְּמַר (שם לד ד) וְנָמַקּוּ כָּל צְבָא הַשָּׁמַיִם (תהלים קב כז), הֵמָּה יֹאבֵדוּ וְאַתָּה תַעֲמוֹד, וּבַאֲבוּדָא דִלְהוֹן (שם צו יד) יִ שְׂמְחוּ הַ שָּׁמַיִם וְ תָגֵל הָ אָרֶץ דְּאִתְבְּרִיאוּ בִשְׁמָא דְיהו\"ה.</p>\n<p>אַנְפִּין אִינוּן בְּאַרְבַּע גַּוָּונִין, אִית בַּר נַשׁ</p>"],[9500011257,"<p>דְּאַנְפּוֹי חִוְורִין מִסִּטְרָא דְאַנְשֵׁי חַיִל, וְאִית בַּר נַשׁ דְּאַנְפּוֹי סוּמְקָא מִסִּטְרָא דְיִרְאֵי אלהי\"ם, וְאִית בַּר נַשׁ דְּאַנְפּוֹי יְרוֹקִין מִסִּטְרָא דְאַנְשֵׁי אֱמֶת, וְאִית בַּר נַשׁ דְּאַנְפּוֹי אוּכְמִין מִסִּטְרָא דְשׂוֹנְאֵי בָצַע, לְקִבְלַיְיהוּ אַרְבַּע אָחֳרָנִין מִסִּטְרָא דִמְסָאֲבוּ כֻּלְּהוּ חֲשׁוֹכִין, אַנְפִּין מִסִּטְרָא דִימִינָא בִישָׁא עוֹפָרֶת, דְּמִתְרַבִּין מִלֵּיחָה חִוְורָא, אִינוּן עָבִים וְגַסִּים, וְעִינוֹי גַּסִּים וְעָבִים, וְגוּפֵיהּ עָב וְגַס, מִסִּטְרָא דִימִינָא מוֹחָא, חִוְורָא כְּכַסְפָּא, זֶרַע אַבְרָהָם אוֹהֲבִי (ישעיה מא ה), וּמָאן דְּאִיהוּ אַנְפּוֹי וְגוּפֵיהּ וְכָל אֵבָרִין דִּילֵיהּ גַּסִּין וְעָבִים, אִיהוּ עָצֵל כָּבֵד חָשׁוּךְ, וּמִסִּטְרָא דְהַאי לֵיחָה אִתְּמַר בְּאַבְרָהָם (בראשית טו יב) וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם, וְהִנֵּה אֵימָה חֲשֵׁכָה גְדוֹלָה נֹפֶלֶת עָלָיו, וְהַאי לֵיחָה אִיהִי זוּהֲמָא דְהִטִּיל נָחָשׁ בְּחַוָּה, וּמִסִּטְרָא דִילֵיהּ תִּכְבַּד הָעֲבֹדָה (שמות ה ט), וּמִסִּטְרָאָה וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקֹּצֶר רוּחַ וּמֵעֲבוֹדָה קָשָׁה (שמות ה ט), וּמִסִּטְרָאָה וַיַּכְבֵּד לֵב פַּרְעֹה (שם ט ז) וַעֲבָדָיו, וְאִיהִי כוֹבֶד הַמַּס וְכוֹבֶד הַמְּלָאכָה.</p>\n<p>אַנְפִּין יְרוֹקִין, אִינוּן מִסִּטְרָא דְמָרָה, יְרוֹקִין חֲשׁוֹכִין, וְהַאי בַּר נַשׁ אִיהִי קַל, בְּהִפּוּכָא דְלֵיחָה דְאִיהִי כְּבֵדָה, הַאי קַל וְהַאי כָּבֵד, הַאי פֶּתִי לְבִישׁ וְהַאי פִּקְחָא לְבִישׁ, הַאי מַזְקִין בִּמְהִירוּ וְאַקְדִּים בְּסֵיבוּ, וְהַאי קַשִּׁישׁ בְּסֵיבוּ, וְאִיהוּ מְאוּחָר בְּסֵיבוּ, הַאי אִתְעֲבִד פֶּתִי לְמִפְתֵּי בְנֵי נָשָׁא בְרַמָּאוּת, בְּגִין דְּאִיהוּ מִסִּטְרָא דְנָחָשׁ הַקַּדְמוֹנִי דִמְפַתֵּי לִבְנֵי נָשָׁא, אִסְתַּמַּר מִנֵּיהּ, וְהַאי יְרוֹקָא פְקִיחָא לְבִישׁ, הַאי כָּל מַה דְּאִית בְּלִבֵּיהּ שָׁפֵיךְ לְבָר, וְהַאי גָּנִיז לוֹן לְגָאו, הַאי כָּל עוֹבָדוֹי בְּעִכּוּבָא, וְדָא כָל עוֹבָדוֹי בִּמְהִירוּ, וְאִיהוּ יָבֵשׁ גּוּפָא וְאַנְפִּין וְכָל אֵבָרִין דִּילֵיהּ, בְּהִפּוּכָא דְאָחֳרָא, בְגִין דְּגֵיהִנָּם דְּאִיהִי מָרָה יְרוֹקָא אוֹקִיד בֵּיהּ דְּאִיהִי כֹּעִס, כַּעִִסָן אִיהוּ וַדַּאי, דְּאוֹקִיד בֵּיהּ נוּרָא לְפוּם שַׁעִִתָּא וּמִיָּד שָׁכִיךְ, הָכִי כָּל עוֹבָדוֹי בָּעִי לְמֶעֱבַד בִּמְהִירוּ, וְאָחֳרָא דְאִיהוּ כָּבֵד בְּנַחַת, דָּא בְּהִפּוּכָא דְּדָא, דָּא נָחָשׁ וְדָא שָׂרָף, דָּא מַיָּא וְדָא אֶשָּׁא, מַיָּא דְמֵי טוֹפָנָא דְחָבִיל כָּל בִּשְׂרָא, הַאי אָחֳרָא מִנֵּיהּ גָּפְרִית וָאֵשׁ.</p>\n<p>אַנְפִּין סוּמְקִין מִסִּטְרָא אָחֳרָא, הַאי אִתְחַזֵּי בֵּינוֹנִי לָא גַס וְלָא יָבֵשׁ, הַאי אִתְאַדַּם מִסִּטְרָא דְמַאֲדִים, אוֹשִׁיד דְּמָא אִיהוּ, אִסְתַּמַּר מִנֵּיהּ, וּתְרֵין אִינוּן בְּהִפּוּכָא סוּמָק וְאוּכָּם, דָּא בֵינוֹנִי בְּמַתְקְלָא, וְדָא בְהִפּוּכָא מִסִּטְרָא אָחֳרָא, דָּא שַׂמְחָן וְדָא עֲצִיב, שַׂמְחָן מִסִּטְרָא דְּדָם, שְׂחוֹק הַכְּסִיל, וְדָא עֲצִיב מִסִּטְרָא דְמָרָה אוּכְמָא, דָּא גָזֵיל וְשָׁפֵיךְ דְּמָא, וְאִיהוּ וַותְּרָן, וְדָא כָּנִישׁ קוֹבֵץ עַל יָד.</p>\n<p>מִסִּטְרָא דְּדַכְיוּ בְּהִפּוּכָא, אַנְשֵׁי חַיִל אַנְפִּין חִוְורִין מִסִּטְרָא דְמוֹחָא, יִרְאֵי אלהי\"ם מִסִּטְרָא דְלִבָּא, אַנְשֵׁי אֱמֶת מִסִּטְרָא דְפִימָא, שׂוֹנְאֵי בָצַע מִסִּטְרָא דְגוּפָא, וְהָא אוּקְמוּהָ אַנְשֵׁי חַיִל יִרְאֵי אלהי\"ם אַנְשֵׁי אֱמֶת שׂוֹנְאֵי בָצַע מִסִּטְרָא דְאדנ\"י, שִׁעוּר וּמִדָּה דִלְהוֹן יהו\"ה מִלְּגָאו וּמִלְּבָר, י' אִתְלַבַּשׁ בְּאַנְשֵׁי חַיִל וְדָא מוֹחָא דְתַמָּן חָכְמָה, ה' בְּיִרְאֵי אלהי\"ם דְּאִיהוּ לִבָּא, וְתַמָּן דְּחִילוּ וּרְחִימוּ דְאִינוּן י\"ה בִּימִינָא וּבִשְׂמָאלָא, וְאִינוּן נִסְתָּרוֹת בְּמוֹחָא וּבְלִבָּא, ו' אִתְלַבַּשׁ בְּפִימָא מִסִּטְרָא דְאִלֵּין דְּאִינוּן אַנְשֵׁי אֱמֶת, ה' אִתְלַבַּשׁ בְּגוּפָא מִסִּטְרָא דְאִלֵּין שׂוֹנְאֵי בָצַע, וְאִינוּן תּוֹרָה וּמִצְוָה, וַעֲלַיְיהוּ אִתְּמַר וְהַ נִּגְלוֹת.</p>\n<p>אַנְפִּין עֲגוּלִין מִסִּטְרָא דִנְקוּדֵי, דְּאִינוּן קָמֵ\"ץ פַּתָ\"ח צֵרִ\"י סֶגוֹ\"ל שְׁבָ\"א חֹלֵ\"ם חִרֵ\"ק שֻׁרֵ\"ק שׁוּרֵ\"ק, מַלְכוּת עִגּוּלָא דְכֻלְּהוּ. תָּא חֲזִי, תֵּשַׁע זִמְנִין יהו\"ה, בְּכָל סְפִירָה וּסְפִירָה נְקוּדָה דִילֵיהּ, וְאִיהוּ יהו\"ה בַּמַּלְכוּת בְּלָא נְקוּדָה, וְאִלֵּין אִינוּן נְקוּדִין דִּמְחַיְּיבִין כָּל סְפִירָה וּסְפִירָה, תֵּשַׁע נְקוּדִין אִינוּן חַד יהו\"ה בְּקָמֵ\"ץ, תִּנְיָינָא יהו\"ה בְּפַתָח, תְּלִיתָאָה יהו\"ה בְּצֵירִ\"י, רְבִיעָאָה יהו\"ה בְּסֶגוֹ\"ל חֲמִשָּׁאָה יהו\"ה בִּשְׁבָ\"א,</p>"],[9500011258,"<p>שְׁתִיתָאָה יהו\"ה בְּחֹלֵ\"ם, שְׁבִיעָאָה יהו\"ה בְּחִירֵ\"ק, תְּמִינָאָה יהו\"ה בְּשָׁלֹשׁ נְקֻדּוֹת, תְּשִׁיעָאָה יהו\"ה בְּשׁוּרֵ\"ק, מַלְכוּת יהו\"ה כְּלִילָא מִכֻּלְּהוּ. קָמֵ\"ץ אִתְקְרֵי בִנְקוּדָה דָא מִסִּטְרָא דְכֶתֶר עִלָּאָה דְאִיהוּ סָתִים כְּקָמֵ\"ץ, דְּאִיהוּ סָתִים בְּמַחֲשָׁבָה, דְלָא יָדַע בַּר נַשׁ מַה דְּאִית בְּגַוִּיהּ, וּמָאן דְּאִיהוּ לְגוֹ סָתִים בְּמַחֲשָׁבָה, עִלַּת הָעִלּוֹת קָרִינָן לֵיהּ.</p>\n<p>וְאִתְקְרֵי פַּתָ\"ח כִּנְקוּדָה דָא מִסִּטְרָא דְחָכְמָה, דְבָהּ אִתְפַּתַּח וְאִתְגַּלְיָיא מַחֲשָׁבָה סְתִימָא, כְגַוְונָא דָא לְעִילָא כְּדִיּוֹקְנָא דָא, לְתַתָּא כְּדִיּוֹקְנָא דָא וּתְרֵין נְקוּדִין אִתְגְּלִיאוּ בְאִימָּא, בְכִתְרָא עִלָּאָה סְתִימִין אִינוּן, וְאִתְעֲבִידוּ צֵרִי יֵהֵוִהֵ, עֲלַיְיהוּ אִתְּמַר (בראשית ב ז) וַיִּיצֶר יהו\"ה, כִּי בְּיָ\"הּ יהו\"ה צוּר עוֹלָמִים (ישעיה כו ד), צִיֵּיר תְּרֵין עָלְמִין עָלְמָא דֵין וְעָלְמָא דְאָתֵי.</p>\n<p>סֶגוֹ\"ל דָּא חֶסֶד, בֵּיהּ שְׁכִינְתָּא אִיהוּ סֶגוֹלְתָּ\"א לְעִילָא, סֶגוֹ\"ל לְתַתָּא, סֶגוֹלְתָּא וּרְחִימָא מִסִּטְרָא דִימִינָא, שְׁבָ\"א כְּגַוְונָא דָא מִסִּטְרָא דִשְׂמָאלָא, כִּי בָאֵ\"שׁ יהו\"ה נִשְׁפָּט (שם סו טז), וַתִּפּוֹל שְׁבָא וַתִּקָּחֵם (איוב א טו), שְׁבָה עִמָּדִי (בראשית כט יט) דְּאִיהִי שְׁכִינְתָּא דְאִתְקְרֵי שְׁבָ\"א מִסִּטְרָא דִשְׂמָאלָא. וְאִתְקְרֵי חֹלֵ\"ם כְּגַוְונָא דָא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, מִשָּׁם רוֹעִִה אֶבֶן יִשְׂרָאֵל (שם מט כד), אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה (תהלים קיח כב), כָּל מַרְגְּלִיתָא יַקִּירָא אִיהִי בְּחֹלֵ\"ם, הֲדָא הוּא דִכְתִיב (שמות כח יט) לֶשֶׁם שְׁבוֹ וְאַחְלָמָה, וּבֵיהּ וַנַּחַלְמָה חֲלוֹם (בראשית מא מא).</p>\n<p>חִרֵ\"ק אִתְקְרֵי מִסִּטְרָא דְשׁוֹקָא יְמִינָא כְּגַוְונָא דָא בֵּיהּ חֲקִירָה, הַחֵקֶר אֱלוֹ\"הַ תִּמְצָא (איוב יא ז), וְאִיהוּ קֶרַח הַנּוֹרָא, קֶרַח מֵהַהוּא נוֹרָא (יחזקאל א כב) דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא. שֻׁרֵ\"ק הוֹד אִתְקְרֵי, כְּגַוְונָא דָא יֻהֻוִהֻ, מִתַּמָּן אִתְקְרִיאַת שְׁכִינְתָּא שֻׁרֵ\"ק, קֶשֶׁר הַמֶּרְכָּבָה, וְאִיהוּ הוֹד דְּמֹשֶׁה, בֵּיהּ אִשְׁתַּלִּימוּ חֲמִשָּׁה בְרִיחִים לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הַשֵּׁנִית (שמות כו כז), כְּחוּשְׁבַּן ה' דִילֵיהּ, אִשְׁתָּאַר ו\"ד דּוּ פַּרְצוּפִין, עֲלֵיהּ אִתְּמַר (שם טז) עִִשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, קֶרֶשׁ, קֶשֶׁר.</p>\n<p>שׁוּרֵק יוּהוּווּהוּ, דָּא צַדִּיק, דְּאִיהוּ קוֹשֵׁר הַמֶּרְכָּבָה, דְאִיהִי שְׁכִינְתָּא עִם קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (ד\"ה א כט יא) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְדָא דְמִתַּרְגְּמִינָן דַּאֲחִיד בִּשְׁמַיָּא וּבְאַרְעָא, וַעֲלֵיהּ אִתְּמַר (ירמיה ב כא) וְאָנֹכִי נְטַעִִתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, זֶרַע אֱמֶת הוּא וַדַּאי, דְּאִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב, אִיהוּ זֶרַע, וּשְׁכִינְתָּא עִזֶר, הֲדָא הוּא דִכְתִיב (בראשית ב יח) אֶעֱשֶׂה לוֹ עִזֶר כְּנֶגְדּוֹ, כָּל אִלֵּין נְקוּדִין אִתְחַיְיבוּ בִּשְׁמָא (נ\"א אתחייב שמא) קַדִּישָׁא מִסִּטְרָא דְתֵשַׁע סְפִירָן, וּמַלְכוּת כְּלִילָא דְכֻלְּהוּ, אַהֲבַת כְּלוּלֹתָיִךְ (ירמיה ב ב), הָא הָכָא אַנְפִּין עִגּוּלִין דִּלְעִילָא, נְקִידִין בִּנְקוּדִין.</p>\n<p>וְאִית אַנְפֵּי רַבְרְבֵי, וְאַנְפֵּי זוּטְרֵי, אַנְפִּין דְּרַחֲמֵי, וְאַנְפִּין דְּזַעַם, דִּבְהוֹן וְאֵ\"ל זוֹעִם בְּכָל יוֹם (תהלים ז יב), וּבְגִין דָּא אָמַר לְמֹשֶׁה הַמְתֵּן לִי עַד שֶׁיַּעַבְרוּ פָּנִים שֶׁל זַעַם, וּמִיָּד וַיַּעֲבוֹר יהו\"ה עַל פָּנָיו וַיִּקְרָא, יהו\"ה יהו\"ה אֵ\"ל רַחוּם וְחַנּוּן (שמות לד ו), דְּאִינוּן בְּרָזָא דְאָת וָא\"ו, תְּלַת עֲשַׂר מְכִילָן, א' דִּבְאֶמְצָעִיתָא דְוָא\"ו אֶרֶךְ אַפַּיִם מַאי אַפַּיִם דִּילֵיהּ ו\"ו, דִּבְהוֹן מַאֲרִיךְ אַנְפִּין עַל חַיָּיבַיָּא, וּמְרַחֵם עַל עָלְמָא, וַעֲלַיְיהוּ אִתְּמַר (במדבר ו כה) יָאֵר יהו\"ה פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ, יִשָּׂא יהו\"ה פָּנָיו אֵלֶיךָ, ה' ה' אִינוּן גַּוָּונִין דְּאַנְפִּין חִוָּור וְסוּמַק, וְחוֹטָמָא אִיהוּ אֲרִיךְ אַנְפִּין, יו\"ד פִּימָא כְּלָלָא דִתְלַת דַּרְגִּין, י' חוּט בְּעִגּוּלָא, ו' לָשׁוֹן, ד' כְּלָלָא דְאַרְבַּע תִּקּוּנִין שִׂפְוָון וְשִׁינַיִם וְחֵךְ וְגָרוֹן.</p>\n<p>תָּא חֲזִי אִתְּמַר בְּאָדָם (איוב יד כ) מְשַׁנֶּה פָנָיו וַתְּשַׁלְּחֵהוּ, וּמָאן גָּרִים לֵיהּ שִׁנּוּיָא דְאַנְפִּין, לְשַׁנָּאָה לֵיהּ דְּלָא יִשְׁתְּמוֹדְעָן בֵּיהּ מָארֵי דְּדִינָא, הַאי אִיהוּ שִׁנּוּי מָקוֹם שִׁנּוּי הַשֵּׁם שִׁנּוּי מַעֲשֶׂה. וְעוֹד נְקוּדִין אִינוּן סֶגּוֹלִין נָהֲרִין (נ\"א בהדין) נְקוּדָה דְאוֹרַיְיתָא, וְאִינוּן נִעִִנוּעִין דְּאַתְוָון, לָקֳבֵל פִּרְקִין וְעַרְקִין, דְּאִינוּן נִעִִנוּעִין דְּאֵבָרִין דְּגוּפָא. וְאִתְקְרִיאוּ בְּאִלֵּין שְׁמָהָן, ק\"דומיאל (נ\"א ק\"דמיאל) (ס\"י קמואל) מ\"לכיאל צ\"וריאל הָא קָמֵץ בְּאַתְווֹי, פ\"דאל ת\"ומיאל ח\"סדיאל הָא פַּתָח, צ\"וריאל ר\"זיאל י\"ופיאל הָא צֵרִי, ס\"מטוריה</p>"],[9500011259,"<p>ג\"זריאל (נ\"א ג\"בריאל) ו\"ענאל ל\"מואל הָא סֶגוֹל, ש\"מעיאל ב\"רכיאל א\"הניאל הָא שְׁבָא, ח\"ניאל ל\"הריאל (נ\"א ל\"הדיאל) מ\"חניאל הָא חֹלֵם, ח\"זקיאל ר\"הטיאל ק\"רשיאל (נ\"א ק\"דושיאל) הָא חִרֵק, ש\"מועאל ר\"עמיאל ק\"ניאל הָא שֻׁרֵק, ש\"משיאל ר\"פאל ק\"דשיאל הָא שֻׁרֵק, הָא תְמַנְיָא וְעִִשְׂרִין שְׁמָהָן, דְּאִתְּמַר בְּהוֹן (תהלים קיא ו) כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ, זַכָּאִין אַנְפִּין דְּנָהֲרִין בְּהוֹן אִלֵּין שְׁמָהָן, וְאִינוּן לָקֳבֵל י\"ד פִּרְקִין דְּיָד יְמִינָא וְלָקֳבֵל י\"ד פִּרְקִין דְּיָד שְׂמָאלָא, יהו\"ה אלהינ\"ו יהו\"ה, כוז\"ו במוכס\"ז כוז\"ו, עֲלַיְיהוּ אִתְּמַר (שמות כ ג) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, וְאִם לַאו עֲלַיְיהוּ אִתְּמַר (משלי יא כא) יָד לְיָד לֹא יִנָּקֶה רָע.</p>\n<p>חוֹטָמָא אֲרִיכָא, דָא הוּא בַר נַשׁ דְּאִית בֵּיהּ רַחֲמֵי, חוֹטָמָא קְמִיטָא מָארֵי דְרוּגְזָא אִיהוּ, חוֹטָמָא עֲקִימָא מִסִּטְרָא דְחִוְיָא אִיהוּ בְּכָל אֵבֶר דְּחָב בַּר נַשׁ הַהוּא חִוְיָא אִיהוּ כְרִיכָא תַמָּן וְעָקִים לֵיהּ, בֵּין בְּאוּדְנִין בֵּין בְּעַיְינִין בֵּין בְּחוֹטָמָא בֵין בְּפִימָא, וַעֲלֵיהּ אִתְּמַר (קהלת א טו) מְעְִוָּת לֹא יוּכַל לִתְקוֹן וְגוֹמֵר, וְכָל כְּאֵבִין דִּבְנֵי נָשָׁא דְאִינוּן תַּקִּיפִין, דְּאִתְּמַר בְּהוֹן (דברים כח נט) וָחֳלָיִם רָעִים וְנֶאֱמָנִים, הוּא דְנָשִׁיךְ לוֹן הַהוּא חִוְיָא בְכַמָּה נְשִׁיכִין בְּהַהוּא אֵבֶר דְּחָב, עַד דְּאִתְפַּרַע מֵהַהוּא חוֹבָא, וּבְגִינֵיהּ אִתְּמַר אֲפִילוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק, לֹא יַפְסִיק בְּיִחוּדָא בִצְלוֹתֵיהּ, וְהָא כְתִיב בְּכָל פִּקּוּדִין (ויקרא יח ה) וָחַי בָּהֶם, וְלֹא שֶׁיָּמוּת בָּהֶם, אָמַר לָהֶם בְּגִין דָּא אָמְרוּ אֲבָל עַקְרָב פּוֹסֵק בְּגִין דְּקָטִיל. תָּא חֲזִי בְּחוֹטָמָא אִית תְּרֵין נוּקְבִין, מֵחַד נָפִיק רוּחָא, וּמֵחַד נָפִיק תְּנָנָא, הֲדָא הוּא דִכְתִיב (דברים כט יט) כִּי אָז יֶעִִשַּׁן אַף יהו\"ה וְקִנְאָתוֹ בָּאִישׁ הַהוּא, בְּרוּחָא קַרִיר אָמַר (שמות טו ח) וּבְרוּחַ אַפֶּיךָ נֶעִִרְמוּ מַיִם, בִּתְּנָנָא דְסָלִיק כֶּעָשָׁן אָמַר (שם) נָשַׁפְתָּ בְרוּחֲךָ כִּסָּמוֹ יָם.</p>\n<p>אוּדְנִין אִית בְּהוֹן אִדְרִין וְאַכְסַדְרִין, וַעֲלַיְיהוּ אָמַר דָּוִד שִׁיר לַמַּעֲלוֹת, דְּאִינוּן כִּי גָבוֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר, וּגְבֹהִים עֲלֵיהֶם (קהלת ה ז), אִי אִינוּן אֲטִימִין אוּדְנִין לְתַתָּא, הָכִי אִינוּן אֲטִימִין תַּרְעִין דִּשְׁמִיעָה לְעִילָא לְגַבַּיְהוּ, וְאִינוּן תַּרְעִין דְּאִתְּמַר בְּהוֹן (תהלים סה ג) שׁוֹמֵעַ תְּפִלָּה, שְׁמַע יִשְׂרָאֵל (דברים ו ד), מִתַּמָּן צָרִיךְ לְכַוְונָא בִשְׁמִיעָה. אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, וְהָא שְׁמִיעָה בְאָן אֲתַר תַּלְיָא לְעִילָא.</p>\n<p>אָמַר לֵיהּ בְּרִי רְאִיָּה הוּא כִּסֵּא לַמִּזְרָח, דְּמִתַּמָּן נְהוֹרָא נָפִיק לְעוֹלָם, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין, מִזְרָח מִשָּׁם הָאוֹר יוֹצֵא לְעוֹלָם, יְהוּדָה אִיהוּ לַמִּזְרָח, וְאִתְּמַר בֵּיהּ (בראשית מט ט) גּוּר אַרְיֵה יְהוּדָה. מַעֲרָב דָּא פִימָא דְתַמָּן עִרוּב דְּכֹלָּא, וְתַמָּן מִתְעָרְבִין כָּל חֲיָילִין וְכָל דַּרְגִּין, וּמַחֲנֵה אֶפְרַיִם לְמַעֲרָב, וּמִטָּה לְמַעֲרָב בֵּין צָפוֹן לַדָּרוֹם. שְׁמִיעָה לָקֳבֵל שֻׁלְחָן בַּצָּפוֹן, וְתַמָּן דְּחִילוּ, הֲדָא הוּא דִכְתִיב (חבקוק ג ב) יהו\"ה שָׁמַעִִתִּי שִׁמְעֲךָ יָרֵאתִי, וּמַחֲנֵה דָן לַצָּפוֹן, וְאֹזֶן דְּמוּת אַלֶּ\"ף, דְּאִתְּמַר בֵּיהּ אַלֵּף בִּינָה, דְּאִיהִי נַמִּי עוֹז לַצָּפוֹן. רֵיחָא לַדָּרוֹם, רֵיחַ נִיחֹחַ לַיהו\"ה (ויקרא א ט), וְאִית לְחוֹטָמָא תְּרֵין נוּקְבִין, כְּלִילָן מִדִּינָא וְרַחֲמֵי, וְאִינוּן י' י', חוֹטָמָא ו' בְּאֶמְצָעִיתָא, תְּרֵין צִנּוֹרוֹת אִינוּן דִּילֵיהּ, וְאִתְּמַר לְגַבֵּי מַחֲנֵה רְאוּבֵן לַדָּרוֹם רְאוּ בֵן, תְּרֵין נוּקְבִין דְּחוֹטָמָא אִינוּן לָקֳבֵל לֵאָה וְרָחֵל, חוֹטָמָא בְּאֹרַח מֵישׁוֹר בֵּינַיְיהוּ דָא יַעֲקֹב.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, מְנָא לָךְ דְּאִימָּא (נ\"א דבינה) אִיהִי לַצָּפוֹן, וּבָהּ תַּלְיָא שְׁמִיעָה, אָמַר לֵיהּ בְּרִי חַמְשִׁין תַּרְעִין אִנּוּן דְּבִינָה, וּבָהּ מְיַיחֲדִין כ\"ה כ\"ה אַתְוָון תְּרֵין זִמְנִין בְּכָל יוֹמָא, וְיִשְׂרָאֵל אִיהוּ בֶן י\"ה, בִּינָה וַדַּאי כְּלָלָא דִתְלַת אַתְוָון אַבָּא וְאִימָּא וּבְרָא, וּבְגִין דָּא שְׁמִיעָה בָהּ תַּלְיָא, לֵית תִּקּוּנָא מֵאִלֵּין אַרְבַּע אַתְוָון דְּלָא אִתְכְּלִילָן בָּהּ עֲשַׂר סְפִירָן, דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א, וְאַרְבַּע אַתְוָון דְּאִינוּן יהו\"ה אִיהוּ לָא אִשְׁתַּנִּי בְּכָל אֲתַר, אִיהוּ שָׁמַע דִּשְׂמָאלָא</p>"],[9500011260,"<p>לְיִשְׂרָאֵל, וְאִסְתַּכַּל בִּימִינָא עֲלַיְיהוּ, וּבַדָּרוֹם אִיהוּ מְרַחֵף עֲלַיְיהוּ, הֲדָא הוּא דִכְתִיב (בראשית א ב) וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, וּבְמַעֲרָב אִיהוּ מְמַלֵּל עִמְּהוֹן, שִׁנּוּיִין אִינוּן בְּמָאנֵי דְּגוּפָא, אֲבָל בֵּיהּ לֵית שִׁנּוּיָא כְּלָל, הֲדָא הוּא דִכְתִיב (מלאכי ג ו) אֲנִי יהו\"ה לֹא שָׁנִיתִי.</p>\n<p>וּבְכָל אֵבֶר וְאֵבֶר (דאיהו נרא דכל פקודא) בָּעִי בַר נַשׁ לְאַמְלָכָא לְקוּדְשָׁא בְּרִיךְ הוּא, וּלְתַקְנָא לֵיהּ אֲתַר דַּכְיָא וּנְקִיָּיא לְשַׁרְיָא לֵיהּ תַּמָּן, וּבְגִין דָּא צָרִיךְ בַּר נַשׁ לְבַעֲרָא מִנֵּיהּ מִכָּל אֵבֶר וְאֵבֶר, כָּל מַחֲשָׁבִין וְכָל הִרְהוּרִין בִּישִׁין דְּטִנּוּפִין דְּאִינוּן קְלִיפִין, וְצָרִיךְ לְאוֹקָדָא לוֹן בְּכָל פִּקּוּדִין כְּשֵׁרִין, דְּשַׁרְיָין עַל כָּל אֵבֶר וְאֵבֶר דְּאִינוּן נֵרוֹת, דְּכָל פִּקּוּדָא נֵר אִתְקְרִיאַת, הֲדָא הוּא דִכְתִיב (משלי ו כג) כִּי נֵר מִצְוָה, נֵר יהו\"ה נִשְׁמַת אָדָם (שם כ כז), וּבָהּ צָרִיךְ לְמֶהֱוִי (שם) חוֹפֵשׂ כָּל חַדְרֵי בָטֶן, וּלְבַעֲרָא מִנַּיְיהוּ שְׂאוֹר וְחָמֵץ מוֹץ וְתֶבֶן, שְׂאוֹר וְחָמֵץ מִן הָעִסָּה (נ\"א הטפה), מוֹץ וְתֶבֶן מִן הַחִטָּה, לְשַׁרְיָא תַמָּן י\"ה, י' בְּעִסָּה דְאִיהִי טִפָּה, ה' בְּחִטָּה, דְּאִיהִי לְבַעֲרָא חֵט מִן ה' דְּאִשְׁתָּאֳרַת סֹלֶת נְקִיָּה.</p>\n<p>דְּכָל פִּקּוּדָא דְשַׁרְיָא עַל כָּל אֵבֶר וְאֵבֶר אִית לָהּ שֵׁם יְדִיעַ, וְכָל חֲיָילִין וּמַשִּׁרְיָין דְּמַלְאָכִין דְּתַלְיָין מִנֵּיהּ, כֻּלְּהוּ אִתְכַּנְשׁוּ לְהַהוּא אֵבֶר, וְנָטְרִין לֵיהּ מִכָּל מַרְעִין בִּישִׁין, וּמָאן דְּחָלִיף לוֹן אוֹ קָרָא לוֹן בְּאֵבֶר דְּלַאו דִּלְהוֹן, וְלַאו אִינוּן מְמַנָּן עֲלַיְיהוּ, אִיהוּ אַכְחִישׁ סִדּוּרָא דְעוֹבָדָא דִבְּרֵאשִׁית, וְלַאו מִתְכַּנְּשִׁין לְגַבֵּיהּ, לְמַלְכָּא דְשַׁוִּי מְמַנָּן עַל מַלְכוּתֵיהּ, וּפָלִיג לוֹן עַל כָּל אֲתַר וַאֲתַר, וְאָמַר לוֹן אַנְתְּ תְּהֵא מְמַנָּא עַל אֲתַר כַּךְ וְכַךְ, וְאַנְתְּ כַּךְ וְכַךְ, וּלְכָל חַד שַׁוִּי לֵיהּ בַּאֲתַר יְדִיעַ, וּבְמִלָּה יְדִיעַ, לֵית לֵיהּ חִלּוּף בַּאֲתַר אָחֳרָא.</p>\n<p>אֲבָל קוּדְשָׁא בְּרִיךְ הוּא דְשָׁלְטָנוּתֵיהּ בְּכָל אֲתַר כְּנִשְׁמָתָא דְשָׁלְטָנוּתָהּ עַל כָּל אֵבֶר וְאֵבֶר, מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, בְּכָל אֲתַר דְּקָרֵי לֵיהּ בַּר נַשׁ עָנֵי לֵיהּ, אֶלָּא אִם הַהוּא אֲתַר דְּהַהוּא אֵבֶר אִיהוּ פָגוּם בְּחוֹבָה דְעָבִיד בַּר נַשׁ, קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁרְיָא בְהַהוּא אֵבֶר, דַּעֲלֵיהּ אִתְּמַר (ויקרא כא יח) כָּל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב.</p>\n<p>וְאֵבָרִין דְּבַר נַשׁ כֻּלְּהוּ אִינוּן מְסוּדָרִין עַל סִדְרֵי בְרֵאשִׁית, וּבְגִין דָּא אִתְקְרֵי בַר נַשׁ עוֹלָם קָטָן, וּמָאן דְּאַמְלִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא עַל כָּל אֵבֶר וְאֵבֶר, כְּאִלּוּ אַמְלִיךְ לֵיהּ עַל כָּל עָלְמָא, וְאַגְרָא דְבַר נַשׁ דְּאַמְלִיךְ לֵיהּ עַל כָּל אֵבֶר וְאֵבֶר לָא אִתְיְיהִיב רְשׁוּ לְגַלָּאָה, דְּאִלֵּין אִינוּן טַעֲמֵי מִצְווֹת דְּלָא אִתְיְיהִיבוּ לְגַלָּאָה, בְּגִין דְּלָא יְהֵא בַּר נַשׁ עוֹבֵד לְקוּדְשָׁא בְּרִיךְ הוּא עַל מְנָת לְקַבֵּל פְּרָס, אֲבָל בְּרִי מִלִּין אִלֵּין דְּלָא צְרִיכִין לְאִתְגַּלְיָא, יְהוֹן טְמִירִין בְּלִבָּךְ, עֲלַיְיהוּ אִתְּמַר (ישעיה כג יח) לֶאֱכוֹל לְשָׂבְעָה וְלִמְכַסֶּה עָתִיק, מִלִּין עַתִּיקִין דְּלָא אִתְמַסְרוּ לְגַלָּאָה יְהוֹן טְמִירִין בְּלִבָּךְ.</p>\n<p>תָּא חֲזִי כַּד בַּר נַשׁ מִתְעַטֵּף בְּעִטּוּפָא דְמִצְוָה, וּמָנַח תְּפִלִּין, וְקָרִי לֵיהּ בִּקְרִיאַת שְׁמַע, הָא תַקִּין לֵיהּ כָּרְסַיָּא בְּעִטּוּפָא דְמִצְוָה, וְהָא אוּקְמוּהוּ וְהוּכַן בַּחֶסֶד כִּסֵּא (שם טז ה), וּבִתְּפִלִּין אִיהוּ מְעַטֵּר לֵיהּ, הֲדָא הוּא דִכְתִיב (יחזקאל כד יז) פְּאֵרְךָ חֲבוֹשׁ עָלֶיךָ, וְקָרָא לֵיהּ בַּקְּרָא לְשַׁרְיָיא עַל כָּרְסַיָּא דְתַקִּין לֵיהּ שְׁמַע יִשְׂרָאֵל, הָכִי קוּדְשָׁא בְּרִיךְ הוּא מְתַקֵּן לֵיהּ בְּהַהוּא עָלְמָא כָּרְסַיָּא וַעֲטָרָה, וּכְמָה דְאִיהוּ נָחִית לֵיהּ תַּמָּן, וִיקוּם כָּרְסַיָּא בְגִינֵיהּ, וְאַמְלִיךְ לֵיהּ עַל כָּל מַלְאָכִין (נ\"א חיילין) וּמַשִּׁרְיָין דְּתַמָּן, הֲדָא הוּא דִכְתִיב (בראשית א כו) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹמֵר, וְרָזָא דְמִלָּה (שמואל א ב ז) כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ.</p>\n<p>וּכְמָה דְנָחִית (ס\"א דמגנין) לֵיהּ בְּכַמָּה נִגּוּנִין דְּשִׁירוֹת תּוּשְׁבָּחוֹת וְהוֹדָאוֹת, הָכִי כַד סָלִיק לְעִילָא כֻּלְּהוּ חֵיוָון דְּמֶרְכָּבוֹת, וּמַשִּׁרְיָין דְּמַלְאָכִין קַדִּישִׁין, דְּחַיּוֹת וְאוֹפַנִּים וּשְׂרָפִים, פָּתְחִין לֵיהּ (נ\"א פרישן) גַּדְפַיְיהוּ בְּחֶדְוָוא בְּנִגּוּנָא לְקַבְּלָא לֵיהּ, הָא הָכָא אַגְרָא דִצְלוֹתָא וְתִקּוּנִין דִּילָהּ דְּאִיהִי פִקּוּדָא חֲדָא.</p>\n<p>פִּקּוּדָא דִבְּרִית מִילָה, בִּגְזִירוּ דְעָרְלָה וּפְרִיעָה, כְּמָה דְאִיהוּ אַעֲבַר מֵהַהוּא אֵבֶר כָּל אִלֵּין קְלִיפִין דֶּאֱלֹהִים אֲחֵרִים, וְתַקִּין בֵּיהּ אֲתַר לְשַׁרְיָא בֵּיהּ שְׁכִינְתָּא תַּמָן, דְּאִיהוּ אוֹת בְּרִית מִילָה, הָכִי קוּדְשָׁא בְּרִיךְ הוּא כַּד נִשְׁמָתֵיהּ</p>"],[9500011261,"<p>סְלִיקַת לְעִילָא, הֲדָא הוּא דִכְתִיב (דברים ל יב) מִ י יַ עֲלֶה לָּ נוּ הַ שָּׁמַיְמָ ה, קוּדְשָׁא בְּרִיךְ הוּא אַעֲבַר מִנֵּיהּ כָּל מַלְאֲכֵי חַבָּלָה וּמְקַטְרְגִין דְּלָא יִקְרְבוּ לְגַבֵּיהּ בְּגִין דִּשְׁמָא דַיהו\"ה שַׁרְיָא עֲלֵיהּ דְּתִשְׁכַּח לֵיהּ בְּאִלֵּין תֵּיבִין מִ י יַעֲלֶ ה לָּנ וּ הַשָּׁמַיְמָ ה, רָאשֵׁי תֵּיבוֹת מִילָ\"ה, וְסוֹפֵי תֵּיבוֹת יהו\"ה, בִּשְׁמֵיהּ סָלִיק לְעִילָא נִשְׁמָתֵיהּ, וּבְהַהוּא זִמְנָא יִתְקַיַּים בֵּיהּ (שם כח ז) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ, וּכְמָא דְאִיהוּ מְקַבֵּל עֲלֵיהּ כָּל פִּקּוּדִין דַּעֲשֵׂה, בִּדְחִילוּ וּרְחִימוּ, הָכִי אַמְלִיכִין לֵיהּ לְעִילָא חֲיָילִין וּמַשִּׁרְיָין, עַל אִלֵּין עָלְמִין דְּתַקִּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְעִילָא, וּמְקַבְּלִין לֵיהּ עֲלַיְיהוּ בִדְחִילוּ וּרְחִימוּ דְמָארֵיהוֹן.</p>\n<p>וּבְזִמְנָא דְבַר נַשׁ אִשְׁתַּדַּל בְּאוֹרַיְיתָא דְאִיהוּ אוֹר, וּבְמִצְוָה דְאִיהוּ נֵר, כְּאִלּוּ נָהִיר עַמּוּדָא דְעַנָּנָא בִימָמָא קֳדָם יהו\"ה, וְעַמּוּדָא דְאֵשָׁתָא בְלֵילְיָא, הָכִי כְּגַוְונָא דָא כַד אָזִיל לְהַהוּא עָלְמָא, מַה כְּתִיב בֵּיהּ (שמות יג כא) וַיהו\"ה הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחוֹתָם הַדֶּרֶךְ, וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם, לְמָאן לַנְּשָׁמָה וְרוּחָא וְנַפְשָׁא דִילֵיהּ, דְּאִינוּן לָקֳבֵל כֹּהֵן לֵוִי וְיִשְׂרָאֵל, וְכֹלָּא בִזְכוּ דְאוֹרַיְיתָא דְאִיהִי אוֹר וְנֵר.</p>\n<p>וְכָל מָאן דְּנָטִיר שַׁבָּת וְאוֹקִיר לֵיהּ וּמְעַנֵּג לֵיהּ בְּגִין יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא, הָכִי קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ אֲתַר לְעִילָא בִנְיָיחָא דְלָא טָרַח בֵּיהּ, וְנָח תַּמָּן מִכָּל טִרְחָא דְהַאי עָלְמָא דְטָרַח בְּכַמָּה גִלְגּוּלִין וְעוֹבָדִין, בְּרִי תָּא חֲזִי, כָּל פִּקּוּדִין אִלֵּין תַּלְיָין בְּדִיּוֹקְנָא דְמַלְכָּא, וְאִית פִּקּוּדִין דְּאִינוּן עַל מְנָת לְקַבֵּל פְּרָס, וְתַלְיָין מִדִּיּוֹקְנָא דְהַהוּא נַעַר דִּלְעִילָא, וְצָרִיךְ לְפָרְשָׁא כָּל פִּקּוּדִין דְּאִינוּן בְּדִיּוֹקְנָא דְמַלְכָּא.</p>\n<p>אִית (אלין) דְּתַלְיָין מֵרֵישָׁא, וְאִית (ואלין) דְּתַלְיָין בְּעַיְינִין, וְכַמָּה מַלְאָכִין וּמַשִּׁרְיָין עִלָּאִין דְּאִינוּן עִינֵי יהו\"ה מְמַנָּן עֲלַיְיהוּ, וְאִית פִּקּוּדִין דְּתַלְיָין מִן אוּדְנִין, וְכַמָּה מַלְאָכִין דְּאִתְקְרִיאוּ אָזְנֵי יהו\"ה מְמַנָּן עֲלַיְיהוּ, וְאִית פִּקּוּדִין דְּתַלְיָין מֵאַנְפִּין, וְכַמָּה מַלְאָכִין דְּאִתְקְרִיאוּ פְּנֵי יהו\"ה מְמַנָּן עֲלַיְיהוּ, דְאִתְּמַר בְּהוֹן (יחזקאל א ו) וְאַרְבָּעָה פָנִים לְאֶחָד, וְאִית פִּקּוּדִין דְּתַלְיָין מֵחוֹטָמָא, וְכַמָּה מַלְאָכִין דְּאִתְּמַר בְּהוֹן (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְמַנָּן עֲלַיְיהוּ, וְאִית פִּקּוּדִין דְּתַלְיָין מִפִּימָא, וְכַמָּה מַלְאָכִים דִּמְמַנָּן עַל קָלִין דְּאוֹרַיְיתָא וְעַל דִּבּוּרִין, דְּאִתְּמַר בְּהוֹן (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר, וְאִית פִּקּוּדִין דְּתַלְיָין מִידוֹי דְּמַלְכָּא, וְכַמָּה מַלְאָכִין מְמַנָּן עֲלַיְיהוּ דְאִתְקְרִיאוּ יְדַיִן, הֲדָא הוּא דִכְתִיב (יחזקאל א ח) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, וְאִית פִּקּוּדִין דְּתַלְיָין מִגּוּפָא כְּעִנְּבִין דְּאַתְכָּלָא.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, וְהָא לְעִילָא הָא אוּקְמוּהָ דְּלֵית גּוּף וְלֵית גְּוִיָּה, אָמַר לֵיהּ בְּרִי, לְעָלְמָא דְאָתֵי אִתְּמַר דְּאִיהִי אִימָּא עִלָּאָה, אֲבָל לְתַתָּא אִית גּוּפָא בְעָלְמָא דֵין דְּאִיהִי שְׁכִינְתָּא תַּתָּאָה, וְגוּפָא אִיהִי אוֹרַיְיתָא, דְמִינָהּ תַּלְיָין כָּל פִּקּוּדִין, וְאִית פִּקּוּדִין דְּתַלְיָין מֵאוֹת בְּרִית, וְכַמָּה מַלְאָכִין מְמַנָּן עֲלַיְיהוּ דְאִתְקְרִיאוּ מָארֵי דְאוֹתוֹת, דְּאִתְּמַר בְּהוֹן (בראשית א יד) וְהָיוּ לְאוֹתוֹת, וַעֲלַיְיהוּ אִתְּמַר לְמֹשֶׁה (שמות ג יב) וְזֶה לְּךָ הָאוֹת, וְהַאי אִיהוּ אוֹת דְּכָל צְבָא הַשָּׁמַיִם מְמַנָּן עֲלֵיהּ, וְאִית פִּקּוּדִין דְּתַלְיָין בְּרַגְלִין, וְכַמָּה מַלְאָכִין מְמַנָּן עֲלַיְיהוּ, דְאִתְּמַר בְּהוֹן (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, וְאִתְּמַר בְּהוֹן (שם ז) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, וְהָכִי תַלְיָין כֻּלְּהוּ מִגּוּפָא, בְּשַׂעֲרָא דְתַלְיָא מֵרֵישָׁא, וְכָל נִימָא וְנִימָא אַחֲזֵי דְאִיהוּ מַלְאָךְ דְּתַלְיָא מֵרֵישָׁא.</p>\n<p>וְכָל מָאן דְּפָשַׁע בְּפִקּוּדָא, כְּאִלּוּ פָשַׁע בְּדִיּוֹקְנָא דְּמַלְכָּא, זַכָּאָה נִשְׁמָתָא דְאִיהִי בְּדִיּוֹקְנָא דְמָארֵיהּ, דִּמְקַיֵּים פִּקּוּדִין אִלֵּין, דְּמִינָהּ תַּלְיָין כָּל מַלְאָכִין אִלֵּין דְּאִתְקְרִיאוּ עִינֵי יהו\"ה אָזְנֵי יהו\"ה, וְכָל תִּקּוּנִין וַחֲיָילִין וּמַשִּׁרְיָין דְּגוּפָא דִלְעִילָא, וְכַד סָלְקַת נִשְׁמָתָא כָּל אִלֵּין חֲיָילִין סָלְקִין עִמָּהּ, וְכַד נָחֲתָא כָּל אִלֵּין חֲיָילִין נָחֲתִין עִמָּהּ, אִיהִי סֻלָּם, וְהִנֵּה מַלְאֲכֵי אלהי\"ם (בראשית כח יב) סָלְקִין וְנָחֲתִין בָּהּ, בָּהּ מַמָּשׁ, וְכַד סָלְקָא, קָלָא נָחִית בְּרוּמֵי רְקִיעִין לְכָל חֲיָילִין וּמַשִּׁרְיָין, הָבוּ יְקָרָא לְדִיּוֹקְנָא דְמַלְכָּא.</p>\n<p>מִצְוָה</p>"],[9500011262,"<p>דְכָל פִּקּוּדָא, בֵיהּ שַׁרְיָא יהו\"ה, הוּא אִשְׁתַּכַּח בְּכָל אֵבֶר וְאֵבֶר, הוּא אִשְׁתַּכַּח בְּאַרְבַּע גַּוָּונִין דְּשַׂעֲרָא וּבְאַרְבַּע גַּוָּונִין דְּעִינָא, וּבְאַרְבַּע אִדְרִין דְּאוּדְנָא, וּבְאַרְבַּע גַּוְּונֵי דְאַנְפִּין, וּבְקָלָא וּבְדִבּוּרָא וּבִקְרִיאָה וַאֲמִירָה, (ובעשיה דידין) וּבְכָל אֵבֶר וְאֵבֶר דְּגוּפָא אִיהוּ יהו\"ה, מְמַנָּא עַל כָּל מִצְוָה וּמִצְוָה, דְבֵיהּ מִצְוָה בְּאַ\"תְּ בַּ\"שׁ, מ\"צ י\"ה, פ\"ץ ו\"ה, הָא מִצְוָה יהו\"ה, מצפץ, יהו\"ה בְּאַ\"תְּ בַּ\"שׁ מצפ\"ץ. וּבְרִי, כָּל אֵבָרִין אִתְקְרִיאוּ כִּנּוּיִין לִשְׁמָא דְיהו\"ה, וְכָל מַלְאָכִין דְּתַלְיָין מֵהַהוּא אֵבֶר כֻּלְּהוּ סָלְקִין וְנָחֲתִין בִּשְׁלִיחוּתֵיהּ, וְכָל מָאן דְּקָרָא לְמַלְאָכִין וּלְכִנּוּיִין וְלָא בְהַהוּא אֵבֶר דִּמְמַנָּא עֲלֵיהּ, לֵית סָלִיק פְּעוּלָה בִידוֹי.</p>\n<p>רֵישָׁא אִיהוּ כִּנּוּיָיא דְשֵׁם אהי\"ה, וְכָל מַלְאָכִין, וּמְמַנָּן דַּהֲוַיּוֹת, מֵהָכָא תַלְיָין, וּבֵיהּ שָׁאֲלִין מַלְאָכִין אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, אי\"ה רְשִׁים בְּאהי\"ה, וְתַמָּן הי\"ה דְסָלִיק בְּחוּשְׁבַּן כ' דְּאִיהוּ כֶּתֶר, אִיהוּ רְשִׁים בְּא\"ב ג\"ד ה\"ו ז\"ח ט\"י, (אהי\"ה) אל\"ף ה\"א יו\"ד ה\"א אִיהוּ רָזָא דַעֲשַׂר אַתְוָון מֵעִילָא לְתַתָּא, הַאי אִיהוּ כֶּתֶר בְּרֵישׁ כֻּלְּהוּ שְׁמָהָן, וּלְעִילָא מִנֵּיהּ יו\"ד ה\"י וא\"ו (נ\"א וי\"ו) ה\"י, אל\"ף דל\"ת נו\"ן יו\"ד, לְעִילָא מִנֵּיהּ יו\"ד ה\"א וא\"ו ה\"א, וְכֻלְּהוּ סָלְקִין לְאַרְבְּעִין וּתְרֵין אַתְוָון, וְאִלֵּין אִינוּן אַתְוָון דְּאִתְבְּרִיאוּ בְּהוֹן שְׁמַיָּא עִלָּאִין, וְאַרְצוֹת הַחַיִּים, דְּאִלֵּין אִתְקְרִיאוּ שְׁמֵי הַשָּׁמַיִם, וּמָאן דְּבָרָא בְּהוֹן כֹּלָּא, אוּמָנָא דְכֹלָּא, עִלַּת הָעִלּוֹת מִתְעַלֶּה עַל כֹּלָּא, הוּא בְרִיךְ לְכֹלָּא, וּלְעִילָא מִכָּל בִּרְכָאָן, הֲדָא הוּא דִכְתִיב (נחמיה ט ה) וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה, וְלָא צָרִיךְ אִיהוּ בִּרְכָאָן מֵאָחֳרָא, דְלֵית עֲלֵיהּ מָאן דְּאַשְׁפַּע לֵיהּ.</p>\n<p>בְּרִי אִית פִּקּוּדִין דְּתַלְיָין בְּרַגְלִין, דְּאִתְּמַר בְּהוֹן (יחזקאל א ז) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, (שם יז) עַל אַרְבַּעַת רִבְעִיהֶם, בְּלֶכְתָּם יֵלֵכוּ, דָא אדנ\"י, דַּעֲלֵיהּ אִתְּמַר (תהלים פה יד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו, וְאִינוּן מְאַת אֲדָנִים לִמְאַת הַכִּכָּר, דְּנָחֲתִין לְמֵאָה בִרְכָאָן, וְדָא ק' מִן צְדָקָה דְאִיהִי צְלוֹתָא, צ' תִּשְׁעִים אֲמֵנִים, ד' אַרְבַּע קְדוּשׁוֹת, ק' מֵאָה בְּרָכוֹת, ה' חֲמִשָּׁה חוּמְשֵׁי תוֹרָה, וְהַאי צְדָקָה אִיהִי אִימָּא עִלָּאָה, צֶדֶק אִימָּא תַּתָּאָה, דְּאִתְּמַר בָּהּ (שם) צֶדֶק לְפָנָיו יְהַלֵּךְ, (ישעיה מא ב) צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, דָּא דִינָא וְדָא רַחֲמֵי, צֶדֶק אִימָּא תַּתָּאָה, צְדָקָה אִימָּא עִלָּאָה.</p>\n<p>כָּל פִּקּוּדִין דַּהֲלִיכָה תַּלְיָין בְּרַגְלִין, כְּגוֹן הֲלִיכָה לְבֵי כְּנִישְׁתָּא, הֲלִיכָה לִבְרִית מִילָה, הֲלִיכָה לְמֵת מִצְוָה, אוֹ לְכָל הֲלִיכָה דְמִצְוָה, וְהַאי פִּקּוּדָא דִבְּרִית מִילָה תַּלְיָא בַּצַּדִּיק, וּצְדָקָה בִּידַיִן מִן נָתֹן תִּתֵּן, כָּל פִּקּוּדִין אִינוּן מְשׁוּלָבִין אִלֵּין עִם אִלֵּין הֲדָא הוּא דִכְתִיב (שמות כו יז) מְשׁוּלָּבוֹת וכו', וְכֵן תְּפִלִּין תַּלְיָין בְּרֵישָׁא וּבִידָא שְׂמָאלָא, צִיצִית עַל כִּתְפָא, מִצְוַת לִלְמוֹד וּלְלַמֵּד בְּפוּמָא, וְכֵן צְלוֹתִין תַּלְיָין בְּפוּמָא, וְהָכִי מִצְוַת שׁוֹפָר בְּרוּחָא דְנָשֵׁיב בֵּיהּ בְּפוּמָא, וְהַהוּא רוּחָא אִתְעֲבִיד קָלָא, וְכֵן קָרְבָּנִין דְּאִינוּן רֵיחַ נִיחֹחַ לַיהו\"ה תַּלְיָין בְּחוֹטָמָא, וְאָעִי בּוּסְמִין דְּאַבְדַּלְתָּא, וְכָל דִּינִין תַּלְיָין בְּדִבּוּרָא, וְכֵן בְּעַיְינִין, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין אֵין לְדַיָּין אֶלָּא מַה שֶּׁעִינָיו רוֹאוֹת.</p>\n<p>וְאִית פִּקּוּדִין דְּתַלְיָין בִּשְׁמִיעָה כְּגוֹן קְרִיאַת שְׁמַע, אוֹ פִקּוּדִין אָחֳרָנִין, דְּאִתְּמַר בְּהוֹן אִם הִשְׁמִיעַ לְאָזְנוֹ יָצָא, וְדָא תְקִיעַת שׁוֹפָר, סוֹף סוֹף בְּאִלֵּין אֵבָרִין תַּלְיָין כָּל פִּקּוּדִין, אֶלָּא פִּקּוּדָא דְיִרְאָה וְאַהֲבָה אֵלּוּ תַלְיָין בְּמוֹחָא וְלִבָּא, וְכָל פִּקּוּדִין דַּעֲשִׂיָּה כְּגוֹן סוּכָּה וְלוּלָב תַּלְיָין בִּידַיִן, וּבְאִלֵּין תִּקּוּנִין (ס\"א פקודין) צָרִיךְ בַּר נַשׁ לְאִשְׁתְּמוֹדְעָא כָּל מַלְאָכַיָּא דְאִתְקְרִיאוּ עִינֵי יהו\"ה אָזְנֵי יהו\"ה, וְאִינוּן דְּאִתְּמַר בְּהוֹן (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת (משרתיו אש לוהט), דְּתַלְיָין בְּחוֹטָמָא, וּמַלְאָכִין דְּאִתְּמַר בְּהוֹן (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל דְּתַלְיָין בְּקָלָא, וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר (שם) דְּתַלְיָין בְּדִבּוּרָא, וּמַלְאָכִים דְּתַלְיָין בַּעֲשִׂיָּה, כְּגוֹן וִידֵי אָדָם (יחזקאל א ד), וּמַלְאָכִין דְּאִתְקְרִיאוּ אוֹתוֹת, דְּתַלְיָין בְּצַדִּיק</p>"],[9500011263,"<p>דְּאִתְּמַר בְּהוֹן (ירמיה י ב) וּמֵאוֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ, וּמַלְאָכִין דְּתַלְיָין בְּרַגְלִין, דְּאִתְּמַר בְּהוֹן (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, וְנִעִִנוּעָא דְכֻלְּהוּ יהו\"ה, וְצָרִיךְ לְמִנְדַּע נְקוּדָה דִילֵיהּ, בְּכָל אֵבֶר וְאֵבֶר נְקוּדָה דְאִתְחַיַּיב לְמַלְאָכָא דְאִיהוּ (אור) מַיִם, וּלְמַלְאָכָא דְאִיהוּ אֵשׁ, וּלְמַלְאָכָא דְאִיהוּ רוּחַ, דְּכָל נְקוּדִין אִינוּן אֶשָּׁא וְרוּחָא וּמַיָּא, מַלְכוּת עָפָר מָאנָא דְכֻלְּהוּ עִלָּאִין דְּתַלְיָין מִסְּפִירָן, וּלְתַתָּא הָכִי אִית מַלְאָכִין דְּתַלְיָין מִכִּסֵּא וּמַלְאָךְ וְאוֹפָן, דְּמִתַּמָּן נְשָׁמָה וְרוּחָא וְנַפְשָׁא, גּוּפָא מָאנָא דְכֻלְּהוּ, מִיכָאֵ\"ל אִיהוּ מַיָּא, וְאִיהוּ מְמוּנֶה עַל יַמָּא, וּבְגִין דָּא כַּד אַעֲבַר מֹשֶׁה לְיִשְׂרָאֵל בְּיַמָּא, בֵּיהּ שַׁבַּח לְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (שמות טו יא) מִ י כָ מוֹךָ בָּאֵ לִים יהו\"ה, גַּבְרִיאֵ\"ל מְמוּנֶה עַל אֶשָּׁא, אוּרִיאֵ\"ל עַל רוּחָא, רְפָאֵ\"ל עַל עַפְרָא, מֵאִלֵּין תַּלְיָין כַּמָּה רִבֵּי רִבְוָון דְּמַלְאָכַיָּא דְתַלְיָין מִנַּיְיהוּ.</p>\n<p>בְּרִי, אַגְרָא דְאִלֵּין פִּקּוּדִין דְּתַלְיָין בְּאִלֵּין אֵבָרִים, הוּא דְּמָאן דִּמְיַחֵד לְקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁכִינְתֵּיהּ בְּהַאי עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא מְזַוִּוג לֵיהּ בְּבַת זוּגֵיהּ לְהַהוּא עָלְמָא, וּמָאן דְּקָרִיב לֵיהּ לִשְׁכִינְתֵּיהּ קָרְבָּנָא, קוּדְשָׁא בְּרִיךְ הוּא מְקָרֵב לֵיהּ בְּבַת זוּגֵיהּ, וּמָאן דְּעָבִיד לֵיהּ בֵּי מַקְדְּשָׁא, הֲדָא הוּא דִכְתִיב (שם כה ח) וְעָשׂוּ לִי מִקְדָּשׁ, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ בְּהַהוּא עָלְמָא בַּיִת לְדַיְירָא (ליה) תַמָּן דְּאִיהוּ קֹדֶשׁ קֻדְשִׁין, וּמָאן דְּעָבִיד לֵיהּ סֻכָּה, קוּדְשָׁא בְּרִיךְ הוּא מְסַכֵּךְ עֲלֵיהּ בְּהַהוּא עָלְמָא, וְאַגִּין עֲלֵיהּ מִכָּל מַלְאֲכֵי חַבָּלָה כַּד נָפִיק מֵהַאי עָלְמָא וְאָזִיל לְהַהוּא עָלְמָא.</p>\n<p>וְכָל מָאן דִּמְבָרֵךְ לְקוּדְשָׁא בְּרִיךְ הוּא, וּמְקַדֵּשׁ לֵיהּ בִּצְלוֹתֵיהּ בְּהַאי עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לֵיהּ בְּהַהוּא עָלְמָא, וּמְקַדֵּשׁ לֵיהּ, וְלֵית קְדוּשָׁה פָּחוּת מֵעֲשָׂרָה, אוֹף הָכִי עָבִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עֲשָׂרָה חוּפּוֹת בְּגַן עִדֶן, דְּקִדּוּשִׁין דְּקוּדְשָׁא בְּרִיךְ הוּא עִם שְׁכִינְתֵּיהּ, אִינוּן קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וְשֶׁבַע בִּרְכָאָן דִּילֵיהּ אִינוּן בִּקְרִיאַת שְׁמַע, בַּשַּׁחַר שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעִִרֶב שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ, הָא שֶׁבַע, וְיִחוּד דִּילֵהּ שְׁמַע יִשְׂרָאֵל, וְהָכִי קוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לֵיהּ וּלְכַלָּה דִילֵיהּ, וּמְקַדֵּשׁ לֵיהּ עִמָּהּ בִּקְדוּשָׁה, וּמְיַיחֵד תַּרְוַיְיהוּ, וְכֹלָּא מִדָּה כְּנֶגֶד מִדָּה.</p>\n<p>סוֹף סוֹף בְּכָל מַה דְּאִשְׁתַּדַּל בַּר נַשׁ בְּפִקּוּדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִינֵיהּ וּבְגִין שְׁכִינְתֵּיהּ, הָכִי אִשְׁתַּדַּל קוּדְשָׁא בְּרִיךְ הוּא בְּגִין בַּר נַשׁ וּבַת זוּגֵיהּ בְּהַהוּא עָלְמָא, זַכָּאָה חוּלָקֵיהּ מָאן דְּיִשְׁתַּדַּל לְמֶעֱבַד רְעוּתֵיהּ, דְּלֵית פּוּמָא יָכִיל לְמֵימַר אַגְרָא דִילֵיהּ בְּהַהוּא עָלְמָא דְאִיהִי לְדָרֵי דָרִין, בַּר נַשׁ עָבִיד לְקוּדְשָׁא בְּרִיךְ הוּא רְעוּתֵיהּ דְּאִיהוּ לְפוּם שַׁעִִתָּא בְהַאי עָלְמָא, וּבָנֵי לֵיהּ בִּנְיָינָא בֵּיהּ, קוּדְשָׁא בְּרִיךְ הוּא בָנֵי לֵיהּ לְבַר נַשׁ בְּעָלְמָא דִילֵיהּ בִּנְיָינָא לְדָרֵי דָרִין, זַכָּאָה מָאן דְּשַׁרְיָא לֵיהּ בְּכָל אֵבֶר וְאֵבֶר דִּילֵיהּ לְמֶעֱבַד לֵיהּ אֲתַר לְשַׁרְיָא תַמָּן, וּלְאַמְלָכָא לֵיהּ בְּכָל אֵבֶר וְאֵבֶר, דְּלָא יְהֵא בֵּיהּ אֵבֶר פָּנוּי מִנֵּיהּ, דְּאִם חָסֵר אֵבֶר חַד דְּלָא שַׁרְיָא עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין הַהוּא אֵבֶר אִתְחַזַּר לְעָלְמָא בְּגִלְגּוּלָא, עַד דְּאִשְׁתַּלִּים בְּאֵבָרִין דִּילֵיהּ, לְמֶהֱוֵי כֻּלְּהוּ שְׁלֵמִין בְּדִיּוֹקְנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִם חָסֵר חַד לַאו אִיהוּ בְּצַלְמוֹ דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>פּוּמָא עֲקִימָא לָא שַׁרְיָא בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ מוּם, כָּל שֶׁכֵּן אִם דִּבּוּרָא דִילֵיהּ עָקִים, עֲלֵיהּ אִתְּמַר (קהלת א טו) מְעְִוָּת לֹא יוּכַל לִתְקוֹן, פִּימָא וְלִבָּא אִינוּן לָקֳבֵל אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה, קָלָא וְדִבּוּר דְּנָפִיק מִתַּרְוַיְיהוּ אִיהוּ ו\"ה, צָרִיךְ לְאַפָּקָא לֵיהּ בִּדְחִילוּ וּרְחִימוּ דְי\"ה, וְאִם לַאו, לָא שַׁרְיָא תַמָּן יהו\"ה.</p>\n<p>שִׂפְוָון אֲרִיכִין מִסִּטְרָא דְאַנְשֵׁי חַיִל, רְחָבִין מִסִּטְרָא דְיִרְאֵי אלהי\"ם, שִׂפְוָון בֵּינוֹנִיִּים מִסִּטְרָא דְאַנְשֵׁי אֱמֶת, זְעִירָן בְּעִגּוּלָא מִסִּטְרָא דְשׂוֹנְאֵי בָצַע, כַּמָּה קָלִין וְדִבּוּרִין נָפְקִין מִפִּימָא מִיָּד דְּנָפְקִין מִפּוּמוֹי כַּמָּה מַלְאָכִים דְּאִתְקְרִיאוּ עוֹפִין נָטְלִין מִלּוּלִין דְּפִימָא. חָמֵשׁ תִּקּוּנִין אִינוּן בְּפִימָא, דְאִתְּמַר בְּסֵפֶר יְצִירָה, אחה\"ע בומ\"ף גיכ\"ק דטלנ\"ת זסשר\"ץ, וּבְהוֹן (דברים כז ו) אֲבָנִים</p>"],[9500011264,"<p>שְׁלֵמוֹת תִּבְנֶה לְקוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה צְלוֹתִין וּפוּלְחָנִין, וַעֲלַיְיהוּ אָמַר יַעֲקֹב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא (בראשית כח יא), וַיִּשְׁכַּב וְיֵ\"שׁ כ\"ב אַתְוָון בַּמָּקוֹם הַהוּא, יֵ\"שׁ (משלי ח כא) לְהַנְחִיל אוֹהֲבַי יֵשׁ, כ\"ב בְּךָ יְבָרֵךְ יִשְׂרָאֵל (בראשית מח כ), בְּךָ בָּטְחוּ אֲבוֹתֵינוּ (תהלים כב ה), כִּי בְךָ אָרוּץ גְּדוּד (שם יח ל), וּבְךָ בָּחַר יהו\"ה (דברים ז ו), אֲשֶׁר נִשְׁבַּעִִתָּ לָהֶם בָּךְ (שמות לב יג), נָגִילָה וְנִשְׂמְחָה בָּךְ (שיר א ד), בְּהוֹן בָּ רוּךְ כְּ בוֹד יהו\"ה מִמְּקוֹמוֹ (יחזקאל ג יב).</p>\n<p>דִּיקְנָא, בְּסֵפֶר בֶּן סִירָא, קַלִּיל דַּקָּן קוּרְטַמָּן, עַב דַּקָּן אִיהוּ בְרִבּוּיָא דְלֵיחָא בְּלַחוּתָא דִילֵיהּ, וּבְגִין דָּא אִיהוּ פַּתְיָא שַׁטְיָא, (אמר רבי שמעון) מָאן דְּלֵית לֵיהּ דִּיקְנָא בְאַנְפּוֹי וּבְפִימוֹי אֶלָּא זְעִיר, הוּא פִּקְחָא (פקיעא), דְּמָרָה יְרוֹקָא אִיהִי אִתְגַּבְּרַת עֲלֵיהּ, וְלֵית בֵּיהּ לַחוּתָא כְלָל, דִּיקְנָא בֵינוֹנִית דָּא אִיהוּ אִישׁ תָּם, דַּעִִתֵּיהּ שְׁלִים, מָאן דְּלֵית לֵיהּ דִּיקְנָא בְאַנְפּוֹי כְּלָל, מָרָה קְרִירָא וִיבֵשָׁתָא אִתְגַּבְּרַת עֲלוֹי, לֵית בֵּיהּ לֵחוּת וַחֲמִימוּת כְּלָל, מָארֵי דַעֲצִיבוּ אִיהוּ, עוֹבָדוֹי כְּאִתְּתָא.</p>\n<p>תָּא חֲזִי אִית בְּנֵי נָשָׁא דִמְמַלְּלָן בְּנִעִִנוּעָא דְעַיְינִין, וְאָחֳרָנִין בְּנִעִִנוּעָא דִיְדַיִן, וְאָחֳרָנִין בְּנִעִִנוּעָא דְרֵישָׁא, וְאָחֳרָנִין בְּנִעִִנוּעָא דְגוּפָא, וְאָחֳרָנִין בְּנִעִִנוּעָא דְרַגְלִין, דָּא אִיהוּ דִּבְכָל אֲתַר דְּנִשְׁמָתֵיהּ בֵּיהּ, תַּמָּן עָבִיד נִעִִנוּעָא יַתִּיר בְּהַהוּא אֲתַר.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, וְכִי נִשְׁמָתָא לָא אִיהִי בַּאֲתַר יְדִיעָא בְלִבָּא, וְאִתְפַּשְׁטוּתָהּ בְּכָל אֵבָרִין דְּלִבָּא, אָמַר לֵיהּ בְּרִי, וְהָא כְתִיב בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, כְּפוּם עוֹבָדוֹי דְּבַר נַשׁ הָכִי נָפִיק לָהּ מֵאַתְרָהָא, וְנָחִית לָהּ לְבַר מֵאַתְרָהָא, כְּגַוְונָא דִשְׁכִינְתָּא דְאִתְּמַר בָּהּ (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם, וּתְיוּבְתָּא שְׁלֵימָתָא, מָאן דְּאָתִיב לָהּ לְאַתְרָהָא דַהֲוַת בְּקַדְמֵיתָא, דִּבְזִמְנָא דְנִשְׁמָתָא אִיהִי בְּלִבָּא אִתְקְרִיאַת מַטְרוֹנִיתָא, כַּד נָפְקַת מִלִּבָּא לָא אִתְקְרִיאַת מַטְרוֹנִיתָא, כְּפוּם חוֹבוֹי דְּבַר נַשׁ הָכִי נָחִית לָהּ מִדַּרְגָּא לְדַרְגָּא וּמֵאֵבֶר לְאֵבֶר, עַד דְּנָחִית לָהּ לְרַגְלוֹי, וּכְפוּם זַכְוָון דִּילֵיהּ הָכִי סְלִיקַת, עַד דִּסְלִיקַת לְאַתְרָהּ, וּבְגִין דָּא בְּכָל אֲתַר דְּנָחֲתַת, תַּמָּן עָבְדַת תְּנוּעָה יְתֵרָה בְּהַהוּא אֵבֶר יַתִּיר מֵאַחֲרָנִין.</p>\n<p>שִׁרְטוּטִין דִּיְדַיִן אַשְׁכַּחְנָא דְאִינוּן כְּעַנְפִין דְּאִילָנָא, מִנְּהוֹן אֲרִיכִין, מִנְּהוֹן קְצָרִין, מִנְּהוֹן מְשַׁלְּבָן, מִנְּהוֹן בְּעִגּוּלָא זְעִירִין.</p>\n<p>אַשְׁכַּחְנָא בְּרָזָא דְמַתְנִיתָא, דְּטוּרִין רַמָּאִין עֲמִיקִין, גּוֹ סוּסְפִיתָא, קוּנְטְרָא, קִטְרָא דְקִטְרִין, תַּמָּן הֲוָה חַד אוּכְמָא בְּלָא רַגְלִין, מְפַכְפֵּךְ הִפּוּכִין, גּוּף טְרִיף, כַּד הֲוָה יָתִיב אָזִיל, כַּד הֲוָה אָזִיל יָתִיב, כַּד הֲוָה אָזִיל מְהַפֵּךְ טוּרִין, כַּד הֲוָה יָתִיב מְעַקֵּר טִנָּרִין, מָאן דְּאַעֲרַע בֵּיהּ טְרִיף לֵיהּ וְקָטִיל לֵיהּ, וְלָא אַהֲנֵי, זַכָּאָה אִיהוּ מָאן דְּאִסְתַּמַּר מִנֵּיהּ.</p>\n<p>כָּל דִּיּוֹקְנִין דִּבְנֵי עָלְמָא בֵּיהּ רְשִׁימִין, כָּל צִיּוּרִין בֵּיהּ מְצוּיָירִין, כָּל גַּוָּונִין בֵּיהּ מְרַקְמָן, דְּסִטְרִין אָחֳרָנִין כַּמָּה עַנְפִין תַּלְיָין מִנֵּיהּ, דְּשַׁרְבִיטִין דְּנוּרָא מְלַהֲטָא דְזָרִיק, כַּמָּה גַלְגַּלִין סַחֲרִין לֵיהּ, כֻּלְּהוּ מַלְיָין עַיְינִין דְּגוּמְרִין דְּנוּרָא מְלַהֲטִין, מִנְּהוֹן מִזְדַּעִִזְעָאן חֲיָילִין וּמַשִּׁרְיָין, לֵית בְּהוֹן רַחֲמָנוּתָא כְלָל, זַכָּאָה אִיהוּ מָאן דְּאִסְתַּמַּר מִנֵּיהּ.</p>\n<p>בֵּיהּ רְשׁוּמִין דִּיּוֹקְנִין דְּחֵיוָון בִּישִׁין, דְּאִינוּן מַזָּל אַרְיֵה, מַזָּל שׁוֹר מוּעָד, מַזָּל נֶשֶׁר, מַזָּל אָדָם, כָּל נוּנֵי יַמָּא מְסָאֲבִין בֵּיהּ מְצוּיָירִין, וְעוֹפִין וְחֵיוָון דְּסִטְרָא דִמְסָאֲבוּ בֵּיהּ רְשִׁימִין וּמְצוּיָירִין, דְּכֻלְּהוּ מוּעָדִין לְקַלְקֵל, כַּמָּה שַׁרְבִיטִין וְנִצּוֹצִין אִזְדְּרִיקוּ מִנֵּיהּ עַל בְּנֵי נָשָׁא, וְאִינוּן נִשְׁמָתִין דְּחַיָּיבַיָּא, דְקָא מַרְכִּיבִין עַל בְּנֵי נָשָׁא, מִנְּהוֹן דְּכוּרִין מִנְּהוֹן נוּקְבִין, לְזִמְנִין מַרְכִּיבִין נוּקְבִין עַל דְּכוּרִין, לְזִמְנִין דְּכוּרִין עַל נוּקְבִין, כַּד אִזְדְּרִיקוּ לָא אִזְדְּרִיקוּ לַאֲתַר יְדִיעָא, אֶלָּא כָל חַד בַּאֲתַר דְּלָא</p>"],[9500011265,"<p>מִינֵיהּ. וַוי לוֹן לְאִינוּן טִיפִּין, דְּאִינוּן נִצּוֹצִין וְשַׁרְבִיטִין אַעִִרַעוּ בֵּינַיְיהוּ, אִלֵּין שַׁטְיָין דְּלָא מִסְתַּמְּרִין גַּרְמַיְיהוּ בְזִוּוּגָא דִלְהוֹן, מַרְכִּיבִין לוֹן בְּהוֹן, וְאִתְעֲבִיד אִילָנָא דְעִץ הַדַּעַת טוֹב וָרָע.</p>\n<p>נוּקְבָא אִית לֵיהּ דְּאִתְקְרִיאַת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, דְּכָל גִּלְגּוּלִין דְּנִשְׁמָתִין בֵּיהּ מִתְהַפְּכִין, לְזִמְנִין מַטֶּה לְנָחָשׁ, לְזִמְנִין נָחָשׁ לַמַּטֶּה, וְהָכִי מִתְהַפְּכָא דְּכוּרָא לְנוּקְבָא, נוּקְבָא לִדְכוּרָא, וְאִלֵּין דְּהָפְכִין לְשֻׁלְחָנָם גָּרְמִין הֲפוּכִין אִלֵּין. הֲפַכְפַּךְ דְּכֻלְּהוּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת מֵרָע לְטוֹב וּמִטָּב לְבִישׁ, וְהָכָא רָזָא דְצַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ, וְדָא אִיהוּ גוֹלֵל אוֹר מִפְּנֵי חֹשֶׁךְ וְחֹשֶׁךְ מִפְּנֵי אוֹר, מָאן דְּאַלִּים גָּבַר, כַּד אַלִּים נוּקְבָא עַל דְּכוּרָא בְגִלְגּוּלָא דִילֵיהּ לֵית לֵיהּ דִּיקְנָא, עָקָר הוּא, עוֹבָדוֹי כִּבְעִירָא, תּוֹעִבָה אִיהוּ.</p>\n<p>וְהָכִי אִינוּן מִתְהַפְּכִין דַּרְגִּין מִדִּינָא לְרַחֲמֵי וּמֵרַחֲמֵי לְדִינָא, כְּגַוְונָא דְסִטְרָא דְּדַכְיוּ הָכִי מִתְהַפְּכִין מִסִּטְרָא דִמְסָאֲבוּ, אִם אַלִּים גָּבַר, וְהוּא יִהְיֶה פֶּרֶא אָדָם יָדוֹ בַכֹּל (בראשית טז יב), וְאִם אַלִּימָא נוּקְבָא יַד כֹּל בּוֹ, אִית שָׁלְטָנוּתָא לְבִישׁ וְאִית שָׁלְטָנוּתָא לְטָב, אִית שָׁלְטָנוּתָא דְשַׁלִּיט (סליק) דָּא עַל דָּא, וְאִית שָׁלְטָנוּתָא דְנִיאוּפִין, כַּד שַׁלִּיט זוֹנָה עֲלֵיהּ, כֻּלְּהוּ בְעִירָן אַתְיָין עֲלֵיהּ, כְּמָה דְאַשְׁכַּחְנָא בִּנְבוּכַדְנֶאצַּר, דְּאִתְּמַר בֵּיהּ (דניאל ד כב) וּמִבְּנֵי אֲינָשָׁא טְרִיד וְעִשְׂבָּא כְתוֹרִין לֵיהּ יְטַעֲמוּן עַד דְּשִׁבְעָה עִדָּנִין יַחְלְפוּן עֲלוֹהִי, דְאִינוּן שִׁבְעָה כֹּכְבֵי דִילֵיהּ, יִתְחַלְפוּן עֲלוֹהִי מִדְּכוּרִין לְנוּקְבִין, וּבְגִין דָּא כַּד גִּלְגּוּלָא דְנוּקְבָא קָא רְכִיבַת עֲלֵיהּ, עוֹבָדוֹי אִיהוּ כְּאִתְּתָא, כַּד מַלִּיל מַלִּיל בִּפְתִיחוּ דִיְדִין, וְקָלֵיהּ וְדִבּוּרֵיהּ וְכָל עוֹבָדוֹי כְּאִתְּתָא, תּוֹעִבָה אִיהוּ, וּבְגִין דָּא מְבָרְכִין יִשְׂרָאֵל עַמָּא קַדִּישָׁא, בָּרוּךְ אַתָּה יהו\"ה אלהינ\"ו מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי אִשָּׁה.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, שְׁמַעִִנָא דְאִית נַפְשָׁא דְמַרְכִּיבִין לָהּ בְּכַלְבָּא, וּבְגִין דָּא אָמַר דָּוִד (תהלים כב כא) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי, מַאי יְחִידָתִי דָא נִשְׁמָתָא, וְכִי נִשְׁמָתָא אִתְרְכִיבַת בְּכֶלֶב, אָמַר לֵיהּ בְּרִי אִין, בְּהַהוּא עָרֵל נָחָשׁ הַקַּדְמוֹנִי דְפַתִּי לְחַוָּה וְלִבְנֵי נָשָׁא, דָא אִיהוּ כֶּלֶב, וְדָא יֵצֶר הָרָע דְּאָתָא בְהַהוּא עָלְמָא מוּרְכָּב עֲלֵיהּ לְקַבְּלָא עוֹנְשֵׁיהּ.</p>\n<p>וְאִית נִשְׁמָתִין אָחֳרָנִין דְּקָא אַתְיָין בְּגִלְגּוּלָא בְכַמָּה חֵיוָן, דְּאִתְקְרִיאוּ מַזָּל אַרְיֵה, מַזָּל שׁוֹר, מַזָּל נֶשֶׁר, מַזָּל בְּתוּלָה, מַזָּל עַקְרָב, מַזָּל טָלֶה, מַזָּל מַאֲדִים, מַזָּל נָחָשׁ, מַזָּל דָּגִים, כְּמָה דְאַשְׁכַּחְנָא בִתְרֵין עֲשַׂר שִׁבְטִין דְּאִתְמְתִילוּ לְחֵיוָון, דָּא לְאַרְיֵה גּוּר אַרְיֵה יְהוּדָה (בראשית מט ט), יוֹסֵף בְּכוֹר שׁוֹרוֹ, יִשָּׂשכָר חֲמוֹר גָּרֶם, יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ, בִּנְיָמִין זְאֵב יִטְרָף, וּבְרִי כָּל דָּא רָזָא דְגִלְגּוּלָא דְּיֵצֶר הָרָע, אִית לְמָאן דְּאִיהוּ דַמְיָא לְאַרְיֵה, וְאִית לְמָאן דְּאִיהוּ דַמְיָא לְחִוְיָא, וְאִית לְמָאן דְּאִיהוּ דַמְיָא כַּחֲמוֹר, לְכָל בִּרְיָין אִשְׁתַּנִּי כְּפוּם עוֹבָדֵיהוֹן, וּכְפוּם שַׁעִִתָּא דְאִתְעֲבִידוּ בָהּ.</p>\n<p>וְעִם כָּל דָּא זַכָּאָה נִשְׁמָתָא דְשַׁלִּיט עֲלֵיהּ וְרָכִיב עֲלֵיהּ, כְּבַר נַשׁ דְּרָכִיב עַל סוּסְיָא אוֹ עַל חֲמָרֵיהּ, וַוי לֵיהּ לְמָאן דְּחִוְיָא שַׁלִּיט עֲלֵיהּ, הַאי אִתְקְרֵי רָשָׁע גָּמוּר, וּמָאן דְּאִיהוּ שַׁלִּיט עֲלֵיהּ אִיהוּ אִתְקְרֵי צַדִּיק גָּמוּר, וַעֲלֵיהּ אִתְּמַר (ישעיה מג ד) וְאֶתֵּן אָדָם תַּחְתֶּךָ, אָדָם בְּלִיַּעַל אִישׁ אָוְן, וּלְאֻמִּים תַּחַת נַפְשֶׁךָ (שם), דְּכַד בַּר נַשׁ אִיהוּ שַׁלִּיט עַל יִצְרֵיהּ, הָכִי אִיהוּ שַׁלִּיט עַל כָּל שָׂנְאוֹי, וְאִם יִצְרֵיהּ שַׁלִּיט עֲלֵיהּ שָׂנְאוֹי שָׁלְטִין עֲלֵיהּ.</p>\n<p>וּבְרִי אַשְׁכַּחְנָא בְּמַתְנִיתִין, בְּרָזָא דְשִׁרְטוּטִין וְצִיּוּרִין וְגַוָּונִין, בְּסִתְרָא דְרָזִין טְמִירָא דִטְמִירִין, דְּאָדָם דִּבְּרִיאָה דְאִיהוּ קַדְמוֹן לְכָל קְדוּמִים רָכִיב בְּאַרְיֵה, סָטָא לִימִינָא, וְעָבִיד שִׁרְטוּטִין, דְּאִינוּן אוֹרְחִין וּשְׁבִילִין דְּיַמָּא דְאוֹרַיְיתָא, דַּעֲלַיְיהוּ אִתְּמַר (שם מג טז) הַנּוֹתֵן בַּיָּם דָּרֶךְ וּבְמַיִם עַזָה נְתִיבָה, אָדָם דִּיצִירָה רָכִיב בְּשׁוֹר וְסָטָא לִשְׂמָאלָא, וְנָטִיל אֶשָּׁא בְּפִימֵיהּ</p>"],[9500011266,"<p>וְצִיֵּיר צִיּוּרִין, אָדָם דַּעֲשִׂיָּה רָכִיב בְּנֶשֶׁר וְנָטִיל רוּחָא בְּפוּמוֹי וְסָטָא לְמִזְרָח בְּאַנְפּוֹי, וְעָבַד גַּוָּונִין בְּעַיְינִין בְּאַנְפִּין. אָמַר לֵיהּ מָאן אָדָם דִּבְּרִיאָה וִיצִירָה וַעֲשִׂיָּה הָכָא, אָמַר לֵיהּ בְּרִי הַאי אִיהוּ דְאִתְּמַר בֵּיהּ וְאָדָם אַיִן, וּמוֹתַר הָאָדָם מִן הַבְּהֵמָה אָיִן (קהלת ג יט), וְאִיהוּ אָדָם דִּבְּרִיאָה, דִבְהַאי בָּרָא עִלַּת הָעִלּוֹת כָּל בִּרְיָין, אָדָם דִּיצִירָה חָכְמָה, עֲלֵיהּ אִתְּמַר (איוב כח כ) וְהַחָכְמָה מֵאַיִן תִּמָּצֵא, דְאִיהוּ י' מֵאַיִן, דְּבֵיהּ צִיֵּיר כָּל צִיּוּרִין דְּעָלְמָא, בֵּיהּ צִיֵּיר עַיְינִין וְחוֹטָמָא נוּקְבִין דְּחוֹטָמָא נוּקְבִין דְּאוּדְנִין וּפִימָא, כָּל נְקוּדִין וְצִיּוּרִין דְּאִינוּן עִזְקָא לְאָת י', וְאִיהִי בְהוֹן כְּאַבְנָא בְרֵישׁ עִזְקָא, אָדָם דַּעֲשִׂיָּה דָא ן' מֵאַיִן, בִּינָה, אִיהִי אֵם כָּל חָי, מַעֲשֵׂה בְרֵאשִׁית, בָּהּ אִתְעֲבִידוּ כָּל עוֹבָדִין דְּעוֹבָדָא דִבְּרֵאשִׁית, וְגַוָּונִין.</p>\n<p>אַרְיֵה דְבֵיהּ עָבִיד שִׁרְטוּטִין, דָּא חֶסֶד יְמִינָא, שׁוֹר דְּבֵיהּ צִיֵּיר צִיּוּרִין, דָּא גְבוּרָה, נֶשֶׁר בְּאֶמְצָעִיתָא, דְבָהּ אִשְׁתְּמוֹדְעוּ כָּל גַּוָּונִין, וְדָא תִּפְאֶרֶת, שַׁפִּירוּ דְכֹלָּא, דְכָל גַּוָּונִין נָהֲרִין בֵּיהּ, וְנֶצַח הוֹד יְסוֹד אִינוּן לָקֳבֵל תְּלַת אֲבָהָן.</p>\n<p>כָּל שִׁרְטוּטִין וְצִיּוּרִין וְעוֹבָדִין, אִינוּן אִתְחַזְיָין בִּשְׁכִינְתָּא תַּתָּאָה, דְּאִיהִי דְמוּת אָדָם, וַעֲלָהּ אִתְּמַר (הושע יב יא) וּבְיַד הַנְּבִיאִים אֲדַמֶּה, כֹּלָּא אִתְחֲזִי בָּהּ לְתַתָּאָה, וְלֵית בַּר נַשׁ יָכִיל לְמִנְדַּע וּלְאִסְתַּכָּלָא בְּשִׁרְטוּטִין וְצִיּוּרִין וְגַוָּונִין דִּלְעִילָא אֶלָּא בָּהּ, וּבְגִינָהּ אִתְּמַר (שמות לג כג) וְרָאִיתָ אֶת אֲחוֹרָי, אֲבָל לְעִילָא מִינָהּ וּפָנַי לֹא יֵרָאוּ (שם), דְלֵית בִּרְיָה דִיְכִילָא לְאִסְתַּכָּלָא תַּמָּן, בִּתְקִיפוּ דְצִחְצוּחִים, וּנְהוֹרָא דְגַוָּונִין, דַּעֲלַיְיהוּ אִתְּמַר (שם כ) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, וְכִי בְאַנְפּוֹי דְּמֹשֶׁה לָא הֲווֹ יָכְלִין לְאִסְתַּכְּלָא, כָּל שֶׁכֵּן בְּעַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ כְלִיל כָּל שִׁרְטוּטִין וְצִיּוּרִין וְגַוָּונִין, וּבֵיהּ נָהֲרִין כֻּלְּהוּ, וְאִיהוּ כְּלִיל בְּכֻלְּהוּ (כלל דכלהו).</p>\n<p>וּבְגִין דָּא אִתְקְרֵי ש, כְּלִיל תְּלַת עַנְפִין דְּאִינוּן תְּלַת אֲבָהָן, וְדָא אִיהוּ רָזָא וְשָׁכַבְתִּי עִם אֲבוֹתַי (בראשית מז ל), וּבְגִין דָּא מַלְכוּת אִיהִי בַּ\"ת יְחִידָה, שַׁבָּ\"ת, דְּבָהּ אִתְגַּלְיָין כָּל גַּוָּונִין וְשִׁרְטוּטִין וְצִיּוּרִין לִבְנֵי נָשָׁא, וּבָהּ יָכְלִין לְמִנְדַּע כָּל מַה דִּלְעִילָא, וְלָא בַאֲתַר אָחֳרָא, דְּאִיהִי כְּגַוְונָא דְאַסְפַּקְלַרְיָאָה, דְאִשְׁתְּמוֹדָע בָּהּ פַּרְצוּפִין דְּאַנְפִּין. שִׁרְטוּטִין דִיְדִין אִינוּן אִילָנָא דְחַיֵּי, כַּד אִינוּן פְּתִיחָן לְמֶעֱבַד טִיבוּ, כְּשׁוֹשַׁנָּה דְאִיהִי פְּתִיחָא לְקַבָּלָא, וּלְאַרָקָא רֵיחָא טָבָא.</p>\n<p>וְאִית עוֹבָדִין טָבִין דְּאִינוּן אִיבָּא לְאִילָנָא, כְּגוֹן צְדָקָה, וְכַמָּה פִּקּוּדִין דְּתַלְיָין בִּיְדִין לְמֶעֱבַד בְּהוֹן טִיבוּ, יְדִין דְּלָא אִתְחַזְיָין בְּהוֹן שִׁרְטוּטִין, לַאו אִיהוּ דִיּוֹקְנָא מֵאִילָנָא דְחַיֵּי, וְאִית שִׁרְטוּטִין בְּאֹרַח מֵישַׁר מִסִּטְרָא דְיִצְרָא טָבָא, וְאָחֳרָנִין מִסִּטְרָא דְיִצְרָא בִישָׁא, דְּאִלֵּין פְּתִיחִין לְטִיבוּ, וְאִלֵּין פְּתִיחִין לְבִישׁ, וְאִית דְּמוּרְכָּבִין אִלֵּין בְּאִלֵּין, אִילָנָא דְטוֹב עִם רָע, וְרָע עִם טוֹב, אִלֵּין אִינוּן דִּיְדֵיהוֹן זִמְנִין עָבְדִין טָב וְזִמְנִין עָבְדִין בִּישׁ, יְדַיִן דְּעָבְדִין טִיבוּ כָּל יוֹמוֹי, אִלֵּין אִינוּן מֵאִילָנָא דְחַיֵּי, וְאִלֵּין דְּעָבְדִין טוֹב וָרָע, אִלֵּין אִינוּן מֵאִילָנָא דְטוֹב וָרָע, וִידַיִן דְּכָל יוֹמוֹי עָבְדִין בְּהוֹן עוֹבָדִין בִּישִׁין, דָּא אִיהוּ מֵאִילָנָא דְאִתְּמַר בֵּיהּ (ישעיה ה ב) וַיְקַו לַעֲשׂוֹת עֲנָבִים וַיַּעַשׂ בְּאוּשִׁים, וְאִית אִילָנָא דְלָא עָבִיד פֵּירִין, וְאִיהוּ עָקָר, אִלֵּין אִינוּן דְּלֵית בְּהוֹן עוֹבָדִין טָבִין, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין לֹא הַמֶּדְרָשׁ עִקָּר אֶלָּא הַמַּעֲשֶׂה הוּא הָעִקָּר, וּבְגִין דָּא עִקָּרָא דְשִׁרְטוּטִין וְצִיּוּרִין וְגַוָּונִין אִיהוּ עוֹבָדָא.</p>\n<p>בַּת עַיִן אִיהִי אַסְפַּקְלַרְיָאָה, אַף עַל גַּב דְּאִיהִי אוּכְמָא, בָּהּ אִתְחַזְיָין כָּל פַּרְצוּפִין וְגַוָּונִין דְּאַנְפּוֹי דְּבַר נַשׁ, כַּד סָתִים בַּר נַשׁ עִינָא אִיהוּ מַחֲשָׁבָה סְתִימָא, א קָמֵ\"ץ אִיהוּ, קָמֵ\"ץ סָתִים, עִינָא אִיהוּ י' בְּעִגּוּלָא דִילֵיהּ, ו' בְּאוּרְכָא דִילֵיהּ, כַּד אִתְפַּתַּח אִתְפַּתַּח בְּה' תַּתָּאָה, כַּד נָהִיר נָהִיר בְּה' עִלָּאָה, בְּהַהוּא זִמְנָא דְאִתְפַּתַּח בְּה' עִלָּאָה אִתְּמַר</p>"]]});
